-- quest.lua
local ADDON_NAME = ...
OneWoW.CatalogData:Defer(ADDON_NAME, 'quest', function()
return {
[10938] = {id=10938,name="Darkmoon Blessings Deck",level=1,requiredLevel=0,faction="both",expansion=5,zoneID=5861,mapID=407,description="Now that you have gathered all of the Blessings cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight. On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\" You have heard that the entrance to this faire appears near Mulgore and Goldshire every month.",rewardItems={31856},starts={{npcID=14847}},ends={{npcID=14847}},questType="standard"},
[25703] = {id=25703,name="Atrocities",level=15,requiredLevel=15,faction="both",expansion=5,zoneID=4,mapID=17,description="The Bloodwash naga and the Rockpool murloc have lived among one another for as long as we could remember. We have always had our differences, but never provoked one another. Why, then, would they turn on us? Neptool looks over his shoulder at his former villagers.> You see what they do now? They enslave us, sacrifice us, force us to fight one another. I will stop them, ... and you will be my weapon.",rewardGold=105000,rewardXP=2615,starts={{npcID=41354}},ends={{npcID=41354}},coords={x=0.71,y=0.598,source="quest_giver",mapID=17},questType="standard"},
[25707] = {id=25707,name="The Future of the Rockpool",level=15,requiredLevel=15,faction="none",expansion=5,zoneID=4,mapID=17,description="The Rockpool tadpoles left upon this crate appear tired, scared, and nearly dried out. They need to be taken to the water, and quickly. Perhaps if you can drag this crate across the beach and into the Forbidden Sea, far off the coast of the Red Reaches, then they will have a chance of escaping, and the Rockpool murlocs may live on...",rewardGold=105000,rewardXP=2090,starts={{npcID=41402}},ends={{npcID=41402}},questType="standard"},
[32700] = {id=32700,name="Quest Reward Summary: PvP Stage 1-5",level=1,requiredLevel=1,faction="alliance",expansion=5,zoneID=6507,mapID=504,rewardGold=456000,rewardXP=400,rewardItems={95622},rewardCurrencies={{id=738,amount=19}},questType="pvp"},
[32701] = {id=32701,name="Quest Reward Summary: PvE Stage 0-2",level=1,requiredLevel=1,faction="alliance",expansion=5,zoneID=6507,mapID=504,rewardGold=456000,rewardXP=400,rewardItems={95622},rewardCurrencies={{id=738,amount=27}},questType="pvp"},
[32703] = {id=32703,name="Quest Reward Summary: PvE Stage 3",level=1,requiredLevel=1,faction="alliance",expansion=5,zoneID=6507,mapID=504,rewardGold=456000,rewardXP=400,rewardItems={95622},rewardCurrencies={{id=738,amount=30}},questType="pvp"},
[32704] = {id=32704,name="Quest Reward Summary: PvE Stage 4-5",level=1,requiredLevel=1,faction="alliance",expansion=5,zoneID=6507,mapID=504,rewardGold=456000,rewardXP=400,rewardItems={95622},rewardCurrencies={{id=738,amount=30}},questType="pvp"},
[32706] = {id=32706,name="Allies in the Shadows",level=32,requiredLevel=32,faction="alliance",expansion=5,zoneID=6507,mapID=504,description="The Shado-Pan arrived here before we did, and they are already at work undermining the Thunder King's forces. I want you to meet with Taran Zhu , the leader of the Shado-Pan, and offer your services on behalf of the Kirin Tor. I doubt he is truly in need of the aid, but the gesture holds importance in itself.",objectivesText="Speak to Taran Zhu in Bleak Hollow.",rewardGold=137400,rewardXP=4385,starts={{npcID=67992},{npcID=70370}},ends={{npcID=70160}},coords={x=0.632,y=0.722,source="quest_giver",zoneID=6507},questType="standard"},
[32707] = {id=32707,name="Secrets in the Isle of Thunder",level=32,requiredLevel=32,faction="both",expansion=5,zoneID=6507,mapID=504,description="I do have one thing I would ask of you, . We've gotten our hands on a powerful ritual stone that the Shan'ze mogu use to beckon their allies into battle, but we need more than one to perform their rituals. If you come upon three of these stones, bring them back to me. We can gather our forces and use these stones to beckon some of Lei Shen's most powerful servants directly into our traps.",objectivesText="Recover 3 Shan'ze Ritual Stones . These stones are very rare, and may take some time to gather. Progress: Have you found the stones I spoke of?",rewardGold=274800,rewardXP=5480,starts={{npcID=70160}},ends={{npcID=70160}},coords={x=0.514,y=0.46,source="quest_giver",zoneID=6507},questType="standard"},
[32708] = {id=32708,name="Setting the Trap",level=32,requiredLevel=32,faction="both",expansion=5,zoneID=6507,mapID=504,description="Take these 3 ritual stones to the location I have marked on your map. There, you will find a Shan'ze ritual object that you can use to beckon one of their powerful allies. You will need capable friends at your side for this trap to work. Do not go alone, for these will be some of the Thunder King's most powerful servants. When your enemy shows itself, show no mercy.",objectivesText="Use 3 Shan'ze Ritual Stones to beckon a Champion of the Thunder King, and then kill him. Progress: Did the ambush succeed?",rewardGold=274800,rewardXP=5480,starts={{npcID=70160}},ends={{npcID=70160}},coords={x=0.514,y=0.46,source="quest_giver",zoneID=6507},questType="group"},
[32709] = {id=32709,name="Allies in the Shadows",level=32,requiredLevel=32,faction="horde",expansion=5,zoneID=6507,mapID=504,description="The Shado-Pan arrived here before we did, and they are already at work undermining the Thunder King's forces. I want you to meet with Taran Zhu , the leader of the Shado-Pan, and offer your services on behalf of the Sunreavers. I doubt he is truly in need of the aid, but the gesture holds importance in itself.",objectivesText="Speak to Taran Zhu in Bleak Hollow.",rewardGold=137400,rewardXP=4385,starts={{npcID=67990},{npcID=70371}},ends={{npcID=70160}},coords={x=0.326,y=0.354,source="quest_giver",zoneID=6507},questType="standard"},
[32710] = {id=32710,name="Something Foul is Afoot",level=35,requiredLevel=35,faction="none",expansion=5,zoneID=6622,description="You notice a stronger-than-usual smell permeating from ahead. Your stomach lurches as the thick smell fills your nostrils. You recognize this smell, it's saurok. Rotting, discarded saurok flesh infused with the foul waste of the sewer.",objectivesText="Seek and destroy Flesh'rok the Diseased .",rewardItems={97153},starts={{npcID=70429}},questType="raid"},
[32711] = {id=32711,name="Agony and Anima",level=35,requiredLevel=35,faction="none",expansion=5,zoneID=6622,description="You notice the initials A.K. skillfully and with calligraphic precision engraved onto the side of the Animus. Before you stands Archritualist Kelada , the shaper of the Animus. By command of the Thunder King, Kelada worked tirelessly to craft the perfect vessel to harness the great power of the anima. Something functional, magnificent, sentient, but most importantly... something deadly. He must be stopped before his next imagination is brought to life by the Thunder King.",objectivesText="Slay Archritualist Kelada .",rewardItems={97153},starts={{npcID=70243}},questType="raid"},
[32712] = {id=32712,name="Zao'cho the Wicked",level=35,requiredLevel=35,faction="none",expansion=5,zoneID=6622,description="Electricity hums in the distance, tickling your ears and sending impulses down your spine. Your fingers go numb, and your heart races as you approach the door ahead. Zao'cho stands arrogantly atop the steps ahead, weaving lightning between his fingers and smirking at you with demented glee.",objectivesText="Slay Zao'cho .",rewardItems={97153},starts={{npcID=69843}},questType="raid"},
[32713] = {id=32713,name="Rocks Fall, People Die",level=35,requiredLevel=35,faction="none",expansion=5,zoneID=6622,description="Words fail to describe the massive horror of rock, bone, and blood that rumbles mindlessly and aimlessly ahead of you. Massive earthquakes crack the seemingly hollow shell of ground beneath the figure, leaving destruction in its wake. It appears that the creature is unaware of your presence.",objectivesText="Slay the Rocky Horror .",rewardItems={97153},starts={{npcID=70430}},questType="raid"},
[32714] = {id=32714,name="Taming the Tempest",level=35,requiredLevel=35,faction="none",expansion=5,zoneID=6622,description="You hear a fierce and militant voice roaring in the distance. A crackling storm swells and swirls around a clouded, shadowy figure. Lightning flashes and No'ku Stormsayer appears, his scornful gaze aimed directly at you.",objectivesText="Slay No'ku Stormsayer .",rewardItems={97153},starts={{npcID=70276}},questType="raid"},
[32715] = {id=32715,name="Requiem for a Queen",level=35,requiredLevel=35,faction="none",expansion=5,zoneID=6622,description="A chilling breeze sweeps across your body, bringing with it a haunting drape of sadness. Your soul sinks as you hear the faint, melodic cries of Monara , the last Queen of the Mogu. Her sweet requiem creeps through the air, bending and shaping itself into a spectral hand, reaching for your heart. As it grabs hold, you see a brief flash of Monara 's last moments... her brutal murder by the hand of Lei Shen. Song turns to sadness and Monara weeps, wailing louder and louder into the darkness.",objectivesText="Put Monara to rest.",rewardItems={97153},starts={{npcID=70440}},questType="raid"},
[32716] = {id=32716,name="Eyes of the Thunder King",level=35,requiredLevel=35,faction="none",expansion=5,zoneID=6622,description="As the fog dissipates from the fallen sentries, you feel a sudden rumbling. The rocks blocking the sewer tunnels tumble forward and crash into the outflow tanks below, as four putrid eyes lunge from the darkness.",objectivesText="Defeat the ambush!",rewardItems={97153},starts={{npcID=70238}},questType="raid"},
[32718] = {id=32718,name="Mogu Runes of Fate",level=90,requiredLevel=90,faction="horde",expansion=5,zoneID=5840,description="Greetings, <name>. I am privileged to offer you an excellent opportunity. Through the centuries, we've honed a method by which the very laws of chance themselves can be bent. With a Mogu Rune of Fate , valuable artifacts will find their way into your hands more frequently inside the palace of the Thunder King.",objectivesText="Collect 50 Lesser Charms of Good Fortune . Progress: May these charms bring you great luck, <name>.",rewardCurrencies={{currencyID=752,quantity=1}},starts={{npcID=63996}},ends={{npcID=63996}},questType="standard"},
[32719] = {id=32719,name="Mogu Runes of Fate",level=90,requiredLevel=90,faction="alliance",expansion=5,zoneID=5840,description="Greetings, <name>. I am privileged to offer you an excellent opportunity. Through the centuries, we've honed a method by which the very laws of chance themselves can be bent. With a Mogu Rune of Fate , valuable artifacts will find their way into your hands more frequently inside the palace of the Thunder King.",objectivesText="Collect 50 Lesser Charms of Good Fortune . Progress: May these charms bring you great luck, <name>.",rewardCurrencies={{currencyID=752,quantity=1}},starts={{npcID=64029}},ends={{npcID=64029}},questType="standard"},
[32720] = {id=32720,name="Choose Your Assignment",level=32,requiredLevel=32,faction="horde",expansion=5,zoneID=6507,mapID=504,objectivesText="Kill 10 Kirin Tor units or players on the Isle of Thunder .",questType="pvp"},
[32721] = {id=32721,name="Choose Your Assignment",level=32,requiredLevel=32,faction="alliance",expansion=5,zoneID=6507,mapID=504,objectivesText="Kill 10 Kirin Tor units or players on the Isle of Thunder .",questType="pvp"},
[32722] = {id=32722,name="Forge Ahead!",level=32,requiredLevel=32,faction="horde",expansion=5,zoneID=6507,mapID=504,description="There's more you must do. Kill Itoka , master of the forge, and find a codex fragment from Fleshcrafter Hoku, gatekeeper of the Thunder King.",objectivesText="Kill the Master of the Forge and collect a Codex Fragment from Fleshcrafter Hoku in the Isle of Thunder . Progress: Well?",rewardGold=274800,rewardXP=5480,rewardItems={94220},rewardCurrencies={{id=738,amount=5}},starts={{npcID=67985}},ends={{npcID=70551}},coords={x=0.472,y=0.406,source="quest_giver",mapID=504},questType="standard"},
[32723] = {id=32723,name="reuse me",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6507,mapID=504,description="There's more you must do. Kill Itoka , master of the forge, and find a codex fragment from Fleshcrafter Hoku, gatekeeper of the Thunder King.",objectivesText="Kill the Master of the Forge and Collect a Codex Fragment from the Mogu Gatekeeper in the Isle of Thunder .",rewardGold=228000,rewardXP=250,rewardItems={94219},questType="standard"},
[32724] = {id=32724,name="Forge Ahead!",level=32,requiredLevel=32,faction="alliance",expansion=5,zoneID=6507,mapID=504,description="There's more you must do. Kill Itoka , master of the forge, and find a codex fragment from Fleshcrafter Hoku, gatekeeper of the Thunder King.",objectivesText="Kill the Master of the Forge and Collect a Codex Fragment from the Mogu Gatekeeper in the Isle of Thunder . Progress: Well?",rewardGold=274800,rewardXP=5480,rewardItems={94219},rewardCurrencies={{id=738,amount=5}},starts={{npcID=67998}},ends={{npcID=70552}},coords={x=0.618,y=0.52,source="quest_giver",mapID=504},questType="standard"},
[32726] = {id=32726,name="So You Want to Be a Blacksmith...",level=30,requiredLevel=30,faction="horde",expansion=5,zoneID=9105,description="While it is best to learn the properties of simpler metals and work your way up, it is possible to learn how to become a good blacksmith through mastering the various applications of ghost iron for common household objects. If you wish to take this path towards becoming a zen master blacksmith, I can teach you. Whichever way you choose, you will have my respect if you can show me that you can make a ghostly skeleton key .",objectivesText="Create a Ghostly Skeleton Key by attaining at least 500 skill in blacksmithing. If you wish to train through pandaren materials, a training project appropriate to your skill level can be learned from Jorunga Stonehoof.",rewardGold=13740,rewardXP=515,starts={{npcID=64058}},ends={{npcID=64058}},coords={x=0.592,y=0.118,source="quest_giver",zoneID=9105},questType="standard"},
[32727] = {id=32727,name="Contributed to Server Percentage Daily Tracking Quest",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6507,mapID=504,questType="standard"},
[32728] = {id=32728,name="The Court of Bones",level=32,requiredLevel=32,faction="horde",expansion=5,zoneID=6507,mapID=504,description="The mogu within the nearby Court of Bones pose a constant threat to our foothold on this island. Grand Magister Rommath has been entrusted with halting their efforts, but I am certain he could use a capable to see this task through. Go to him. Aid in whatever ways that you are able.",objectivesText="Find Grand Magister Rommath outside the Court of Bones.",rewardGold=34350,rewardXP=1095,starts={{npcID=67673}},ends={{npcID=67989}},coords={x=0.324,y=0.352,source="quest_giver",mapID=504},questType="standard"},
[32729] = {id=32729,name="Za'Tual",level=32,requiredLevel=32,faction="horde",expansion=5,zoneID=6507,mapID=504,description="The Zandalari have been a constant nuisance since we arrived on this island. I've assigned Halduron Brightwing to take charge of dismantling their presence at Za'Tual, in the south. Report to Halduron when you are best able. He will have work for you.",objectivesText="Find Halduron Brightwing outside of Za'Tual.",rewardGold=21100,rewardXP=1095,starts={{npcID=67990},{npcID=70371}},ends={{npcID=70520}},coords={x=0.326,y=0.354,source="quest_giver",mapID=504},questType="standard"},
[32730] = {id=32730,name="Ihgaluk Crag",level=32,requiredLevel=32,faction="horde",expansion=5,zoneID=6507,description="Aethas has taken over at Ihgaluk Crag, to the southeast, continuing his effort to turn the Saurok against the Zandalari and mogu. Go to him, and help in any way that you can.",objectivesText="Find Archmage Aethas Sunreaver outside of Ihgaluk Crag.",rewardGold=34350,rewardXP=1095,starts={{npcID=67663}},ends={{npcID=67660}},coords={x=0.324,y=0.352,source="quest_giver",zoneID=6507},questType="standard"},
[32731] = {id=32731,name="The Court of Bones",level=32,requiredLevel=32,faction="alliance",expansion=5,zoneID=6507,mapID=504,description="The mogu within the nearby Court of Bones comprise one of the greatest threats to our presence on this island. Narasi Snowdawn has been entrusted with halting their efforts, but I am certain she could use a capable to see this task through. Go to her. Aid in whatever ways that you are able.",objectivesText="Find Narasi Snowdawn outside the Court of Bones.",rewardGold=59670,rewardXP=1095,starts={{npcID=67993}},ends={{npcID=67997}},coords={x=0.632,y=0.722,source="quest_giver",mapID=504},questType="standard"},
[32732] = {id=32732,name="Ihgaluk Crag",level=32,requiredLevel=32,faction="alliance",expansion=5,zoneID=6507,mapID=504,description="Archmage Modera has taken over at Ihgaluk Crag, to the southeast, continuing her efforts to turn the Saurok against the Zandalari and mogu. Go to her, and help in any way that you can.",objectivesText="Find Archmage Modera outside of Ihgaluk Crag.",rewardGold=34350,rewardXP=1095,starts={{npcID=67995}},ends={{npcID=67996}},coords={x=0.626,y=0.734,source="quest_giver",mapID=504},questType="standard"},
[32733] = {id=32733,name="Za'Tual",level=32,requiredLevel=32,faction="alliance",expansion=5,zoneID=6507,mapID=504,description="The Zandalari have been a constant nuisance since we arrived on this island. I've assigned Archmage Lan'dalock to take charge of dismantling their presence at Za'Tual, in the south. Report to him when you are best able. He will have work for you.",objectivesText="Find Archmage Lan'dalock outside of Za'Tual.",rewardGold=21100,rewardXP=1095,starts={{npcID=67992},{npcID=70370}},ends={{npcID=70517}},coords={x=0.632,y=0.722,source="quest_giver",mapID=504},questType="standard"},
[32758] = {id=32758,name="Reader for the Dead Tongue",level=1,requiredLevel=1,faction="none",expansion=5,description="Return to your capital city and seek out a warlock trainer who may know more about the codex.",objectivesText="Bring the codex to a Warlock trainer in your capital city.",rewardGold=114000,rewardXP=200,questType="standard"},
[32783] = {id=32783,name="Ga'nar's Vengeance",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,mapID=525,description="My brother's head is as thick as his axe and he is as stubborn as a gronn. When Ga'nar left he took with him some of the finest warriors in the clan and headed north to the Daggermaw Ravine. If they are still out there, you must find them. Ga'nar will not listen to me. Help him see his vengeance through if you must but please bring him back to us.",objectivesText="Find Ga'nar near Daggermaw Ravine.",rewardGold=715,rewardXP=175,starts={{npcID=70860}},ends={{npcID=70909}},coords={x=0.27,y=0.36,source="quest_giver",zoneID=6720},questType="standard"},
[32791] = {id=32791,name="Let the Hunt Begin!",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,mapID=525,description="I have no time for my brother's whimpering. We hunt for vengeance or death. The Thunderlord chieftain slew my father and left me for dead, so I shall take his three sons, the first of which is this runt in my hand. This filth has revealed the number and positions of the Thunderlords in the ravine beyond. Join us, if you dare, and you will witness how real warriors of the Frostwolf clan fight. Get in my way, and I will end you.",objectivesText="Confront Grotan the Herald.",rewardGold=169800,rewardXP=1415,starts={{npcID=70909}},ends={{npcID=74000}},coords={x=0.308,y=0.258,source="quest_giver",zoneID=6720},questType="standard"},
[32792] = {id=32792,name="Leave Nothing Behind!",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,mapID=525,description="The Thunderlord clan has become a thorn in my side I will no longer tolerate. Go east and leave none alive! Burn their supplies! Leave them nothing to cling to. Converge on the Savage Crag to the east when it is done.",objectivesText="Kill Kur'ak the Binder , burn the Thunderlord Supplies , and destroy the Thunderlord Ballistae.",rewardGold=169800,rewardXP=1415,rewardItems={111917,111918,117505,117506,117507,117508},rewardChoices={111917,111918,117505,117506,117507,117508},starts={{npcID=74000}},ends={{npcID=70910}},coords={x=0.36,y=0.258,source="quest_giver",zoneID=6720},questType="standard"},
[32794] = {id=32794,name="Wrath of Gronn",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,mapID=525,description="The Thunderlord are capturing gronn for the Iron Horde. Show these fools why gronn are NOT pets. Follow us into Grulloc's Grotto and sunder the chains of the captive gronn . Let the beasts seek to gain their own vengeance against the Thunderlord. Meet us at Grulloc's Lair beneath the grotto when you are done.",objectivesText="Release 3 Captive Gronn .",rewardGold=169800,rewardXP=1415,starts={{npcID=70910}},ends={{npcID=70910}},questType="standard"},
[32795] = {id=32795,name="The Eldest",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,mapID=532,description="There is Hatock, last and eldest son of the Iron Wolf. One of the greatest hunters the Thunderlord have ever fielded. He was there when his father murdered my father and left me for dead. When I am done with him he will regret not finishing the job.",objectivesText="Help Ga'nar win his vengeance.",rewardGold=169800,rewardXP=1415,rewardItems={117501,117502,117503,117504},rewardChoices={117501,117502,117503,117504},starts={{npcID=70941}},ends={{npcID=70941}},questType="standard"},
[32796] = {id=32796,name="To the Garrison",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=7004,mapID=525,description="My father is avenged. The sons of the Iron Wolf are all slain. Go to the garrison your people are constructing in the south. There, herald my return to my laggard brother. The time has come for the \"chieftain\" to be reminded of what it means to be a Frostwolf.",objectivesText="Meet with Durotan in front of your garrison in Frostfire Ridge .",rewardGold=169800,rewardXP=1415,starts={{npcID=70941}},ends={{npcID=74163}},questType="standard"},
[32803] = {id=32803,name="Treasure: Thunderlord Cache 01",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6720,mapID=525,rewardGold=118000,rewardXP=200,ends={{npcID=220641}},questType="standard"},
[32804] = {id=32804,name="Articles of the Fallen",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,mapID=525,description="Even when on a mission of vengeance we must remember to uphold the honor that is required of a member of the Frostwolves. In the grotto below are the fallen corpses of many good Frostwolf orcs. They must be remembered. While you carry out Ga'nar's task, look for articles of our fallen brethren. Bring these articles to me so that I might pass them to a shaman for final burial as is our tradition.",objectivesText="Recover 10 Fallen Frostwolf Artifacts . Progress: Have you found the articles?",rewardGold=169800,rewardXP=1415,starts={{npcID=74223}},ends={{npcID=74223}},coords={x=0.464,y=0.32,source="quest_giver",zoneID=6720},questType="standard"},
[32806] = {id=32806,name="The King and the Council",level=35,requiredLevel=35,faction="both",expansion=5,zoneID=6678,mapID=390,description="I am glad you are here, . I have been using my dream brew to experience events around the world, but the more I learn, the more confused I become. For instance, King Wrynn has asked the dwarves of Ironforge for more troops, but they do not all support him. I will tell you more, but I would also like to hear from your experience firsthand...",objectivesText="Complete the \"Blood in the Snow\" scenario. You can queue from the Dungeon Finder or use Lorewalker Cho 's Dream Brew. Progress: It is not my place to make stories. I simply tell them.",rewardGold=549600,rewardXP=9580,rewardItems={98133},rewardChoices={98133},starts={{npcID=61962},{npcID=63577}},ends={{npcID=61962}},coords={x=0.832,y=0.296,source="quest_giver",zoneID=5840},questType="dungeon"},
[32807] = {id=32807,name="The Warchief and the Darkness",level=35,requiredLevel=35,faction="both",expansion=5,zoneID=6733,mapID=390,description="I see now how the Alliance king leads his people. But what is the Horde warchief up to? Just below us, a swarm of goblins are burrowing into the sacred vale on his orders. What does he hope to find there? We must find out!",objectivesText="Complete the \"Dark Heart of Pandaria\" scenario. You can queue from the Dungeon Finder or use Lorewalker Cho 's Dream Brew. Progress: It is not my place to make stories. I simply tell them.",rewardGold=549600,rewardXP=9580,rewardItems={98133},rewardChoices={98133},starts={{npcID=61962}},ends={{npcID=61962}},coords={x=0.832,y=0.296,source="quest_giver",zoneID=5840},questType="dungeon"},
[32816] = {id=32816,name="Path of the Last Emperor",level=35,requiredLevel=35,faction="both",expansion=5,zoneID=5841,mapID=379,description="In his time of uncertainty, the last emperor walked a lonely path up this mountain, until he had at last found his answers. I am here to walk the same path, and it seems you have questions of your own to be answered. Perhaps you will join me, and we can both be satisfied? Oh, but I am getting old, and this blizzard is proving too much for my bones. Could you climb ahead and anchor this rope? I can hoist myself along from there. Together we shall walk the path of the last emperor.",objectivesText="Attach the climbing rope to each Rope Anchor along the path to help Seer Hao Pham Roo reach Seeker's Point.",rewardItems={98137,98138,98139,98140,98141,98142,98143,98144,98145,247858},starts={{npcID=70980}},questType="standard"},
[32825] = {id=32825,name="Re-Use Me",level=1,requiredLevel=1,faction="alliance",expansion=5,zoneID=6507,mapID=504,objectivesText="Kill 10 Kirin Tor units or players on the Isle of Thunder .",questType="pvp"},
[32826] = {id=32826,name="Re-Use Me",level=1,requiredLevel=1,faction="none",expansion=5,zoneID=6507,mapID=504,description="Ah, $p, just the I was looking for. I have received another batch of tactical mana bombs that I need planted in key positions across Dawnseeker Promontory to the northwest. Here, take these. It is time to give the Sunreavers a taste of their own medicine. Plant one on the Sunreaver ships, another one on their scrying crystals, and the last on the bridge that connects to their forward base.",objectivesText="Plant a Tactical Mana Bomb on a Sunreaver ship, the Scrying Crystals, and on the most inland bridge of Dawnseeker Promontory.",rewardGold=114000,rewardXP=200,rewardCurrencies={{id=392,amount=75},{id=738,amount=2}},questType="pvp"},
[32827] = {id=32827,name="Re-Use Me",level=1,requiredLevel=1,faction="none",expansion=5,zoneID=6507,mapID=504,description="Even the strongest defense can still have a weakness, . We just need to find the weakness in the Sunreaver's defense and then exploit it as much as possible. Scouts have reported the use of perimeter wards around Dawnseeker Promontory. They're powerful, but not deadly. Disabling them would allow us to keep closer watch on their activities.",objectivesText="Destroy 6 Sunreaver Perimeter Wards around Dawnseeker Promontory.",rewardGold=114000,rewardXP=200,rewardCurrencies={{id=392,amount=75},{id=738,amount=2}},questType="pvp"},
[32836] = {id=32836,name="A Knockoff Grumplefloot",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=2257,mapID=500,description="The \"grumplefloot\" has been hastily carved out of a tree root, with holes unevenly spaced along its length. A close inspection of its backside, however, reveals words carved into the wood: RETURN TO BRAWLER'S GUILD",objectivesText="Return the Knockoff Grumplefloot to someone within your faction's Brawler's Guild.",questType="standard"},
[32838] = {id=32838,name="A Tale of Romance and Chivalry",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6719,mapID=539,description="A small book, written for children. It's well-bound and in fairly good condition. On the back cover of the book, near the spine, you find a few words written in flowing script: RETURN TO BRAWLER'S GUILD",objectivesText="Return The Bear and the Lady Fair to someone within your faction's Brawler's Guild.",questType="standard"},
[32840] = {id=32840,name="Boom Boom's Fuse",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=2257,mapID=500,description="Amidst the gibbets of hozen meat and fur flying aimlessly around Kota Kon's sphere of destruction, you seem to have grabbed hold of a small fuse. The fuse is created entirely from woven, matted hozen tail hair. It has a strong smell. Near one of the ends of the fuse, however, is a small paper tag, embossed with the words: RETURN TO BRAWLER'S GUILD",objectivesText="Return Boom Boom's Fuse to someone within your faction's Brawler's Guild.",questType="standard"},
[32842] = {id=32842,name="Teeth Like Swords",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=5805,mapID=376,description="The tooth comes to a singular edge, almost as if it were sharpened by stone. It clearly belonged to a ferocious beast. Handling it gingerly, you notice a few tiny words, expertly carved into the enamel: RETURN TO BRAWLER'S GUILD",objectivesText="Return the Impeccably Sharp Tooth to someone within your faction's Brawler's Guild.",questType="standard"},
[32844] = {id=32844,name="Secret of the Ooze",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6721,mapID=543,description="The contents of the vial swirl and froth violently, causing the vessel to tremble in your hand. As you look into the container, you think you catch a fleeting image of a living, angry face. The vial's stopper fits snugly. Around its edge, some small words have been carved with an expert hand: RETURN TO BRAWLER'S GUILD",objectivesText="Return the Vial of Reddish Ooze to someone within your faction's Brawler's Guild.",questType="standard"},
[32846] = {id=32846,name="Modified Chomping Apparatus",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=2257,mapID=500,description="You might not have recognized this as a modified chomping apparatus if it didn't have the words \" modified chomping apparatus \" messily painted onto it. Right beneath the sloppy label, you see a smaller message, written much more neatly in bright red ink: RETURN TO BRAWLER'S GUILD",objectivesText="Return the Modified Chomping Apparatus to someone within your faction's Brawler's Guild.",questType="standard"},
[32848] = {id=32848,name="Frost-Tipped Eggshell",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=2257,mapID=500,description="A piece of an eggshell, presumably penguin. Its edges are covered with rime, and based on its curvature, this egg was quite large when it was intact. Strangely, the inside of the eggshell has a message written on it, in jade-green ink: RETURN TO BRAWLER'S GUILD",objectivesText="Return the Frost-Tipped Eggshell to someone within your faction's Brawler's Guild.",questType="standard"},
[32850] = {id=32850,name="Last Year's Model",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=2257,mapID=500,description="The robot is in bad shape. It was built with several sockets which, like the Blingtron 4000, presumably once carried gems, but are now empty. The robot's otherwise dust-covered posterior region contains a small, shiny metal plaque, embossed with the words: RETURN TO BRAWLER'S GUILD",objectivesText="Return the Dusty Old Robot to someone within your faction's Brawler's Guild.",questType="standard"},
[32851] = {id=32851,name="Blingtron 3000",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=2257,mapID=500,description="The Blingtron line didn't really pick up until the 4000 series hit the vendor shelves. Few remember the Blingtron 3000, but it was a real engineering marvel in its own right! The challenge card you've unlocked gives you the ability to fight Blingtron 3000 right here, in the Brawler's Guild. Lucky you!",objectivesText="Defeat Blingtron 3000 by purchasing his challenge card and challenging him in the Brawler's Guild.",rewardItems={98091,98101},questType="standard"},
[32852] = {id=32852,name="The Digmaster's Earthblade",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=2257,mapID=500,description="An entirely ordinary-looking shovel. The handle is carved with an ornate script: \"The Digmaster's Earthblade \". On the flipside of the handle, however, is a smaller label, written in simpler text: RETURN TO BRAWLER'S GUILD",objectivesText="Return the Digmaster's Earthblade to someone within your faction's Brawler's Guild.",questType="standard"},
[32853] = {id=32853,name="Mingus Diggs",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=2257,mapID=500,description="You've earned the right to challenge Mingus Diggs, the archaeologist! Mingus isn't that tough, from what I hear... but the people in charge let him bring some of his excavated treasures with him into the brawling ring. Those are what you want to watch out for. Come buy his card when you're ready!",objectivesText="Defeat Mingus Diggs by purchasing his challenge card and challenging him in the Brawler's Guild.",rewardItems={98092,98103},questType="standard"},
[32854] = {id=32854,name="Well-Worn Blindfold",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=2257,mapID=500,description="A piece of cloth, shaped for a human-sized head. The cloth is unadorned and simple, except for a small tag on the end, which reads: RETURN TO BRAWLER'S GUILD",objectivesText="Return the Well-Worn Blindfold to someone within your faction's Brawler's Guild. Progress: You carry something of mine, I believe.",questType="standard"},
[32855] = {id=32855,name="The Blind Hero",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=2257,mapID=500,description="The challenge card you've earned allows you to fight the Blind Hero, a mysterious warrior from a bygone age. Nobody surpasses his skill with a blade. Nobody. Luckily, he can't see anything. Have fun!",objectivesText="Defeat the Blind Hero by purchasing his challenge card and challenging him in the Brawler's Guild.",rewardItems={98093,98103},questType="standard"},
[32856] = {id=32856,name="Paper-Covered Rock",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=2257,mapID=500,description="It's a strange combination of items. The paper envelops the rock completely, dwarfing it like a smothering blanket of wood pulp. Compared to the paper, the rock is barely a pebble. When held up to the light, the paper reveals a distinct watermark, along with the text: RETURN TO BRAWLER'S GUILD",objectivesText="Return the Paper-Covered Rock to someone within your faction's Brawler's Guild.",questType="standard"},
[32857] = {id=32857,name="Ro-Shambo",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=2257,mapID=500,description="The challenge card you have unlocked will allow you to fight Ro-Shambo, an esoteric creature from parts unknown. Watch out. I hear it's got a few tricks up its sleeve.",objectivesText="Defeat Ro-Shambo by purchasing her challenge card and challenging her in the Brawler's Guild.",rewardItems={98087,98102},questType="standard"},
[32858] = {id=32858,name="Raptorhide Boxing Gloves",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=17,mapID=10,description="The gloves are stitched together roughly, and by the smell of it, they've been treated with crawler mucus. Nevertheless, they appear sturdy and functional. Somewhat unsurprisingly, the inner seam bears the following words: RETURN TO BRAWLER'S GUILD",objectivesText="Return the Raptorhide Boxing Gloves to someone within your faction's Brawler's Guild.",questType="standard"},
[32863] = {id=32863,name="What We've Been Training For",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=5840,mapID=1530,description="Are you ready to put your pets to the test? The battle pet arena is no place for low-level rabbits, you'd better have a rocketbot in your pocket and be ready for action. If you've got three fully-experienced pets, find battles against trainers of similar skill and show the world what you've got. You can find the instructions in your Pet Journal.",objectivesText="Defeat 10 players through Find Battle with a team of level 25 pets.",rewardGold=341600,rewardXP=200,rewardItems={98095},starts={{npcID=63596},{npcID=63626},{npcID=64572},{npcID=64582}},ends={{npcID=63596},{npcID=63626},{npcID=64572},{npcID=64582}},coords={x=0.692,y=0.25,source="quest_giver",mapID=1530},questType="standard"},
[32868] = {id=32868,name="Beasts of Fable Book II",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6134,mapID=418,description="The stories of Lucky Yi , Greyhoof , and Skitterer Xi'a will exist in this land, always. Do you wish to meet them in battle once more?",objectivesText="Defeat Lucky Yi , Greyhoof , and Skitterer Xi'a .",rewardGold=341600,rewardXP=200,rewardItems={94207},starts={{npcID=64572},{npcID=64582}},ends={{npcID=64572},{npcID=64582}},coords={x=0.864,y=0.6,source="quest_giver",mapID=418},questType="standard"},
[32869] = {id=32869,name="Beasts of Fable Book III",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=5842,mapID=388,description="The stories of No-No , Ti'un the Wanderer , and Gorespine will exist in this land, always. Do you wish to meet them in battle once more?",objectivesText="Defeat No-No , Ti'un the Wanderer , and Gorespine .",rewardGold=341600,rewardXP=200,rewardItems={94207},starts={{npcID=64572},{npcID=64582}},ends={{npcID=64572},{npcID=64582}},coords={x=0.864,y=0.6,source="quest_giver",mapID=388},questType="standard"},
[32873] = {id=32873,name="LFGDungeons - Mists - Scenario - Heroic Random - 1st",level=10,requiredLevel=10,faction="none",expansion=5,rewardGold=137400,rewardXP=1770,rewardItems={98134},questType="standard"},
[32893] = {id=32893,name="LFGDungeons - Mists - Scenario - Heroic Random - 1st Bonus",level=10,requiredLevel=10,faction="none",expansion=5,rewardGold=549600,questType="standard"},
[32898] = {id=32898,name="Daily Scenario Random (1st) (Mists)",level=10,requiredLevel=10,faction="none",expansion=5,rewardGold=137400,questType="standard"},
[32900] = {id=32900,name="Heroic Deeds",level=35,requiredLevel=35,faction="alliance",expansion=5,zoneID=9105,description="My mind is spinning with boredom - I never get to leave this place! You look like you've seen some adventures. If you can bring me a truly heroic story, I've got something special I'm sure you'll be interested in.",objectivesText="Complete any scenario on Heroic difficulty.",rewardGold=412200,rewardXP=9580,rewardItems={98546},starts={{npcID=64101}},ends={{npcID=64101}},coords={x=0.884,y=0.65,source="quest_giver",zoneID=9105},questType="dungeon"},
[32901] = {id=32901,name="Heroic Deeds",level=35,requiredLevel=35,faction="horde",expansion=5,zoneID=9105,description="My mind is spinning with boredom - I never get to leave this place! You look like you've seen some adventures. If you can bring me a truly heroic story, I've got something special I'm sure you'll be interested in.",objectivesText="Complete any scenario on Heroic difficulty.",rewardGold=929400,rewardXP=9580,rewardItems={98546},starts={{npcID=66998}},ends={{npcID=66998}},coords={x=0.61,y=0.136,source="quest_giver",zoneID=9105},questType="dungeon"},
[32910] = {id=32910,name="reuse me",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6507,mapID=504,description="There's more you must do. Kill Itoka , master of the forge, and find a codex fragment from Fleshcrafter Hoku, gatekeeper of the Thunder King.",objectivesText="Kill the Master of the Forge and Collect a Codex Fragment from the Mogu Gatekeeper in the Isle of Thunder .",rewardGold=228000,rewardXP=250,rewardItems={94219},questType="standard"},
[32911] = {id=32911,name="Vignette: Ancient Clefthoof (Tracking Quest)",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6720,mapID=525,questType="standard"},
