[32924] = {id=32924,name="Short-Supply Reward",level=1,requiredLevel=1,faction="both",expansion=5,questType="standard"},
[32929] = {id=32929,name="They Rely on Numbers",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=7004,mapID=525,description="Thunderlord spend their days training to hunt as a team, but as individuals they are weak. Their only strength is in numbers. So... to win, we must cull their numbers. As we move up through the Daggermaw Ravine, slay any Thunderlord who stand in your way, and their clan will be made the weaker for it.",objectivesText="Slay 15 Thunderlord at Daggermaw Ravine in Frostfire Ridge . Progress: My axe bears the blood of a dozen Thunderlord. How many have you slain this day?",rewardGold=169800,rewardXP=1415,starts={{npcID=74222}},ends={{npcID=74223}},questType="standard"},
[32941] = {id=32941,name="Vignette: Oasis Icemother",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6720,mapID=525,rewardGold=114000,rewardXP=200,questType="standard"},
[32942] = {id=32942,name="Work Order: Sunreaver Onslaught I",level=15,requiredLevel=15,faction="horde",expansion=5,zoneID=5805,description="<Yoon keeps the details of this order short, but detailed.> Another request has come through for the Horde. The Sunreaver Onslaught, located out on the Isle of Thunder, has requested a bushel of scallions. Though this Horde and Alliance conflict still gets my fur in a bristle, I won't turn away a hungry stomach.",objectivesText="Plant 8 Scallion Seeds on Sunsong Ranch.",starts={{npcID=218750}},coords={x=0.522,y=0.487,source="quest_giver",zoneID=5805},questType="standard"},
[32943] = {id=32943,name="Work Order: Sunreaver Onslaught II",level=15,requiredLevel=15,faction="horde",expansion=5,zoneID=5805,description="Once your scallions are ready to be picked, you'll need only to package them for pick-up. Just think; your scallions will feed so many hungry soldiers on the front lines!",objectivesText="Harvest 8 Ripe Scallion plants and provide 40 Scallions for the Sunreaver Onslaught. Progress: The crate sits empty awaiting your crops.",rewardGold=137400,rewardXP=2090,rewardCurrencies={{id=738,amount=1}},starts={{npcID=218765}},ends={{npcID=218765}},coords={x=0.517,y=0.487,source="quest_giver",zoneID=5805},questType="standard"},
[32944] = {id=32944,name="Work Order: Kirin Tor Offensive I",level=15,requiredLevel=15,faction="alliance",expansion=5,zoneID=5805,description="<Yoon keeps the details of this order short, but detailed.> Another request has come through for the Alliance. The Kirin Tor Offensive, located out on the Isle of Thunder, has requested a bushel of juicycrunch carrots. Though this Horde and Alliance conflict still gets my fur in a bristle, I won't turn away a hungry stomach.",objectivesText="Plant 8 Juicycrunch Carrot Seeds on Sunsong Ranch.",starts={{npcID=218750}},coords={x=0.522,y=0.487,source="quest_giver",zoneID=5805},questType="standard"},
[32945] = {id=32945,name="Work Order: Kirin Tor Offensive II",level=15,requiredLevel=15,faction="alliance",expansion=5,zoneID=5805,description="Once your juicycrunch carrots are ready to be picked, you'll need only to package them for pick-up. Just think; your juicycrunch carrots will feed so many hungry soldiers on the front lines!",objectivesText="Harvest 8 Ripe Juicycrunch Carrot plants and provide 40 Juicycrunch Carrots for the Kirin Tor Offensive. Progress: The crate sits empty awaiting your crops.",rewardGold=137400,rewardXP=2090,rewardCurrencies={{id=738,amount=1}},starts={{npcID=218765}},ends={{npcID=218765}},coords={x=0.517,y=0.487,source="quest_giver",zoneID=5805},questType="standard"},
[32949] = {id=32949,name="Tracking Quest: Guru Kukuru",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6757,mapID=554,questType="standard"},
[32956] = {id=32956,name="Tracking Quest - Spectral Pirate Treasure",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6757,mapID=554,questType="standard"},
[32964] = {id=32964,name="Tracking Quest: Ghost Pirate Battle - Completed",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6757,mapID=554,questType="standard"},
[32965] = {id=32965,name="Tracking Quest: Ghost Pirate Battle - Looted Treasure",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6757,mapID=554,questType="standard"},
[32974] = {id=32974,name="Rolo's Riddle",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6757,description="On the isle of time are tall men four Round and strong and nothing more Of these brothers the shortest be Where the trail leads to me.",objectivesText="Solve the riddle.",rewardGold=68700,rewardXP=2060,starts={{npcID=8730}},ends={{npcID=8730}},questType="standard"},
[32975] = {id=32975,name="Rolo's Riddle",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6757,description="Somewhere hope stands, wings held forth From its feet turn to the north Pass beyond an ancient gate Behind a stone pair, I await.",objectivesText="Solve the riddle.",rewardGold=68700,rewardXP=2060,starts={{npcID=72751}},ends={{npcID=72751}},questType="standard"},
[32976] = {id=32976,name="Rolo's Riddle",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6757,description="The final step, my treasure calls Above the place where water falls Beneath the shade on vantage high No path to walk but air and sky.",objectivesText="Solve the riddle.",rewardGold=274800,rewardXP=5145,rewardItems={104009,104010,104012,104013},rewardChoices={104009,104010,104012,104013},rewardCurrencies={{id=777,amount=250}},starts={{npcID=72754}},ends={{npcID=72754}},questType="standard"},
[32979] = {id=32979,name="Garrison Campaign: Farseer's Rock",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=7004,mapID=525,description="Draka and Drek'Thar are travelling to Farseer's Rock. It is a sacred place, not a safe one. But Draka insists that Drek'Thar must rebuild his connection to the elements. I can feel the spirits of this land are becoming restless. Something is about to happen, and I suspect these two will need all the help they can get. Please, $p, go to them and lend what aid you can. I care for these two a great deal.",objectivesText="Find Draka and Drek'Thar at Farseer's Rock in Frostfire Ridge.",rewardGold=16980,rewardXP=685,starts={{npcID=74808}},ends={{npcID=72230}},coords={x=0.208,y=0.578,source="quest_giver",zoneID=6720},questType="standard"},
[32980] = {id=32980,name="Eaters of the Elements",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=6720,mapID=525,description="Drek'Thar has already begun his ritual, and it is powerful enough to draw the attention of the local goren. Those beasts are drawn to elemental magic like flies to a corpse. I will have my hands full soon enough. Help us if you like but Drek'Thar must be allowed to finish his ritual.",objectivesText="Defend Drek'Thar as he performs his ritual.",rewardGold=169800,rewardXP=1365,starts={{npcID=72230}},ends={{npcID=74253}},coords={x=0.74,y=0.296,source="quest_giver",zoneID=6720},questType="standard"},
[32981] = {id=32981,name="Only the Winner",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,mapID=525,description="I am Gronnstalker Rokash , and I only serve the winning side. I have heard of some of your deeds, commander, and seen the corpses left in the wake of you and your forces. I have grown tired of my current clan. They are soft, weak, and losing. I offer you this challenge: enter Colossal's Fall to the north and slay Sky-Singer Strag. Claim her totem as a trophy and I will hail you as my new chieftain.",objectivesText="Collect Sky-Singer Strag's Totem . Progress: Strag always was a coward. She would hide behind her magic and position as a speaker for the dead.",rewardGold=169800,rewardXP=1415,rewardItems={112687,112688,112689},rewardChoices={112687,112688,112689},starts={{npcID=79229}},ends={{npcID=79229}},coords={x=0.594,y=0.318,source="quest_giver",zoneID=6720},questType="standard"},
[32983] = {id=32983,name="In the Shadow of Giants",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=6720,mapID=525,description="The goren and the magnaron are ravaging the element spirits and smelting their essence as one would smelt steel. Commander, take my totem, travel east to Magnarok. Please, find them, and free them. Draka and I will make our way to the Ascent of Frostfire. Meet us there if you are successful.",objectivesText="Rescue Flamrog and Kindler . Progress: The ritual was more draining than I could have anticipated.",rewardGold=169800,rewardXP=1365,starts={{npcID=74253}},ends={{npcID=74253}},coords={x=0.74,y=0.296,source="quest_giver",zoneID=6720},questType="standard"},
[32984] = {id=32984,name="The Ascent",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=6720,mapID=525,description="I can feel the voice of the Fury at the top of the ascent. Come, let us climb these stairs together. Be on your guard. The goren of this area are likely to be drawn by the smell of a shaman. If we get separated, fall back to the base of the stairs and regroup.",rewardGold=169800,rewardXP=1365,starts={{npcID=74253}},ends={{npcID=74330}},coords={x=0.74,y=0.296,source="quest_giver",mapID=525},questType="standard"},
[32985] = {id=32985,name="Fury of Frostfire",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=6720,mapID=525,description="The moment I begin the ritual to free Exurotus you can expect Kron to be drawn to us. It would normally take an army of seasoned warriors to defeat a magnaron. We have only the three of us. Look for my fire totem upon the battlefield. I will try to gain what boons I can from Exurotus. Step near the totems and become one with the Fury. With these boons, slay Kron ! Lok'tar ogar!",objectivesText="Defeat Kron . Progress: The... Fury... is nearly free!",rewardGold=169800,rewardXP=1365,rewardItems={119145},starts={{npcID=74330}},ends={{npcID=74330}},coords={x=0.7,y=0.382,source="quest_giver",zoneID=6720},questType="standard"},
[32989] = {id=32989,name="Securing the South",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,mapID=525,description="We have an outpost to the southeast that was boxed in by Thunderlord forces as they marched through the canyons to Wor'gol. I have sent reinforcements to secure the outpost and press east to Grom'gar. We will push the Thunderlords out of our lands completely, and pursue them all the way back to that reeking corpse they call home. Draka's sister, Lokra , was among the orcs who volunteered to clean up Stonefang Outpost.",objectivesText="Speak with Lokra at Stonefang Outpost.",rewardXP=175,starts={{npcID=70860}},ends={{npcID=72274}},coords={x=0.27,y=0.36,source="quest_giver",zoneID=6720},questType="standard"},
[32990] = {id=32990,name="They Who Held Fast",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,mapID=525,description="The siege has been broken - they underestimated the resilience of Stonefang, and our reinforcement wave from Bladespire caught them completely off-guard. Once we finish cleaning up here, we rally anyone who can still fight and prepare to march for Grom'gar. The outpost captain, Karg Bloodfury, should have come out to meet us by now. Can you get him out here? Tell him Lokra is waiting. He knows how much I hate to be kept waiting.",objectivesText="Speak with Karg Bloodfury in Stonefang Outpost. Progress: You go ahead - Asha and I will hold here for now.",rewardXP=1415,starts={{npcID=72274}},ends={{npcID=72274}},coords={x=0.386,y=0.524,source="quest_giver",zoneID=6720},questType="standard"},
[32991] = {id=32991,name="Into the Boneslag",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,mapID=525,description="The Thunderlords took prisoners into the Boneslag? Well what are we waiting for?! We have to go after them! You look for the missing villagers - Asha and I will track Karg.",objectivesText="Search the Boneslag for the missing Frostwolf orcs.",rewardXP=1415,starts={{npcID=72274}},ends={{npcID=72274}},coords={x=0.386,y=0.524,source="quest_giver",zoneID=6720},questType="standard"},
[32992] = {id=32992,name="Moving Target",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,mapID=525,description="Karg's captors are moving east - probably retreating to Grom'gar with their tails between their legs! They think they outrun me, but Asha here is the fastest thing on four legs. We'll run them down in the Icewind Drifts.",objectivesText="Catch up with Lokra in the Icewind Drifts.",rewardGold=7925,rewardXP=175,starts={{npcID=72274}},ends={{npcID=72274}},coords={x=0.386,y=0.524,source="quest_giver",zoneID=6720},questType="standard"},
[32993] = {id=32993,name="The Strength of Our Bonds",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,mapID=525,description="Asha has passed, but we share a bond that cannot be severed by death. Even now, her spirit urges me onward to Grom'gar. The Iron Wolf claims our attachments make us weak... that love makes us vulnerable. He is wrong. Karg is my strength, and I his. I will free him from his chains, and together we will show the Thunderlord clan the strength of our bonds.",objectivesText="Find Karg Bloodfury in Grom'gar.",rewardGold=79250,rewardXP=1415,rewardItems={113253,113254,113255},rewardChoices={113253,113254,113255},starts={{npcID=72274}},ends={{npcID=72373}},coords={x=0.386,y=0.524,source="quest_giver",zoneID=6720},questType="standard"},
[32994] = {id=32994,name="Enfilade",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,mapID=525,description="If we leave now, my clan's final assault on Grom'gar will be a disaster. Though our warriors are unmatched in melee, the Thunderlords have new ranged weapons - our forces would be decimated as they cross the Icewind Drifts. But WE are already here. We can overtake those weapons before they ever fire. Blackrock orcs help our enemies forge these \"cannons\" in the workshops on the south side. If we use their own tools to sabotage the weapons, we leave Grom'gar wide open to a Frostwolf raid.",objectivesText="Use Blackrock Blasting Powder to destroy 5 Iron Horde Cannons in Grom'gar. Progress: If we leave those cannons intact, my brothers and sisters will die. What more is there to say?",rewardGold=169800,rewardXP=1415,rewardItems={104039},starts={{npcID=73097}},ends={{npcID=73097}},questType="standard"},
[33008] = {id=33008,name="Into the Vale",level=87,requiredLevel=87,faction="horde",expansion=5,description="Ah, I have been waiting for your arrival, traveler. I wish we could meet in better times, but alas, I fear the situation in the Vale is quite dire. But let us not speak of that now. Go visit Madam Vee Luo at the Shrine of Two Moons. She should be able to settle you in.",objectivesText="Speak to Madam Vee Luo at the Shrine of Two Moons in the Vale of Eternal Blossoms .",starts={{npcID=59964}},questType="standard"},
[33010] = {id=33010,name="The Iron Wolf",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,mapID=525,description="My brother Ga'nar stands beside me. Wor'gol, Stonefang, and your garrison hold strong. Our clan is united, and the Thunderlord are already on the run. We are ready. The time has come to face this \"Iron Wolf.\"",objectivesText="Enter the Hunter's Hall in Grom'gar and defeat the Iron Wolf .",rewardGold=339600,rewardXP=1770,rewardItems={111909,111911,111912,111913,111914,111915,111916},rewardChoices={111909,111911,111912,111913,111914,111915,111916},starts={{npcID=74163}},ends={{npcID=74163}},coords={x=0.5,y=0.384,source="quest_giver",zoneID=7004},questType="standard"},
[33011] = {id=33011,name="Vignette: Frostwolf Veteran's Keepsake",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6720,mapID=525,questType="standard"},
[33013] = {id=33013,name="Of Fire and Thunder",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,mapID=525,description="The Iron Wolf... brought weapons... ...weapons of fire and thunder. Our warriors have never seen such weapons. We were not ready. We must learn... to overcome...",objectivesText="Examine the Siege Munitions and Heavy Plating in The Boneslag.",rewardGold=79250,rewardXP=1415,rewardCurrencies={{id=824,amount=35}},starts={{npcID=74358}},ends={{npcID=74358}},coords={x=0.416,y=0.528,source="quest_giver",zoneID=6720},questType="standard"},
[33014] = {id=33014,name="Vignette: Cindermaw",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6720,mapID=525,questType="standard"},
[33016] = {id=33016,name="Treasure: Frostwolf Supply Cache",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6720,mapID=525,questType="standard"},
[33017] = {id=33017,name="Treasure: Iron Horde Supply Wagon",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6720,mapID=525,ends={{npcID=224633}},questType="standard"},
[33018] = {id=33018,name="Noodle Secrets Long Forgotten",level=35,requiredLevel=35,faction="both",expansion=5,zoneID=6757,description="Searching amidst the rubble, you find the fragment of an old sign. Wiping away the dust, you can make out the well-weathered pandaren characters for \"Noodles\" and \"Lin.\" Looking above, you suspect that the establishment this sign belonged to was situated on the bridge, which now lies in rubble about you. An eatery placed on a bridge sounds very temporary, so its owner would likely live nearby. Perhaps there is a clue to be found in the village here on the island?",objectivesText="Search the village, Old Pi'jiu, on the Timeless Isle, for the owner of the old sign fragment .",rewardGold=137400,rewardXP=4790,starts={{npcID=221376}},ends={{npcID=72426}},coords={x=0.521,y=0.463,source="quest_giver",zoneID=6757},questType="standard"},
[33020] = {id=33020,name="The Lost Secret of the Secret Ingredient",level=35,requiredLevel=35,faction="both",expansion=5,zoneID=5956,description="If you've come here to try my family's famous noodle soup, I'm afraid you're out of luck. My father passed away before he could teach me the secret ingredient. He did mention writing down the recipe for a friend of his that studied at the Temple of the Jade Serpent. Perhaps you can find it there?",objectivesText="Defeat the Sha of Doubt .",rewardGold=549600,rewardXP=9580,starts={{npcID=72426}},ends={{npcID=72426}},coords={x=0.41,y=0.738,source="quest_giver",zoneID=6757},questType="dungeon"},
[33021] = {id=33021,name="Secrets Lost, Forever?",level=35,requiredLevel=35,faction="both",expansion=5,zoneID=5805,mapID=376,description="Sungshin Ironpaw .>",objectivesText="Speak with Sungshin Ironpaw at the Halfhill Market in the Valley of the Four Winds.",rewardGold=13740,rewardXP=600,starts={{npcID=64231}},ends={{npcID=64231}},questType="standard"},
[33022] = {id=33022,name="Catch and Carry",level=35,requiredLevel=35,faction="both",expansion=5,zoneID=5805,mapID=376,description="Oh my! Grandpa used to tell me stories of the famous Lin family noodle shop. It is sad that the scroll has been warped, but I think we can work together to solve the riddle! To start, we're going to need lots of grain to make noodles. Head down to the granary and catch some grain with this sack. After you've caught some, drop it off at the wagon I've placed at the granary.",objectivesText="Use the Grain Catching Sack to catch 20 Sacks of Grain being thrown down by the Granary Vandals at the Imperial Granary. You will drop all your carried grain if you mount or get hurt.",rewardGold=137400,rewardXP=4790,starts={{npcID=64231}},ends={{npcID=64231}},coords={x=0.536,y=0.512,source="quest_giver",zoneID=5805},questType="standard"},
[33024] = {id=33024,name="Is That A Real Measurement?",level=35,requiredLevel=35,faction="both",expansion=5,zoneID=5805,mapID=376,description="Well done, . I can see you're ready to continue exploring the mysteries of Lin's secret ingredient soup. From what I can tell, Lin used Stormstout brew for his soup broth. I think the next steps for you are to create a Noodle Cart of your own and to head to the Stormstout Brewery to collect some sloshes of brew.",objectivesText="Create a Noodle Cart Kit and collect 20 Sloshes of Brew from slain alementals in the Stormstout Brewery. Progress: I'm glad it's you and not me. I'm not much of a drinker, myself.",rewardGold=549600,rewardXP=9580,starts={{npcID=64231}},ends={{npcID=64231}},coords={x=0.536,y=0.512,source="quest_giver",zoneID=5805},questType="dungeon"},
[33026] = {id=33026,name="These Aren't Your Fatty Goatsteaks",level=35,requiredLevel=35,faction="both",expansion=5,zoneID=6757,mapID=376,description="I'm so excited, . We've nearly mastered all the ingredients for noodle soup! We have plenty of vegetables and spices here, but the Lin family had access to exotic meats not seen in Pandaria for some time. We need some nice, fatty meats. Grandpa used to tell me of ancient turtles living off the shores of the Timeless Isle. Something that lives that long has to have some nice fatty meat on its bones. Create a deluxe noodle cart and gather some fatty turtle steaks and we'll continue.",objectivesText="Create a Deluxe Noodle Cart Kit and collect 50 Fatty Turtle Steaks . Progress: I can just taste the soup now!",rewardGold=274800,rewardXP=5990,starts={{npcID=64231}},ends={{npcID=64231}},coords={x=0.536,y=0.512,source="quest_giver",zoneID=5805},questType="standard"},
[33027] = {id=33027,name="The Secret Ingredient Is...",level=35,requiredLevel=35,faction="both",expansion=5,zoneID=5805,mapID=376,description="The best way to go about doing this is through hands-on experience. I've arranged for merchants, scholars, and farmers from all over Pandaria to come for a taste test of your soups. We'll get the best results if you can match them to the soups they prefer. It's time to find the secret ingredient!",objectivesText="Queue for and complete the Finding the Secret Ingredient scenario. Progress: <name>, we need to find the secret ingredient if we're to ever master the Lin family's noodle soup!",rewardGold=274800,rewardXP=5990,starts={{npcID=64231}},ends={{npcID=64231}},coords={x=0.536,y=0.512,source="quest_giver",zoneID=5805},questType="dungeon"},
[33037] = {id=33037,name="Treasure: False Jar",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6719,mapID=539,starts={{npcID=9728}},ends={{npcID=224783}},questType="standard"},
[33038] = {id=33038,name="Vignette: Embaari Defense Crystal",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6719,mapID=539,questType="standard"},
[33039] = {id=33039,name="Vignette: The Voidseer",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6719,mapID=539,questType="standard"},
[33041] = {id=33041,name="Vignette: Iron Horde Caravan",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6719,mapID=539,ends={{npcID=227134}},questType="standard"},
[33043] = {id=33043,name="Vignette: Killmaw",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6719,mapID=539,questType="standard"},
[33046] = {id=33046,name="Treasure: Beloved's Offering",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6719,mapID=539,ends={{npcID=232591}},questType="standard"},
[33047] = {id=33047,name="Short-Supply Reward",level=1,requiredLevel=1,faction="both",expansion=5,questType="standard"},
[33055] = {id=33055,name="Vignette: Foreling Worship Circle",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6719,mapID=539,questType="standard"},
[33057] = {id=33057,name="Vignette: Rotbelcher",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6719,mapID=539,questType="standard"},
[33059] = {id=33059,name="The Fate of Karabor",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,mapID=539,description="Threads of the future weave together, winding and unwinding, creating tapestries that change in form and color from one moment to the next. I must have clarity. I must focus on the ONE strand that will become reality. When you are ready to share in my vision, drink the elixir. When the vision begins, be on your guard. The events of the vision are as deadly as anything we experience in this reality.",objectivesText="Drink the Clarity Elixir and witness the fate of Karabor. Progress: <The Prophet is deep in thought. He looks troubled.>",rewardGold=169800,rewardXP=1415,starts={{npcID=79043}},ends={{npcID=79043}},coords={x=0.406,y=0.55,source="quest_giver",zoneID=6719},questType="standard"},
[33061] = {id=33061,name="Vignette: Amaukwa",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6719,mapID=539,questType="standard"},
[33062] = {id=33062,name="Catching His Eye",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,mapID=539,description="For what must be done, I need someone I can trust. You're one of those few. The woods and the orc village, Gul'var, are protected from my scrying magic. We need to pierce that veil. I think I know a way. There's a fel presence within the woods. A demonic watcher is there, hidden in a cave from which it casts its all-seeing gaze. I would like for you and the warden to capture it.",objectivesText="Capture the All-Seeing Eye .",rewardGold=339600,rewardXP=1770,starts={{npcID=77184}},ends={{npcID=77184}},coords={x=0.292,y=0.256,source="quest_giver",zoneID=6719},questType="standard"},
[33064] = {id=33064,name="Vignette: Shadowmoon Cultist Ritual",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6719,mapID=539,questType="standard"},
[33066] = {id=33066,name="Soul Shards of Summoning",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,mapID=539,description="It's good to know what Teron'gor and Cho'gall are up to. It's more important that we stop Gul'dan. Some of his disciples can summon minor demons. To do this, these lesser warlocks must use a soul shard. The foul crystal creates a connection to the Twisting Nether, pulling a demon through against its will. Gul'dan's as much demon as he is orc. If we can gather some of the more potent shards, we can combine them into something that just might capture him.",objectivesText="Collect Kurgoth's Shard , Grogal's Shard , and Hagra's Shard . Progress: Do you have the shards, <name>?",rewardGold=339600,rewardXP=1770,starts={{npcID=77184}},ends={{npcID=77417}},coords={x=0.292,y=0.256,source="quest_giver",zoneID=6719},questType="standard"},
[33070] = {id=33070,name="Think of the Children!",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,mapID=539,description="When the Shadowmoon attacked Arbor Glen, everything was thrown into chaos. Many of us escaped, but there are still three children missing. I believe they are still back in the village. Please save them!",objectivesText="Save Rastaak , Ariaana , and Hakaam .",rewardGold=169800,rewardXP=1415,starts={{npcID=80196}},ends={{npcID=74043}},coords={x=0.466,y=0.376,source="quest_giver",zoneID=6719},questType="standard"},
[33072] = {id=33072,name="Into Twilight",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,mapID=539,description="The safety of my people is of the utmost priority. It is likely that Ner'zhul has taken the prisoners to Shaz'gul, his stronghold to the southwest. I do not wish to use aggression against him, but he may force my hand. Meet me at Twilight Glade, . Then, we shall try our best to recover the prisoners.",objectivesText="Speak to Prophet Velen at Twilight Glade.",rewardGold=31900,rewardXP=710,starts={{npcID=74043}},ends={{npcID=79043}},coords={x=0.492,y=0.374,source="quest_giver",zoneID=6719},questType="standard"},
[33075] = {id=33075,name="A Hero's Welcome",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=7078,mapID=539,description="Prophet Velen has asked me to show you around Shadowmoon Valley . We will go first to Embaari Village, where my sister Samaara is waiting for us. I have not seen her since the Iron Horde took me to Tanaan. The village is just one of many trading villages between the Temple of Karabor and Shattrath. Follow the road east and make your way to Embaari Village. I will accompany you, my friend.",objectivesText="Speak to Samaara at Embaari Village.",rewardGold=169800,rewardXP=1415,starts={{npcID=73395},{npcID=80568}},ends={{npcID=75005}},coords={x=0.462,y=0.386,source="quest_giver",zoneID=6719},questType="standard"},
[33076] = {id=33076,name="The Clarity Elixir",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,mapID=539,description="I see a thousand glimpses of the future, swimming in a chaotic blur. It is possible to focus my energies to see the true eventuality - the future most likely to come to pass. I will need an oracle stone to focus my power, and a special elixir to still my mind. To make the elixir, I will need the following ingredients: wing dust from Swamplighters along the river, fresh hearts from a monstrously-sized hydra, and a rare star lily. Meet me at Moonwillow Peak when this task is done.",objectivesText="Collect 6 Swamplighter Dust , 3 Engorged Hearts , and 1 Starflower. Progress: Yes?",rewardGold=169800,rewardXP=1415,rewardItems={111024},rewardCurrencies={{id=824,amount=35}},starts={{npcID=79043}},ends={{npcID=79043}},coords={x=0.406,y=0.55,source="quest_giver",zoneID=6719},questType="standard"},
[33077] = {id=33077,name="A Grandmother's Remedy",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,mapID=539,description="Oh my, such a vigorous young ! Such a spring in your step, and such a sparkle in your eye! When you get to my age, it's all aches and pains. Luckily, I have a recipe for an unguent that would soothe my joints. I just need the ooze from the skin of belly toads in the swamp. Would you be a dear and help an old woman out?",objectivesText="Collect 6 Vials of Toad Juice . Progress: It's all downhill from here, dearie.",rewardGold=169800,rewardXP=1415,starts={{npcID=71641}},ends={{npcID=71641}},coords={x=0.412,y=0.55,source="quest_giver",zoneID=6719},questType="standard"},
[33078] = {id=33078,name="The Dark that Blinds Us",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,mapID=539,description="After years of research, there is still so much I do not understand about the Shadowmoon. To the southwest are stone monuments detailing the orcs' history. I'm not able to get close enough to examine the stones, but perhaps you can. If you could take a chalk rubbing of the words written on those stones, and I will reward you handsomely.",rewardGold=169800,rewardXP=1415,starts={{npcID=74121}},ends={{npcID=74121}},coords={x=0.422,y=0.574,source="quest_giver",mapID=539},questType="standard"},
[33080] = {id=33080,name="Going Undercover",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,mapID=539,description="Yrel leads my rangers on a search for the prisoners at the Shadowmoon village. Their work is extremely dangerous, so I need you to carry out a contingency mission. Sylene has mastered an illusion spell which will allow you to infiltrate Shaz'gul safely. Speak to her to disguise yourself. Then, plant explosives at the quartermaster's depot, the main lodge, and the ritual altar. In case anything goes wrong, set them off to create a distraction.",objectivesText="Speak to Sylene at Twilight Glade to gain an orc illusion, then plant explosives at key locations in Shaz'gul. If you lose your disguise, use Sylene's Amulet of Illusion to regain an orc appearance.",rewardGold=339600,rewardXP=1770,starts={{npcID=73425}},ends={{npcID=74877}},coords={x=0.406,y=0.548,source="quest_giver",zoneID=6719},questType="standard"},
[33081] = {id=33081,name="Escape From Shaz'gul",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,mapID=539,description="I've failed, ... My squadron was caught by a wandering patrol. We fought fiercely, but the alarm had been raised. The rangari forced me into hiding before surrendering themselves to the enemy. They were under MY command, and they gave their lives... for what? I... I'm not sure what to do, . We need to get out of here, but how?",objectivesText="Help Yrel escape from Shaz'gul.",rewardGold=509400,rewardXP=2125,rewardItems={106174,107304,107309,107315},rewardChoices={106174,107304,107309,107315},starts={{npcID=74877}},ends={{npcID=76067}},coords={x=0.342,y=0.632,source="quest_giver",zoneID=6719},questType="standard"},
[33082] = {id=33082,name="Ancestor's Memory",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,mapID=539,description="I believe that you should know the price of the lives you take. So before I will help you find Ner'zhul, you must understand why he joined the Iron Horde. In a cave beneath this village is an artifact that we call the Ancestral Totem. On it is carved the names of every Shadowmoon clan member since its founding. The opening of the cave lies directly south. I will meet you there.",objectivesText="Find the Ancestor's Totem in the cave beneath Exile's Rise. Progress: You must understand a man's life before taking it.",rewardGold=339600,rewardXP=1770,rewardItems={106151,107301,107306,107316},rewardChoices={106151,107301,107306,107316},starts={{npcID=75884}},ends={{npcID=75884}},coords={x=0.456,y=0.262,source="quest_giver",zoneID=6719},questType="standard"},
[33083] = {id=33083,name="On the Offensive",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,mapID=539,description="We cannot enter these gates, but you can, . Your mission is critical, and the Shadowmoon will kill you on sight. Do not hesitate to return the favor.",objectivesText="Kill 15 Shadowmoon Darkcasters or Shadowmoon Voidclaws .",rewardGold=169800,rewardXP=1415,starts={{npcID=81176}},ends={{npcID=77282}},coords={x=0.358,y=0.368,source="quest_giver",zoneID=6719},questType="standard"},
[33084] = {id=33084,name="The Big Haul",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,mapID=539,description="Ey commander, fancy runnin' inta ya out here! Tha garrison's got plenty a hungry mouths ta feed, with more folks comin' by every day. We're really gonna need a big haul o' meat ta keep everyone happy. Wouldya care ta lend us a hand? It'll be faster work with an extra pair a hands.",objectivesText="Collect 1000 Raw Elekk Steaks . Progress: Have ya seen tha size a these beasts?",rewardGold=169800,rewardXP=1415,starts={{npcID=74233}},ends={{npcID=74233}},coords={x=0.624,y=0.368,source="quest_giver",zoneID=6719},questType="standard"},
[33086] = {id=33086,name="Tracking Quest: The Root of Darkness - Stone 1",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6719,mapID=539,questType="standard"},
[33107] = {id=33107,name="Bad Feeling, Worse Result",level=35,requiredLevel=35,faction="both",expansion=5,zoneID=5956,description="<As you open the scroll, you realize your worst fears have come true: the sha energies have corrupted the Lin recipe.> <Your only choice is to defeat the released energies in the hope that the scroll can be saved.>",objectivesText="Defeat the Ghost of Lin Da-Gu .",coords={mapID=429,x=0.688,y=0.584},questType="dungeon"},
[33109] = {id=33109,name="Short-Supply Reward",level=1,requiredLevel=1,faction="both",expansion=5,questType="standard"},
[33110] = {id=33110,name="The Usurper",level=1,requiredLevel=1,faction="none",expansion=5,zoneID=6553,description="This fragment of the heart of Y'shaarj lies completely inert. You should bring it to the remnants of the Golden Lotus as proof that Garrosh has been defeated.",objectivesText="Claim your reward for deposing Garrosh Hellscream as Warchief of the Horde.",rewardItems={98093,98103},rewardCurrencies={{id=396,amount=50}},questType="standard"},
[33111] = {id=33111,name="Bounty: Twisted Ancient",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,description="The ancients of the Cursed Woods have been corrupted by demonic magic. Since they need to be destroyed, we might as well make use of their resources. Waste not, want not. Beware: these woodland behemoths are no easy targets. Gather trusted friends before you engage these twisted ancients. -- Baros Alexston",objectivesText="Collect Corrupted Lumber from a Twisted Ancient. Progress: Have you read the bounty I posted concerning the twisted ancients in the Cursed Woods?",rewardGold=509400,rewardXP=2125,rewardCurrencies={{id=824,amount=75}},starts={{npcID=232397},{npcID=232398},{npcID=232400}},ends={{npcID=77209}},coords={x=0.43,y=0.45,source="quest_giver",zoneID=7078},questType="group"},
[33112] = {id=33112,name="Ominous Portents",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,mapID=539,description="Now that Priestess Moonfang has created the blessed water, it is time to deal with the demon. Take the water and the scripture of Elune. Through the power of each, you will compel the demon to show us what the orcs are up to at Gul'var.",objectivesText="Compel the All-Seeing Eye. Progress: The demon must be put to the test if we're to find out what's happening at Gul'var.",rewardGold=169800,rewardXP=1415,rewardItems={108972,108975,108976},rewardChoices={108972,108975,108976},starts={{npcID=77184}},ends={{npcID=77184}},coords={x=0.292,y=0.256,source="quest_giver",zoneID=6719},questType="standard"},
[33113] = {id=33113,name="Shadowmoonwell",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,mapID=539,description="The archmage has asked me to prepare this moonwell. Once it is completed, I'll be able to sanctify its water for use against the demon. Only one thing remains. A piece of one of Draenor's moons has fallen into a nearby pool on the far side of the woods. Such a thing is perfect for use in the dedication of the moonwell to Elune. Will you bring it back for me, ?",objectivesText="Collect a Chunk of Lunar Rock . Progress: With that chunk of fallen rock, I'll be able to complete the dedication of the moonwell.",rewardGold=169800,rewardXP=1415,starts={{npcID=72623}},ends={{npcID=72623}},coords={x=0.294,y=0.246,source="quest_giver",zoneID=6719},questType="standard"},
[33114] = {id=33114,name="Forging the Soul Trap",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,mapID=539,description="The fiery heart of Krosnis is in the forge. We have the soul shards. Now all that is left to do is to stoke the fires and combine all of these foul components into a trap for Gul'dan.",objectivesText="Forge Gul'dan's Soul Trap . Progress: With the soul shards combined, we will trap Gul'dan and put an end to the Shadow Council on Draenor.",rewardGold=169800,rewardXP=1415,starts={{npcID=77417}},ends={{npcID=77417}},coords={x=0.19,y=0.286,source="quest_giver",zoneID=6719},questType="standard"},
[33115] = {id=33115,name="Shrouding Stones",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=7078,mapID=539,description="Long ago, the shaman of the Shadowmoon clan erected three stones in the woods. There, they performed their sacred rituals, blessing the beasts and the trees. Now, someone has placed a fel magic upon those stones. This corruption is what shrouds the village of Gul'var. Before we can use the captured demon to safely peer into the Shadow Council's village, we must bring down those stones.",objectivesText="Destroy the Central, Northern, and Southern Shrouding Stones . Progress: Once the shrouding stones are destroyed, we'll turn our attention to breaking this demon's will.",rewardGold=169800,rewardXP=1415,starts={{npcID=77184}},ends={{npcID=77184}},coords={x=0.292,y=0.256,source="quest_giver",zoneID=6719},questType="standard"},
[33116] = {id=33116,name="To Catch a Shadow",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,mapID=539,description="Gul'dan is on the Shadow Rise just up the hill to the west. But, you must hurry, . We know that he's about to leave for Talador and Frostfire Ridge. The use of the soul trap is straightforward. Simply point and shoot to ensnare Gul'dan . The crystal will take care of the rest. I'll see you back at Starfall Outpost when you have him. Good luck.",objectivesText="Use Gul'dan's Soul Trap on Gul'dan .",rewardGold=509400,rewardXP=2125,rewardItems={113148,113149,113150},rewardChoices={113148,113150,113149},starts={{npcID=77417}},ends={{npcID=77184}},coords={x=0.19,y=0.286,source="quest_giver",zoneID=6719},questType="standard"},
[33117] = {id=33117,name="Short-Supply Reward",level=1,requiredLevel=1,faction="both",expansion=5,questType="standard"},
[33118] = {id=33118,name="Short-Supply Reward",level=1,requiredLevel=1,faction="both",expansion=5,questType="standard"},
[33119] = {id=33119,name="Slavery and Strife",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,mapID=525,description="We have their citadel, but they still have some of my people enslaved at the Sootstained Mines. We have no one to spare, but you seem more than capable of handling a few ogres on your own. I ask that you release any enslaved Frostwolves you find there, and keep an eye out for Mulverick .",objectivesText="Free 5 Frostwolf Slaves from the Sootstained Mining Camp. Progress: Free my people and then we can talk!",rewardGold=169800,rewardXP=1415,starts={{npcID=78222}},ends={{npcID=72890}},coords={x=0.244,y=0.372,source="quest_giver",zoneID=6720},questType="standard"},
[33120] = {id=33120,name="A Curse Upon the Woods",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=7078,mapID=539,description="Cordana tells me that the creatures of the woods are cursed by the same fel energies keeping Khadgar from scrying into the orc village. This will not do. If we were on Azeroth, I could find a cure in a reasonable timeframe. However, we are not, nor do we have the luxury of time. Better to put a swift end to their suffering rather than allow these poor creatures to linger with demonic energy.",objectivesText="Kill 10 fel-cursed creatures in the Cursed Woods.",rewardGold=169800,rewardXP=1415,rewardCurrencies={{id=824,amount=35}},starts={{npcID=72623}},ends={{npcID=72623}},coords={x=0.294,y=0.246,source="quest_giver",zoneID=6719},questType="standard"},
[33125] = {id=33125,name="A Proper Parting",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,mapID=525,description="The ogres outnumbered us, *cough* but we made them pay for their deeds in blood. Even so, I was forced to abandon my fallen brothers and sisters on the battlefield. They deserve better than to have their corpses despoiled by the ogre filth. Here, take this torch *cough* and do what I could not: burn the corpses of my fallen brothers and sisters to the west.",objectivesText="Burn the corpses of dead Frostwolf Outriders . Progress: Did you give the others a proper burial?",rewardGold=169800,rewardXP=1415,starts={{npcID=72976}},ends={{npcID=72976}},coords={x=0.66,y=0.49,source="quest_giver",zoneID=6720},questType="standard"},
[33132] = {id=33132,name="Gut Guttra",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,mapID=525,description="Snowpaw was able to help me to here so that I might strike against their leader, Guttra, but I have lost too much blood. My time is near. Do you have the strength to help me avenge my fallen brothers and sisters and kill Guttra Wolfchew ? The monster resides in the tallest tower of Grimfrost.",objectivesText="Slay Guttra Wolfchew . Progress: Did you kill Guttra Wolfchew ?",rewardGold=169800,rewardXP=1415,starts={{npcID=72976}},ends={{npcID=72976}},coords={x=0.66,y=0.49,source="quest_giver",zoneID=6720},questType="standard"},
[33133] = {id=33133,name="Warforged Seals",level=30,requiredLevel=30,faction="horde",expansion=5,zoneID=5840,mapID=390,description="Greetings, . I am privileged to offer you an excellent opportunity. Through the centuries, we've honed a method by which the very laws of chance themselves can be bent. With a Warforged Seal , valuable artifacts will find their way into your hands more frequently as you pursue Garrosh.",objectivesText="Collect 50 Lesser Charms of Good Fortune . Progress: May these charms bring you great luck, <name>.",rewardCurrencies={{currencyID=776,quantity=1}},starts={{npcID=63996}},ends={{npcID=63996}},coords={x=0.62,y=0.206,source="quest_giver",zoneID=5840},questType="standard"},
[33134] = {id=33134,name="Warforged Seals",level=30,requiredLevel=30,faction="alliance",expansion=5,zoneID=5840,mapID=390,description="Greetings, . I am privileged to offer you an excellent opportunity. Through the centuries, we've honed a method by which the very laws of chance themselves can be bent. With a Warforged Seal , valuable artifacts will find their way into your hands more frequently as you pursue Garrosh and his forces.",objectivesText="Collect 50 Lesser Charms of Good Fortune . Progress: May these charms bring you great luck, <name>.",rewardCurrencies={{currencyID=776,quantity=1}},starts={{npcID=64029}},ends={{npcID=64029}},coords={x=0.852,y=0.626,source="quest_giver",zoneID=5840},questType="standard"},
[33135] = {id=33135,name="Cleaning Up Gul'var",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,mapID=539,description="Just because we need to focus on Gul'dan doesn't mean we're not going to take down the Shadow Council in the process. This village is filthy with Shadow Council villains. Let's do something about them.",objectivesText="Kill 20 Shadow Council orcs at Gul'var.",rewardGold=169800,rewardXP=1415,starts={{npcID=77417}},ends={{npcID=72637}},coords={x=0.19,y=0.286,source="quest_giver",zoneID=6719},questType="standard"},
[33136] = {id=33136,name="The Rainy Day is Here",level=35,requiredLevel=35,faction="both",expansion=5,zoneID=6757,mapID=554,rewardItems={101529},starts={{npcID=73082}},ends={{npcID=73082}},coords={x=0.348,y=0.596,source="quest_giver",mapID=554},questType="standard"},
[33137] = {id=33137,name="The Celestial Tournament",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6757,description="The Timeless Isle is home to a special tournament created to test the leadership of its participants. Those who prove their worth are granted an opportunity to befriend an embodiment of virtue - the progeny of the celestials themselves. Each time you win the tournament, I will honor you with a single ceremonial coin. When you have enough coins, speak with me again to further discuss your reward.",objectivesText="Speak with Master Li to enter the Celestial Tournament and defeat all the challengers there.",rewardGold=341600,rewardXP=200,rewardItems={101529},rewardCurrencies={{id=777,amount=1000}},starts={{npcID=73082}},ends={{npcID=73082}},coords={x=0.348,y=0.596,source="quest_giver",zoneID=6757},questType="standard"},
[33138] = {id=33138,name="Why Do We Fight?",level=35,requiredLevel=35,faction="both",expansion=5,zoneID=5840,mapID=1530,description="Oh my friend, today you and your companions have put an end to the sha that has plagued Pandaria since before time was recorded. You have accomplished that which even the titans and their mogu servants could not: destroying the last breaths of Y'Shaarj. Come, will you join me in the Vale of Eternal Blossoms? There is something I would like you to bear witness to.",rewardGold=137400,rewardXP=4790,starts={{npcID=73318}},ends={{npcID=73136}},questType="standard"},
[33139] = {id=33139,name="Secrets Lost, Forever?",level=35,requiredLevel=35,faction="none",expansion=5,description="<With the ancient Lin family noodle soup recipe in hand, you decide to set out for the Halfhill Market.> <If anyone in Pandaria knows how to decipher this scroll, it's Sungshin Ironpaw.>",objectivesText="Speak with Sungshin Ironpaw at the Halfhill Market in the Valley of the Four Winds.",rewardGold=13740,rewardXP=600,questType="standard"},
[33145] = {id=33145,name="Grimfrost Hill",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,mapID=525,description="Free the Frostwolves being held by the Grimfrost ogres.",rewardGold=849000,rewardXP=1415,questType="world",db2Objectives={{orderIndex=1,type=0,amount=3,objectID=73284,text="Captured Frostwolves Freed"},{orderIndex=0,type=0,amount=8,objectID=72953,text="Grimfrost ogres slain"}},worldTaskTitle="Grimfrost Hill"},
[33146] = {id=33146,name="Noodle Time",level=35,requiredLevel=35,faction="both",expansion=5,zoneID=5805,mapID=376,description="Hello, . Care to work the noodle stand again? Just let me know when you're ready to work another shift and I'll get everything set up.",objectivesText="Queue for and complete a shift at the Halfhill noodle stand . Progress: Keep up the good work, <name>!",rewardGold=274800,rewardXP=5990,rewardCurrencies={{id=402,amount=1}},starts={{npcID=64231}},ends={{npcID=64231}},coords={x=0.536,y=0.512,source="quest_giver",zoneID=5805},questType="dungeon"},
[33147] = {id=33147,name="The Last Gasp of Y'Shaarj",level=35,requiredLevel=35,faction="both",expansion=5,zoneID=6738,description="A dark, vaporous substance stains the floor of the room. This is all that remains of the Old God Y'Shaarj.",objectivesText="Speak with Lorewalker Cho in the Siege of Orgrimmar .",rewardGold=137400,rewardXP=4790,starts={{npcID=73335}},questType="standard"},
[33151] = {id=33151,name="Tracking Quest: Saw Scout Valdez Arrive",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6719,mapID=539,questType="standard"},
[33156] = {id=33156,name="Time Keeper Kairoz",level=30,requiredLevel=30,faction="horde",expansion=5,zoneID=6757,mapID=554,description="You have found your way to the Timeless Isle , . The bronze dragonflight is keen to investigate the mysteries of this place, but the island is dangerous, and we will need your help. Midway down this beach, you will find a paved path to the east. It will lead you to the ancient Celestial Court. You will find Kairoz there, one of the Keepers of Time that we are working with. Kairoz will answer any questions you might have. Be careful: The way may not be safe.",objectivesText="Speak with Kairoz on the Timeless Isle .",rewardXP=2060,rewardCurrencies={{id=777,amount=100}},starts={{npcID=73353}},ends={{npcID=72870}},coords={x=0.22,y=0.408,source="quest_giver",zoneID=6757},questType="standard"},
[33160] = {id=33160,name="Time Keeper Kairoz",level=30,requiredLevel=30,faction="alliance",expansion=5,zoneID=6757,mapID=554,description="You have found your way to the Timeless Isle , . The bronze dragonflight is keen to investigate the mysteries of this place, but the island is dangerous, and we will need your help. Midway up this beach, you will find a paved path to the east. It will lead you to the ancient Celestial Court. You will find Kairoz there, one of the Keepers of Time that we are working with. Kairoz will answer any questions you might have. Be careful: The way may not be safe.",objectivesText="Speak with Kairoz on the Timeless Isle .",rewardXP=2060,rewardCurrencies={{id=777,amount=100}},starts={{npcID=73348}},ends={{npcID=72870}},coords={x=0.23,y=0.714,source="quest_giver",zoneID=6757},questType="standard"},
[33161] = {id=33161,name="A Timeless Tour",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6757,mapID=554,description="You should first familiarize yourself with the island. Explore. Investigate anything that catches your interest. Return when you're done, and I'll reward you for whatever information you've gathered about this strange place. And do be careful! Monstrous beasts and supernatural creatures abound.",objectivesText="Explore the Timeless Isle .",rewardXP=4115,rewardCurrencies={{id=777,amount=500}},starts={{npcID=72870}},ends={{npcID=72870}},coords={x=0.346,y=0.536,source="quest_giver",zoneID=6757},questType="standard"},
[33165] = {id=33165,name="Tracking Quest: The Root of Darkness - Stone 2",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6719,mapID=539,questType="standard"},
[33166] = {id=33166,name="Tracking Quest: The Root of Darkness - Stone 3",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6719,mapID=539,questType="standard"},
[33167] = {id=33167,name="Tracking Quest: The Root of Darkness - Stone 4",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6719,mapID=539,questType="standard"},
[33168] = {id=33168,name="Heart On Fire",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,mapID=539,description="We have the shards, but now they must be combined. There's a forge here, but even its fires aren't hot enough for our purposes. However, there is a demon nearby that burns hot as the sun. Gul'dan, or perhaps Razuun, has managed to summon an infernal. The thing calls itself Krosnis, which means \"furnace.\" The demon's heart burns hotly enough. All you need do is collect it.",objectivesText="Collect the Fiery Heart from Krosnis. Progress: With the combined might of the shards, we should be able to trap Gul'dan.",rewardGold=339600,rewardXP=1770,starts={{npcID=77417}},ends={{npcID=77417}},coords={x=0.19,y=0.286,source="quest_giver",zoneID=6719},questType="standard"},
[33211] = {id=33211,name="A Timeless Question",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6757,description="Destiny. Fate. Karma. Words like these imply that the timeways are unassailable. Would that were the case. To this day, many of Azeroth's inhabitants yearn to change the past. Yet just as our experiences shape us, they also shape the world around us. Consider how those threads have woven the fabric of today's reality. Cut enough threads, and causation inevitably fails, unraveling that fabric. Indeed, cutting even a single thread short can result in disaster, provided it is the right thread.",objectivesText="Correctly answer one of Evelyna's questions about the history of Azeroth. Progress: Let us speak, then, of events that have already come to pass.",rewardGold=549600,rewardXP=8230,rewardCurrencies={{id=777,amount=100}},starts={{npcID=73570}},ends={{npcID=73570}},coords={x=0.65,y=0.506,source="quest_giver",zoneID=6757},questType="standard"},
[33222] = {id=33222,name="Little Tommy Newcomer",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6757,description="I've got a battle pet, too! Want to battle? It'll be fun, I promise!",objectivesText="Defeat Little Tommy Newcomer in a pet battle.",rewardGold=341600,rewardXP=200,rewardCurrencies={{id=777,amount=500}},starts={{npcID=73626}},ends={{npcID=73626}},coords={x=0.346,y=0.604,source="quest_giver",zoneID=6757},questType="standard"},
[33225] = {id=33225,name="Short-Supply Reward",level=1,requiredLevel=1,faction="both",expansion=5,questType="standard"},
[33226] = {id=33226,name="Short-Supply Reward",level=1,requiredLevel=1,faction="both",expansion=5,questType="standard"},
[33228] = {id=33228,name="Time In Your Hands",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6757,mapID=554,description="Inhabitants of this strange island barter with a special currency, immune from the fickle fluctuations of time. You would do well to gather as many of these \" timeless coins \" as possible! They can be found hidden away in small caches, or gathered from creatures all around the island. Larger, rarer creatures are a better source of coins - you may find it profitable to venture forth as part of a group. Introduce yourself to Mistweavers Ai and Ku across the Celestial Court, and gather some coins for me.",objectivesText="Gather 1000 Timeless Coins and introduce yourself to Mistweaver Ai and Mistweaver Ku . Progress: You're back already? It feels like we spoke only moments ago.",rewardGold=137400,rewardXP=4115,rewardItems={104009,104010,104012,104013},rewardChoices={104009,104010,104012,104013},starts={{npcID=72870}},ends={{npcID=72870}},coords={x=0.346,y=0.536,source="quest_giver",zoneID=6757},questType="standard"},
[33229] = {id=33229,name="A Flash of Bronze...",level=30,requiredLevel=30,faction="alliance",expansion=5,zoneID=5840,description="As you survey the devastation of the vale, a flash of bronze catches your eye. Unless you're mistaken, a tiny gnome is trying to catch your attention from the balcony above Mogu'shan Palace, just outside of the Seat of Knowledge. You should see what she wants.",objectivesText="Speak with Chromie outside of the Seat of Knowledge in the Vale of Eternal Blossoms .",rewardGold=69050,rewardXP=1030,starts={{npcID=73691}},ends={{npcID=73691}},questType="standard"},
[33230] = {id=33230,name="A Flash of Bronze...",level=30,requiredLevel=30,faction="horde",expansion=5,zoneID=5840,description="As you survey the devastation of the vale, a flash of bronze catches your eye. Unless you're mistaken, a tiny gnome is trying to catch your attention from the balcony above Mogu'shan Palace, just outside of the Seat of Knowledge. You should see what she wants.",objectivesText="Speak with Chromie outside of the Seat of Knowledge in the Vale of Eternal Blossoms .",rewardGold=69050,rewardXP=1030,starts={{npcID=73691}},ends={{npcID=73691}},questType="standard"},
[33231] = {id=33231,name="Journey to the Timeless Isle",level=30,requiredLevel=30,faction="alliance",expansion=5,zoneID=6757,mapID=554,description="The bronze dragonflight has discovered a most unusual pandaren phenomenon, . Emerging from the mists, far off the coast of the Jade Forest - an island that was lost in time! It is a dangerous place, perhaps the most perilous in all of Pandaria. But we are determined to unravel its mysteries. Here, take this timepiece. A single click will whisk you to the island. Get yourself established, and speak with Watcher Lara . She will guide you to our chief investigator.",objectivesText="Speak with Watcher Lara on the Timeless Isle , off the coast of the Jade Forest. Provided item:",rewardGold=13740,rewardXP=515,starts={{npcID=73691}},ends={{npcID=73348}},coords={x=0.806,y=0.33,source="quest_giver",zoneID=5840},questType="standard"},
[33232] = {id=33232,name="Journey to the Timeless Isle",level=30,requiredLevel=30,faction="horde",expansion=5,zoneID=6757,mapID=554,description="The bronze dragonflight has discovered a most unusual pandaren phenomenon, . Emerging from the mists, far off the coast of the Jade Forest - an island that was lost in time! It is a dangerous place, perhaps the most perilous in all of Pandaria. But we are determined to unravel its mysteries. Here, take this timepiece. A single click will whisk you to the island. Get yourself established, and speak with Watcher Alundra . She will guide you to our chief investigator.",objectivesText="Speak with Watcher Alundra on the Timeless Isle , off the coast of the Jade Forest. Provided item:",rewardGold=13740,rewardXP=515,rewardItems={104110},starts={{npcID=73691}},ends={{npcID=73353}},coords={x=0.806,y=0.33,source="quest_giver",zoneID=5840},questType="standard"},
[33233] = {id=33233,name="Short-Supply Reward",level=35,requiredLevel=35,faction="none",expansion=5,rewardItems={120334},questType="standard"},
[33234] = {id=33234,name="Meaty Crane Leg",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6757,mapID=554,objectivesText="Progress: What do you have there?",rewardGold=13740,rewardCurrencies={{currencyID=777,quantity=1}},starts={{npcID=73657}},ends={{npcID=73657}},coords={x=0.418,y=0.634,source="quest_giver",mapID=554},questType="standard"},
[33235] = {id=33235,name="Great Turtle Meat",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6757,mapID=554,objectivesText="Progress: Well that smells... interesting...",rewardGold=13740,rewardCurrencies={{currencyID=777,quantity=1}},starts={{npcID=73657}},ends={{npcID=73657}},coords={x=0.418,y=0.634,source="quest_giver",mapID=554},questType="standard"},
[33236] = {id=33236,name="Heavy Yak Flank",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6757,mapID=554,objectivesText="Progress: What smells like bloody flank?",rewardGold=13740,rewardCurrencies={{currencyID=777,quantity=1}},starts={{npcID=73657}},ends={{npcID=73657}},coords={x=0.418,y=0.634,source="quest_giver",mapID=554},questType="standard"},
[33238] = {id=33238,name="Thick Tiger Haunch",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6757,mapID=554,objectivesText="Progress: I have a 'haunch' you have something for me!",rewardGold=13740,rewardCurrencies={{currencyID=777,quantity=1}},starts={{npcID=73657}},ends={{npcID=73657}},coords={x=0.418,y=0.634,source="quest_giver",mapID=554},questType="standard"},
[33239] = {id=33239,name="Pristine Firestorm Egg",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6757,mapID=554,objectivesText="Progress: What is that heavenly smell?",rewardGold=13740,rewardCurrencies={{currencyID=777,quantity=1}},starts={{npcID=73657}},ends={{npcID=73657}},coords={x=0.418,y=0.634,source="quest_giver",mapID=554},questType="standard"},
[33248] = {id=33248,name="Proving Grounds",level=35,requiredLevel=35,faction="alliance",expansion=5,zoneID=6852,description="You there! It's , right? Greetings. I'm Taijing. You look strong. I've seen you a few times here in the Vale, but I've never seen you fight before. I wonder... are you as strong as you seem? If you're interested in proving yourself, speak with Trial Master Rotun at the Temple of the White Tiger, in Kun-Lai. He will put you to the test.",objectivesText="Speak with Trial Master Rotun at the Temple of the White Tiger, then enter the Proving Grounds.",rewardGold=27620,rewardXP=600,starts={{npcID=64101}},ends={{npcID=64101}},coords={x=0.884,y=0.65,source="quest_giver",zoneID=9105},questType="standard"},
[33249] = {id=33249,name="Proving Grounds",level=35,requiredLevel=35,faction="horde",expansion=5,zoneID=6852,description="You there! It's , right? Greetings. I'm Jinho. You look strong. I've seen you a few times here in the Vale, but I've never seen you fight before. I wonder... are you as strong as you seem? If you're interested in proving yourself, speak with Trial Master Rotun at the Temple of the White Tiger, in Kun-Lai. He will put you to the test.",objectivesText="Speak with Trial Master Rotun at the Temple of the White Tiger, then enter the Proving Grounds.",rewardGold=13740,rewardXP=600,starts={{npcID=66998}},ends={{npcID=66998}},coords={x=0.61,y=0.136,source="quest_giver",zoneID=9105},questType="standard"},
[33255] = {id=33255,name="The Righteous March",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,mapID=539,description="The Iron Horde have overtaken Karabor. If we don't act now, we will lose the city. Exarch Akama and the last of our forces are trapped within the city, but your garrison forces are still outside the temple, awaiting your orders. Come and fly with me. We will meet your forces on the field. With the naaru by our side, we will make one last charge to retake the city!",objectivesText="Escort your garrison forces to the Temple of Karabor by slaying all the orcs in the Path of Light.",rewardGold=169800,rewardXP=1415,starts={{npcID=75145},{npcID=77312}},ends={{npcID=72413}},coords={x=0.522,y=0.46,source="quest_giver",zoneID=6719},questType="standard"},
[33256] = {id=33256,name="The Defense of Karabor",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,mapID=539,description="Defend Karabor from the Iron Horde. At the end of the northern courtyard is Arnokk the Burner. He guards the entrance to the harbor behind Karabor, where the main Iron Horde army is waiting. Once we've taken care of him, we'll need to deal with the Iron Horde leader, Commander Vorka.",objectivesText="Destroy the Iron Horde in Karabor.",rewardGold=509400,rewardXP=2125,rewardItems={106139,106150,106156,106160,251654},rewardChoices={106139,106150,106156,106160},starts={{npcID=72413}},ends={{npcID=73395}},coords={x=0.774,y=0.376,source="quest_giver",zoneID=6719},questType="standard"},
[33263] = {id=33263,name="Gloomshade Grove",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,mapID=539,description="You probably should investigate.>",objectivesText="Search Gloomshade Grove for clues. Progress: <The mule looks frightened.>",rewardGold=169800,rewardXP=1415,starts={{npcID=79966}},ends={{npcID=73877}},coords={x=0.396,y=0.296,source="quest_giver",zoneID=6719},questType="standard"},
[33266] = {id=33266,name="A Light in the Dark - Tracking Quest",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6719,mapID=539,questType="standard"},
[33269] = {id=33269,name="Cleaning Up Gul'var",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,mapID=539,description="Khadgar wants you to concentrate on Gul'dan, but that doesn't mean we're not going to take down the Shadow Council in the process. Gul'var's filthy with Shadow Council villains. Let's do something about them.",objectivesText="Kill 20 Shadow Council orcs at Gul'var.",rewardGold=169800,rewardXP=1415,starts={{npcID=72637}},ends={{npcID=72637}},coords={x=0.292,y=0.256,source="quest_giver",zoneID=6719},questType="standard"},
[33271] = {id=33271,name="Game of Thorns",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,mapID=539,description="My lead forest operator, Shelly... she is being held not far from here...",rewardGold=169800,rewardXP=1415,rewardItems={113151,113152,113153,113154},rewardChoices={113154,113153,113152,113151},starts={{npcID=73877}},ends={{npcID=76748}},coords={x=0.47,y=0.144,source="quest_giver",mapID=539},questType="standard"},
[33323] = {id=33323,name="Finale - Tracking Quest",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6719,mapID=539,questType="standard"},
[33331] = {id=33331,name="Captured Critters",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,mapID=539,description="This poor critter is about to be podling food. It would be pretty easy to set this little guy free.",objectivesText="Free Captured Critters in Gloomshade Grove.",rewardGold=169800,rewardXP=1415,starts={{npcID=77270}},ends={{npcID=77270}},coords={x=0.462,y=0.158,source="quest_giver",zoneID=6719},questType="standard"},
[33332] = {id=33332,name="Hints From The Past",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6757,mapID=554,description="There is much to learn of this place, yet it does not yield its secrets willingly. Something you mentioned the last time that we spoke intrigues me. This Mistweaver Ai, she carries a time-worn journal , if I recall? This may be the answer to many of our questions, or it may simply raise more. I suppose that it all depends on the diligence of the explorer that put pen to paper in this preposterous place. Obtain a time-worn journal and return to me with it. We shall delve into its mysteries together.",objectivesText="Purchase a Time-Worn Journal from Mistweaver Ai. Progress: Ah, you have returned. Do you have the journal?",rewardGold=137400,rewardXP=4115,rewardItems={103977},rewardCurrencies={{id=777,amount=500}},starts={{npcID=72870}},ends={{npcID=72870}},coords={x=0.346,y=0.536,source="quest_giver",zoneID=6757},questType="standard"},
[33333] = {id=33333,name="Timeless Treasures",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6757,mapID=554,description="The journal indicates that treasures abound across the island, sometimes temptingly out of reach, and other times hidden in dark caves and hollows. What might have been secreted away here, many generations ago? And perhaps more importantly, by whom? Search the island for such treasures, and return to me with your findings. Be warned that all that glitters is not gold, yet the reverse is also true. Sometimes the simple hollowed-out stump is the best hiding place for one's valuables.",objectivesText="Find a hidden treasure on the Timeless Isle . Progress: Time flows oddly in this place, I cannot tell if I should be sleeping or eating my mid-day meal.",rewardGold=137400,rewardXP=4115,rewardCurrencies={{id=777,amount=500}},starts={{npcID=72870}},ends={{npcID=72870}},coords={x=0.346,y=0.536,source="quest_giver",zoneID=6757},questType="standard"},
[33334] = {id=33334,name="Strong Enough To Survive",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6757,description="An island lost in time and yet it returns flourishing with life! Where did this island travel to? Did it simply hop forward in time, or did it languish in the dark reaches of the Twisting Nether? There is one thing for certain: the creatures that inhabit this place are far more than they seem. I sense a hidden power in them, forged by the eons. Seek out the champions of their species, duly marked by their power and prowess, and vanquish five such creatures. In death, we may find the clues we seek.",objectivesText="Defeat five Rare or Rare Elite creatures on the Timeless Isle . Progress: This journal really is fascinating, I wonder what happened to our dear explorer friend in the end.",rewardGold=274800,rewardXP=5145,rewardCurrencies={{id=777,amount=1000}},starts={{npcID=72870}},ends={{npcID=72870}},questType="group"},
[33335] = {id=33335,name="The Last Emperor",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6757,mapID=554,description="From what I have gathered, this place used to be a tournament ground of sorts, where warriors from throughout Pandaria would show their prowess by following in the footsteps of their last emperor, Shaohao. I have heard that when Shaohao completed his trials, he became one with the land, and enveloped Pandaria in a thick mist, obscuring it from even our abilities to penetrate the passages of time. That sounds quite interesting, perhaps you should speak with him?",objectivesText="Speak with Emperor Shaohao . Progress: Greetings, I am Shaohao. Are you here to hear the wisdom of the celestials?",rewardGold=137400,rewardXP=4115,rewardCurrencies={{id=777,amount=500}},starts={{npcID=72870}},ends={{npcID=73303}},coords={x=0.346,y=0.536,source="quest_giver",zoneID=6757},questType="standard"},
[33336] = {id=33336,name="The Essence of Time",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6757,description="It is about time that I revealed to you my purpose on this island. The bronze dragonflight's powers have diminished greatly - we can now only catch furtive glimpses through time. It is... quite frustrating. But we are not entirely without means. I hold in my hand the Vision of Time, an artifact of my own creation. The creatures of this isle have passed through time, and may carry with them some of its essence. With it, we will fill the hourglass, granting us a window into the timeways once more.",objectivesText="Obtain an Epoch Stone from one of the creatures on the Timeless Isle . Progress: Have you found anything?",rewardXP=4115,rewardItems={105715},rewardCurrencies={{id=777,amount=1000}},starts={{npcID=72870}},ends={{npcID=72870}},questType="standard"},
[33337] = {id=33337,name="A Vision in Time",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6757,description="Look at how the Vision reacts! Astounding! Even now it shows shadows of timeways that flit around us constantly. Though not true sands of the Hourglass of Time, the finely-ground epoch stones certainly have a power all their own. Our first task is to use them to calibrate the Vision of Time . Take the Vision of Time to a location where history is in the making: the Siege of Orgrimmar. Once there, turn the hourglass and see what happens.",objectivesText="Use the Vision of Time in the Siege of Orgrimmar. Progress: Did you use the Vision of Time ? What was the result?",rewardXP=4115,rewardItems={105930},rewardCurrencies={{id=777,amount=1000}},starts={{npcID=72870}},ends={{npcID=72870}},coords={x=0.346,y=0.536,source="quest_giver",zoneID=6757},questType="standard"},
[33338] = {id=33338,name="Empowering the Hourglass",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6757,description="The hourglass gives us glimpses into the streams of time we once walked as easily as a well-worn path. Gather additional epoch stones , so that we may continue to use the power of the hourglass to delve into the mysteries of the timeways. The future depends on it.",objectivesText="Collect Epoch Stones from creatures on the Timeless Isle . Progress: Epoch stones are rare, crystallized temporal essence.",rewardXP=4115,rewardItems={105715},rewardCurrencies={{id=777,amount=1000}},starts={{npcID=72870}},ends={{npcID=72870}},questType="standard"},
[33340] = {id=33340,name="Timeless Nutriment",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6757,mapID=554,description="As you have surmised, the flora and fauna of this island are quite unusual. Not all explanations are mysterious, however. Sometimes, we must listen to the land, to hear the tales of the world around us. Have you considered that the creatures of this island grew to such proportions simply from the nutriment of the land you walk upon? You will find nutriment in abundance throughout the island: ripe fruits, eggs, meat, flowers, nuts, and even the stones themselves. Eat, and discover the power of the land.",objectivesText="Consume a Ripe Crispfruit, Sand-Covered Egg, Charged Crystal, Huge Yak Roast, Roasted Seed, or Fire Poppy on the Timeless Isle . Progress: Have you enjoyed the abundance of the island?",rewardGold=137400,rewardXP=4115,rewardCurrencies={{id=777,amount=250}},starts={{npcID=73303}},ends={{npcID=73303}},coords={x=0.428,y=0.552,source="quest_giver",zoneID=6757},questType="standard"},
[33341] = {id=33341,name="Wayshrines Of The Celestials",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6757,mapID=554,description="Many years ago, these grounds were a place where my people would come in pilgrimage. Here, they would listen to the words of the celestials, and meditate for many days. In their meditations, they found the fear, anger, despair, doubt, and violence that plagued their spirits. Before them would be a pathway to enlightenment. For each, the pathway would be different. For all of them, the pathway began with wisdom. Travel the island, as they did, and discover one of the lost wayshrines of the celestials.",objectivesText="Find an active Time-Lost Shrine and request a blessing from the celestials. Progress: The shrines will not always avail themselves to you. Do not give up, such is the test of patience.",rewardGold=137400,rewardXP=4115,rewardCurrencies={{id=777,amount=250}},starts={{npcID=73303}},ends={{npcID=73303}},coords={x=0.428,y=0.552,source="quest_giver",zoneID=6757},questType="standard"},
[33342] = {id=33342,name="Drive Back The Flame",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6757,mapID=554,description="The pandaren once existed in harmony with the Ordon yaungol. When the island suddenly disappeared, the Ordon faced certain death. In their desperation, the chief shaman called out for aid to the Fire Lords, and was answered. Ordos was his name. Now, he is a creature of anger and violence. Though his people were saved, he burns endlessly in molten agony. There is harmony no longer. The Ordon seek to take the Celestial Court, and sacrifice us all to Ordos. Drive them back, and restore balance.",objectivesText="Earn an Honored Reputation with Shaohao by defeating yaungol forces on the Timeless Isle . Progress: The Ordon are not to be trifled with. They have survived on this island under the protections of their ever-burning demigod, Ordos.",rewardGold=137400,rewardXP=4115,rewardCurrencies={{id=777,amount=2000}},starts={{npcID=73303}},ends={{npcID=73303}},coords={x=0.428,y=0.552,source="quest_giver",zoneID=6757},questType="standard"},
[33343] = {id=33343,name="The Archiereus Of Flame",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6757,mapID=554,description="Your efforts have driven back the Ordon and brought peace to the Celestial Court, but it will not last. It is time to silence the great emissary of Ordos - the Archiereus of Flame . Speak with Mistweaver Ku and purchase a scroll of challenge, then travel to Three-Breeze Terrace to the north. Issue a challenge at the challenge stone, it will undoubtedly catch the attention of the Ordon, drawing the archiereus out of the Ordon Sanctuary. It is your only chance.",objectivesText="Summon and defeat the Archiereus of Flame . Progress: The emissaries of Ordos are powerful, do not underestimate them.",rewardGold=137400,rewardXP=4115,rewardItems={103982},rewardCurrencies={{id=777,amount=2500}},starts={{npcID=73303}},ends={{npcID=73303}},coords={x=0.428,y=0.552,source="quest_giver",zoneID=6757},questType="group"},
[33344] = {id=33344,name="Armed and Dangerous",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,mapID=525,description="Ligra was sent with extra weapons to equip enslaved Frostwolves. Arm the Frostwolf Slaves so they can cut their way from their slavers.",objectivesText="Give weapons to 10 Frostwolf Slaves .",rewardGold=84400,rewardXP=1415,starts={{npcID=75186}},ends={{npcID=75177}},questType="standard"},
[33349] = {id=33349,name="STARTER QUEST - RED->PURPLE 15",level=1,requiredLevel=1,faction="none",expansion=5,zoneID=6170,mapID=37,description="BFor this challenge, run through the arch, then get to the RED marker, the PURPLE marker, then return here before the bell tolls 15 times. Good luck!",objectivesText="Run through the arch, hit the red marker, then the purple marker, then return to the Ironelf games camp.",rewardGold=341600,rewardXP=300,questType="standard"},
[33350] = {id=33350,name="Redridge Group Trial",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=44,mapID=49,objectivesText="Log description text.",questType="standard"},
[33354] = {id=33354,name="Den Mother's Demise",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=5861,description="This is the pelt of Darkmoon Island's monstrous den mother. Yebb Neblegear , beastmaster of the Darkmoon Faire, will be happy to know the ghostly wolf and her spawn will no longer be terrorizing his menagerie... at least for a little while. Bring it to him.",objectivesText="Bring Moonfang's Pelt to Yebb Neblegear at the Darkmoon Faire on Darkmoon Island.",rewardXP=200,rewardCurrencies={{currencyID=515,quantity=1}},starts={{npcID=14829}},ends={{npcID=14829}},questType="standard"},
[33358] = {id=33358,name="Noodle Time: Bonus",level=35,requiredLevel=35,faction="both",expansion=5,zoneID=5805,mapID=376,description="Hello, . Think you're a truly extraordinary noodle chef? Let's see what you've got!",objectivesText="Queue for a shift at the Halfhill noodle stand, then complete the bonus objective.",rewardGold=274800,rewardXP=5990,rewardCurrencies={{id=402,amount=1}},starts={{npcID=64231}},ends={{npcID=64231}},coords={x=0.536,y=0.512,source="quest_giver",zoneID=5805},questType="dungeon"},
[33359] = {id=33359,name="Meet Us at Starfall Outpost",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,mapID=539,description="The archmage has uncovered a potential Shadow Council presence in the valley. He asked me to let you know. As soon as you can, join us at Starfall Outpost. We're going to need your muscle to root them out, commander.",objectivesText="Speak with Archmage Khadgar at Starfall Outpost.",rewardXP=175,starts={{npcID=80645}},ends={{npcID=77184}},coords={x=0.438,y=0.448,source="quest_giver",zoneID=7078},questType="standard"},
[33374] = {id=33374,name="Path of the Mistwalker",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6757,description="You have heard the words of the celestials, but what did you learn on your path to the shrines? The wisdom of the pilgrimage is in its silence and simplicity. As you listen to the wind rustling in the trees, and note even the smallest butterfly, your mind is open to learning the deepest lessons the trials have to teach us. Perhaps you noticed the many great beasts that roam the island? Therein lies your trial. You have learned much from Pandaria, now let us put your knowledge to the test.",objectivesText="Defeat 20 Elite creatures on the Timeless Isle . Progress: Have the lessons of Pandaria aided you in your journey?",rewardGold=274800,rewardXP=5145,rewardItems={103641,103642,103643},rewardChoices={103641,103642,103643},rewardCurrencies={{id=777,amount=1000}},starts={{npcID=73303}},ends={{npcID=73303}},questType="group"},
[33375] = {id=33375,name="Refining The Vision",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6757,description="I have finished grinding the stones, and have attuned the hourglass to a new series of timeways. Will you return to the Siege of Orgrimmar and turn the hourglass once more? Return quickly, I am most curious.",objectivesText="Use the Vision of Time in the Siege of Orgrimmar. Progress: Did you use the Vision of Time ? What was the result?",rewardXP=4115,rewardItems={105931},rewardCurrencies={{id=777,amount=1000}},starts={{npcID=72870}},ends={{npcID=72870}},coords={x=0.346,y=0.536,source="quest_giver",zoneID=6757},questType="standard"},
[33376] = {id=33376,name="Seeking Fate",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6757,description="I have not been completely forthright with you, despite all that you have done to aid the Timewalkers. I cannot tell you everything, not yet, but know this - there is a traitor amongst us. Tell no one of your mission today, and take caution around any of my flight while you hold the Vision of Time . Quickly now, return to the Siege of Orgrimmar once more and use the hourglass. And be safe.",objectivesText="Use the Vision of Time in the Siege of Orgrimmar. Progress: Did you use the Vision of Time ? What was the result?",rewardXP=4115,rewardItems={105932},rewardCurrencies={{id=777,amount=1000}},starts={{npcID=72870}},ends={{npcID=72870}},coords={x=0.346,y=0.536,source="quest_giver",zoneID=6757},questType="standard"},
[33377] = {id=33377,name="Hidden Threads",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6757,description="You have kept our mission a secret, and for that I thank you. Knowledge of the timeways, when in the wrong hands, can cause catastrophic devastation. My flight has little power to repair it, now. We must be careful. The hourglass grows in power. I believe it can now be used to see much further than before. I wish you to push it to its limits. Return to the Siege of Orgrimmar, and focus the hourglass on the most devastating timeway you can find.",objectivesText="Use the Vision of Time in the Siege of Orgrimmar.",rewardXP=4115,rewardItems={105933},rewardCurrencies={{id=777,amount=1000}},starts={{npcID=72870}},ends={{npcID=72870}},coords={x=0.346,y=0.536,source="quest_giver",zoneID=6757},questType="standard"},
[33378] = {id=33378,name="Courting Destiny",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6757,description="The Vision of Time is nearly perfected, we now have much more control over the visions we seek. Your efforts have been instrumental in completing the artifact and restoring the strength of not only my flight, but also our allies in the Timewalkers. All of us are in your debt. Quite fortunately, I have located a sort of crux in time - an intersection of timeways - right here in Pandaria. Take the Vision of Time to the Temple of the White Tiger. There, in the cellars, turn the hourglass.",objectivesText="Use the Vision of Time at the Temple of the White Tiger in Kun-Lai Summit. Progress: Did you use the Vision of Time ? What was the result?",rewardXP=4115,rewardItems={105934},rewardCurrencies={{id=777,amount=1000}},starts={{npcID=72870}},ends={{npcID=72870}},coords={x=0.346,y=0.536,source="quest_giver",zoneID=6757},questType="standard"},
[33379] = {id=33379,name="One Final Turn",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6757,description="I do not wish to ask this of you again, but I do not know who I can trust any longer. I have been using the Vision of Time to gather information, and in my searches, I believe I have found another crux in time. It is in the Caverns of Time itself. I did not want to believe it when the vision first came to me, but I cannot sit idly by and let this information pass. The Caverns of Time - you must go there, now, and use the Vision of Time . Move quickly!",objectivesText="Use the Vision of Time in the Caverns of Time in Tanaris.",rewardXP=4115,rewardItems={105935},rewardCurrencies={{id=777,amount=5000}},starts={{npcID=72870}},ends={{npcID=72870}},coords={x=0.346,y=0.536,source="quest_giver",zoneID=6757},questType="standard"},
[33382] = {id=33382,name="Tracking Quest: Saw Maraad Storm Off",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6719,mapID=539,questType="standard"},
[33384] = {id=33384,name="Treasure: Burial Fields A",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6719,mapID=539,starts={{npcID=9728}},ends={{npcID=223533}},questType="standard"},
[33389] = {id=33389,name="Vignette: Yggdrel the Corrupted",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6719,mapID=539,questType="standard"},
[33398] = {id=33398,name="South Sprint Practice",level=1,requiredLevel=1,faction="none",expansion=5,zoneID=6170,mapID=37,description="For this challenge, run through the arch, then get to the red marker, the purple marker, then return here. You have all the time you need.",objectivesText="Run through the arch, hit the red marker, purple marker, then return to the Ironelf games camp.",rewardGold=683200,rewardXP=300,rewardItems={106981},questType="standard"},
[33408] = {id=33408,name="Great Balls of Fire!",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,mapID=525,description="Ga'nar led Ligra and the others to the second level of the fortress. Your friend, Thrall , also went to lend his skills. Follow the ramp on the south end of the ramparts outside to join them. Help them bring victory to the Frostwolf Clan!",objectivesText="Speak to Thrall in Bladespire Citadel. Progress: Yes, traveler?",rewardGold=169800,rewardXP=1415,starts={{npcID=75177}},ends={{npcID=75186}},coords={x=0.28,y=0.356,source="quest_giver",zoneID=6720},questType="standard"},
[33409] = {id=33409,name="Elwynn Run",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6170,mapID=37,description="Welcome to the Ironelf games! For this challenge: get to the blue marker, then the green marker, then return here. Score is based on your time, so get back as fast as you can!",objectivesText="Hit the blue marker, then the green marker, then return to the Ironelf games camp.",rewardXP=300,questType="standard"},
[33410] = {id=33410,name="The Butcher of Bladespire",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,mapID=527,description="After Ga'nar advanced into the fortress, the Bladespire unleashed a giant creature on our forces. I am still weak after using my magic, but at least I can help this orc in her recovery. Help take Dorogg down, .",objectivesText="Slay Dorogg the Ruthless . Progress: Have Dorogg fallen?",rewardGold=271500,rewardXP=1415,rewardItems={106138,106148,106159,106170},rewardChoices={106159,106138,106170,106148},starts={{npcID=75186}},ends={{npcID=75186}},questType="standard"},
[33412] = {id=33412,name="Mopping Up",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,mapID=525,description="We've won the day, but our work here is far from finished. Frostwolves will scour the citadel and root out any survivors. To you, I offer the glory of cleansing the gladiator pits to the north. As we launched our attack, we dispatched one of our best to recon that area. If you still thirst for blood, join her there. There's surely some sport left.",objectivesText="Speak with Igrimar the Resolute at the Circle of Blood.",rewardGold=7150,rewardXP=1415,starts={{npcID=81678}},ends={{npcID=74635}},coords={x=0.254,y=0.364,source="quest_giver",zoneID=6720},questType="standard"},
[33416] = {id=33416,name="South Sprint 12",level=1,requiredLevel=1,faction="none",expansion=5,zoneID=6170,mapID=37,description="For this challenge, run through the arch, then get to the red marker, the purple marker, then return here before the bell tolls 12 times. Good luck!",objectivesText="Run through the arch, hit the red marker, then the purple, then return to the Ironelf games camp.",rewardGold=929400,rewardXP=300,rewardItems={105710},questType="standard"},
[33419] = {id=33419,name="A Matter of Life and Death",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,description="Stranger, please help me! My companions and I ventured here to seek the bounty on a monstrous wasp queen. After we set up camp down the hill, we fell asleep. We were attacked in the middle of the night by these horrid, pale... things! I don't know where my friends have gone, but I heard screams from further down the cavern. Please, find my companions. I can't leave here without them!",objectivesText="Find Arekk , Diaani , and Zuulo in Bloodthorn Cave. Progress: They told us not to come out here, but we didn't listen. Why didn't we listen!?",rewardGold=43200,rewardXP=1415,starts={{npcID=70902}},ends={{npcID=70902}},questType="standard"},
[33422] = {id=33422,name="Elwynn Long Distance Practice",level=1,requiredLevel=1,faction="none",expansion=5,zoneID=12,mapID=37,description="For this challenge: run through the arch, then get to the blue marker, the green marker, and finally return here. You have all the time you need.",objectivesText="Run through the arch, hit the blue marker, then the green marker, then return to the Irongnome games camp.",rewardXP=300,rewardItems={106950},questType="standard"},
[33424] = {id=33424,name="Northshire Dash 12",level=1,requiredLevel=1,faction="none",expansion=5,zoneID=6170,mapID=37,description="For this challenge: run through the arch, then get to the blue marker and return here as fast as you can. Get back before you hear the bell toll 12 times.",objectivesText="Run through the arch, hit the blue marker, then return to the Ironelf games camp.",rewardGold=625600,rewardXP=250,questType="standard"},
[33425] = {id=33425,name="Blue/Yellow Sprint 15 INTERNAL REPEATABLE",level=1,requiredLevel=1,faction="none",expansion=5,zoneID=6170,mapID=37,description="Ready for a tougher challenge? This one has an extra leg: Run through the arch... Get to the blue marker... Get to the green marker... then return here before the bell tolls 15 times. Good luck!",objectivesText="Run through the arch, hit the blue marker, then the green marker, then return to the Ironelf games camp.",rewardXP=300,questType="standard"},
[33427] = {id=33427,name="Ours is the Fury",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=7004,mapID=525,description="Drek'Thar will be fine, once he adjusts. The vision the elemental has bestowed upon him is powerful, and he is on the path of becoming this world's greatest shaman. You may wish to inform Warmaster Zog in your garrison of what has transpired here. He should be able to deploy some of your troops to the area to further secure the area.",objectivesText="Speak with Warmaster Zog at your Garrison in Frostfire Ridge.",rewardGold=23635,rewardXP=685,starts={{npcID=76622}},ends={{npcID=79740}},coords={x=0.7,y=0.382,source="quest_giver",zoneID=6720},questType="standard"},
[33429] = {id=33429,name="Elwynn Long Distance Trial: 25",level=1,requiredLevel=1,faction="none",expansion=5,zoneID=12,mapID=37,description="For this challenge: run through the arch, then get to the blue marker, the green marker, and finally return here before the bell tolls 25 times.",objectivesText="Run through the arch, hit the blue marker, then the green marker, then return to the Ironelf games camp.",rewardXP=300,rewardItems={106829},questType="standard"},
