[33575] = {id=33575,name="Treasure: Demonic Cache",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6719,mapID=539,ends={{npcID=224785}},questType="standard"},
[33578] = {id=33578,name="Pyrophobia",level=20,requiredLevel=20,faction="both",expansion=5,zoneID=6662,mapID=535,description="W- we have done n-n-nothing to provoke the arakkoa... w-why would they attack Aruuna? What do they want from us? I want to run, but I'm... too afraid. That leader of theirs will burn me to a crisp, I just know it! H-he's just inside the inn...",rewardGold=169800,rewardXP=2765,starts={{npcID=75311}},ends={{npcID=75311}},coords={x=0.776,y=0.44,source="quest_giver",mapID=535},questType="standard"},
[33579] = {id=33579,name="What the Draenei Found",level=20,requiredLevel=20,faction="both",expansion=5,zoneID=6662,mapID=535,description="They came here for an artifact? The miners must have found something in our crystal mine to the north. By the Light, can you imagine how powerful that thing must be, to attract them all the way here from their spires? I suppose it is in their hands now... You'd have to be crazy to go looking for it...",rewardGold=43200,rewardXP=2765,starts={{npcID=75311}},ends={{npcID=75469}},coords={x=0.776,y=0.44,source="quest_giver",mapID=535},questType="standard"},
[33580] = {id=33580,name="The Purge of Veil Shadar",level=20,requiredLevel=20,faction="both",expansion=5,zoneID=6719,mapID=539,description="Not all arakkoa are alike. It is no illusion. They did this to me. Before I was even given a name, I was given a place in society: at the bottom. We are many. We make our homes in the places this world has forgotten. Veil Shadar was such a place, but the Adherents have found it and started a purge. For morale. For fun. Help my people escape, and we'll be in your debt. When the sky burns, it pays to have allies in the shadows.",rewardGold=169800,rewardXP=2765,rewardItems={113026,113027,113028,119077,119086},rewardChoices={113028,113027,113026,119077,119086},starts={{npcID=75288}},ends={{npcID=232592}},coords={x=0.704,y=0.568,source="quest_giver",mapID=539},questType="standard"},
[33581] = {id=33581,name="Forbidden Knowledge",level=20,requiredLevel=20,faction="both",expansion=5,zoneID=6662,mapID=535,description="Darkscryer Raastok narrows his eyes and looks you up and down.> So, you are Iskar's hired hand? Well, I care not whether you are |5 or an overgrown moth, so long as you are willing to help. The Adherents of Rukhmar are closed-minded fools! They forbid the study of shadow magic, branding as heretics anyone who dares to seek answers in the dark. We kept many tomes of forbidden knowledge in Veil Shadar. Bring any you find to me, and I will reward you for keeping them from the flames.",rewardGold=169800,rewardXP=2765,starts={{npcID=75323}},ends={{npcID=75323}},coords={x=0.704,y=0.572,source="quest_giver",mapID=535},questType="standard"},
[33582] = {id=33582,name="Kura's Vengeance",level=20,requiredLevel=20,faction="both",expansion=5,zoneID=6662,mapID=535,description="I was a wing-guard myself, once upon a time. One afternoon, I was caught away from my post. I just wanted an hour to watch the festival... Kuuan was supposed to cover for me, but instead he sold me out to gain favor with our superiors. They plucked my eyes, broke my wings, and threw me off the spire. Yet I am the fortunate one, for if Iskar hadn't found me, I'd have died there. And now Kuuan shows his face in Veil Shadar on the same day that you show up willing to kill for coin. Fortunate, indeed.",rewardGold=169800,rewardXP=2765,rewardItems={258742},starts={{npcID=75324}},ends={{npcID=75324}},coords={x=0.706,y=0.568,source="quest_giver",mapID=535},questType="standard"},
[33584] = {id=33584,name="Treasure: Ashes of A'kumbo",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6719,mapID=539,ends={{npcID=232582}},questType="standard"},
[33586] = {id=33586,name="Chasing Shadows",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,mapID=539,description="Not all of the Shadowmoon orcs followed Ner'zhul's alliance with the Iron Horde. Among them, there is one orc whom I befriended many years ago. She may be able to tell us more about Ner'zhul's plans for this \"Dark Star.\" She can be found at Exile's Rise to the northeast. I will send word ahead so she expects your arrival.",objectivesText="Speak to Rulkan at Exile's Rise.",rewardGold=84900,rewardXP=710,starts={{npcID=79043}},ends={{npcID=75884}},coords={x=0.406,y=0.55,source="quest_giver",zoneID=6719},questType="standard"},
[33593] = {id=33593,name="A Flare for the Dramatic",level=15,requiredLevel=15,faction="horde",expansion=5,zoneID=6721,mapID=543,description="I received a strange object with a note attached. Here, it seems to be written in your tongue, commander. Durotan , I'm Penny... you know, from Azeroth? We met briefly back at $p's garrison. Anyway, like I told you, I have a fifth degree black hammer in engineering and I'm eager to serve. The more danger the better! You just fire this old flare whenever you're in trouble and I'll be there, quick as a quark! Hopefully, Penny>",objectivesText="Shoot Penny's Flare Gun while in Deadgrin. Progress: Hey there, commander!",rewardGold=403722,rewardXP=2090,starts={{npcID=74594}},ends={{npcID=74594}},coords={x=0.372,y=0.77,source="quest_giver",zoneID=6721},questType="standard"},
[33602] = {id=33602,name="Short-Supply Reward",level=1,requiredLevel=1,faction="both",expansion=5,questType="standard"},
[33603] = {id=33603,name="Short-Supply Reward",level=1,requiredLevel=1,faction="both",expansion=5,questType="standard"},
[33609] = {id=33609,name="Northshire Dash Practice",level=1,requiredLevel=1,faction="none",expansion=5,zoneID=6170,mapID=37,description="Welcome to the Irongnome games! For this challenge: run through the arch, then get to the blue marker and return here as fast as you can. You have all the time you need.",objectivesText="Run through the arch, hit the blue marker, then return to the Ironelf games camp.",rewardGold=619600,rewardXP=250,questType="standard"},
[33610] = {id=33610,name="Treasure: Burial Fields B",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6719,mapID=539,starts={{npcID=9728}},ends={{npcID=225501}},questType="standard"},
