[33944] = {id=33944,name="And the Elekk Too?!",level=20,requiredLevel=20,faction="alliance",expansion=5,zoneID=6662,mapID=535,description="The little stuffed elekk has seen better days. It's torn and the stuffing is poking out. The name Caleb is sewn onto the bottom of the left back foot. Sher'khaan must have snatched it from the cart. The little draenei might appreciate its return.",objectivesText="Return Ricky to Caleb at the overturned cart. Progress: Where did you find Ricky ?!",rewardGold=169800,rewardXP=2765,starts={{npcID=226987}},ends={{npcID=76826}},coords={x=0.309,y=0.709,source="quest_giver",zoneID=6662},questType="standard"},
[33945] = {id=33945,name="Treasure: Frostwolf Cache 03",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6720,mapID=525,rewardGold=114000,rewardXP=200,questType="standard"},
[33946] = {id=33946,name="Treasure: Frostwolf Cache 04",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6720,mapID=525,rewardGold=114000,rewardXP=200,ends={{npcID=226993}},questType="standard"},
[33947] = {id=33947,name="Treasure: Grimfrost Cache",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6720,mapID=525,rewardGold=114000,rewardXP=200,ends={{npcID=226994}},questType="standard"},
[33948] = {id=33948,name="Treasure: Goren Leftovers",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6720,mapID=525,rewardGold=114000,rewardXP=200,ends={{npcID=226996}},questType="standard"},
[33949] = {id=33949,name="Treasure: Frostwolf Cache 07",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6720,mapID=525,rewardGold=114000,rewardXP=200,questType="standard"},
[33955] = {id=33955,name="Missing Pack",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,mapID=525,description="Strange, I wonder where little Shivertail and his pack are? They normally show up for a feeding about now. I hope everything is alright.",objectivesText="Find Shivertail near Wor'gol in Frostfire Ridge .",rewardGold=16980,rewardXP=175,starts={{npcID=76941}},ends={{npcID=76889}},coords={x=0.216,y=0.552,source="quest_giver",zoneID=6720},questType="standard"},
[33957] = {id=33957,name="A Gift for Raa'la",level=10,requiredLevel=10,faction="none",expansion=5,zoneID=6720,mapID=525,description="I need to pack up this kill. I promised my daughter Raa'la I would bring her home a gift from the hunt. There are a couple baby Rylaks in the cave nearby. Maybe Raa'la would like one as a pet? Would you mind catching one while I finish up here?",objectivesText="Collect a Baby Rylak for Raa'la in the Windswept Lowlands.",rewardGold=169800,rewardXP=1415,questType="standard"},
[33958] = {id=33958,name="Into the Hollow",level=20,requiredLevel=20,faction="alliance",expansion=5,zoneID=6662,mapID=535,description="I've learned that the Shadow Council is using the nearby deathweb spiders' venom to spread fel corruption and augment their forces after their defeat at the Burning Front. One of my soulbinders saw a dreadlord headed into the eastern mines with Sha'tari , one of the remaining pieces of the Heart of Auchindoun. I need you to wrest Sha'tari from the dreadlord's quivering corpse and bring it to me, champion.",objectivesText="Kill Xanatos the Defiler in Deathweb Hollow and retrieve Sha'tari . Progress: Did the demon have Sha'tari as we thought?",rewardGold=53500,rewardXP=2765,rewardItems={112509,112510,112511,112528},rewardChoices={112509,112510,112511,112528},starts={{npcID=75256}},ends={{npcID=75256}},coords={x=0.572,y=0.768,source="quest_giver",zoneID=6662},questType="standard"},
[33960] = {id=33960,name="Talador Flowerpicker",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6662,mapID=535,questType="standard"},
[33961] = {id=33961,name="Frostfire Flowerpicker",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6662,mapID=535,questType="standard"},
[33962] = {id=33962,name="Shadowmoon Flowerpicker",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6662,mapID=535,questType="standard"},
[33963] = {id=33963,name="Nagrand Flowerpicker",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6662,mapID=535,questType="standard"},
[33964] = {id=33964,name="Arak Flowerpicker",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6662,mapID=535,questType="standard"},
[33965] = {id=33965,name="Tanaan Flowerpicker",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6662,mapID=535,questType="standard"},
[33966] = {id=33966,name="Gorgrond Flowerpicker",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6662,mapID=535,questType="standard"},
[33967] = {id=33967,name="Antivenin",level=20,requiredLevel=20,faction="alliance",expansion=5,zoneID=6662,mapID=535,description="I'm worried about Nyami. She's so focused on retrieving the Heart of Auchindoun that she seems to have lost sight of everything else. I'm sorry, I'm not trying to belittle her wisdom, but look around! Every soldier we sent into the mine has been gravely injured by the deathweb spiders. Their wounds need immediate attention! Please, can you retrieve some fangs from the spiders? I can use them to create an antivenin, but I need to stay here and keep them stable until then.",objectivesText="Collect 9 Deathweb Fangs in Deathweb Hollow. Progress: Do you have the fangs? We don't have much time!",rewardGold=169800,rewardXP=2765,starts={{npcID=78028}},ends={{npcID=78028}},coords={x=0.572,y=0.768,source="quest_giver",zoneID=6662},questType="standard"},
[33969] = {id=33969,name="Vile Defilers",level=20,requiredLevel=20,faction="alliance",expansion=5,zoneID=6662,mapID=535,description="The spiders in the nearby overrun mine are feared by many, for their venom twists the very form of their victims. Many of the locals stay far away from their hollow, but I fear the Shadow Council has become privy to this information. Our scouts report that their warlocks are infusing these spiders with fel energy so that their venom turns their victims into demonic minions! We must destroy the defiling crystals so this madness does not spread.",objectivesText="Destroy 5 Defiling Crystals in Deathweb Hollow.",rewardGold=169800,rewardXP=2765,starts={{npcID=78102}},ends={{npcID=78102}},coords={x=0.574,y=0.766,source="quest_giver",zoneID=6662},questType="standard"},
[33970] = {id=33970,name="Into the Hollow",level=20,requiredLevel=20,faction="horde",expansion=5,zoneID=6662,mapID=535,description="I've learned that the Shadow Council is using the nearby deathweb spiders' venom to spread fel corruption and augment their forces after their defeat at the Burning Front. One of my soulbinders saw a dreadlord headed into the eastern mines with Sha'tari , one of the remaining pieces of the Heart of Auchindoun. I need you to wrest Sha'tari from the dreadlord's quivering corpse and bring it to me, champion.",objectivesText="Kill Xanatos the Defiler in Deathweb Hollow and retrieve Sha'tari . Progress: Did the foul demon have Sha'tari as we thought?",rewardGold=169800,rewardXP=2765,rewardItems={112509,112510,112511,112528},rewardChoices={112509,112510,112511,112528},starts={{npcID=75256}},ends={{npcID=75256}},coords={x=0.572,y=0.768,source="quest_giver",zoneID=6662},questType="standard"},
[33971] = {id=33971,name="Antivenin",level=20,requiredLevel=20,faction="horde",expansion=5,zoneID=6662,mapID=535,description="I'm worried about Nyami. She's so focused on retrieving the Heart of Auchindoun that she seems to have lost sight of everything else. I'm sorry, I'm not trying to belittle her wisdom, but look around! Every soldier we sent into the mine has been gravely injured by the deathweb spiders. Their wounds need immediate attention! Please, can you retrieve some fangs from the spiders? I can use them to create an antivenin, but I need to stay here and keep them stable until then.",objectivesText="Collect 9 Deathweb Fangs in Deathweb Hollow. Progress: Do you have the fangs? We don't have much time!",rewardGold=169800,rewardXP=2765,starts={{npcID=78028}},ends={{npcID=78028}},coords={x=0.572,y=0.768,source="quest_giver",zoneID=6662},questType="standard"},
[33972] = {id=33972,name="Vile Defilers",level=20,requiredLevel=20,faction="horde",expansion=5,zoneID=6662,mapID=535,description="The deathweb spiders are remarkable creatures. Their venom twists the very form of their victims. We are not the only ones privy to this information. The Shadow Council has already dispatched its warlocks to Deathweb Hollow to infuse the spiders with fel energy so that their venom turns creatures into demonic minions! We must destroy the defiling crystals to prevent all of Talador from bending to Teron'gor's will!",objectivesText="Destroy 5 Defiling Crystals in Deathweb Hollow. Progress: The last thing we need is the monstrous creatures of this land joining the Legion's fold.",rewardGold=169800,rewardXP=2765,starts={{npcID=75249}},ends={{npcID=75249}},coords={x=0.606,y=0.724,source="quest_giver",zoneID=6662},questType="standard"},
[33973] = {id=33973,name="Dying Wish",level=20,requiredLevel=20,faction="both",expansion=5,zoneID=6662,mapID=535,description="I am too far gone to rescue, but thank you for speaking with me. Blademaster Bralok had his men starve and beat me, and he stole an heirloom that has been in my family since before we arrived on Draenor. Should you find it, please let me see it once more so I may die in peace.",objectivesText="Recover Ahm's Heirloom from Blademaster Bralok. Progress: The Blademaster must pay...",rewardGold=169800,rewardXP=2765,starts={{npcID=77031}},ends={{npcID=77031}},coords={x=0.568,y=0.26,source="quest_giver",zoneID=6662},questType="standard"},
[33974] = {id=33974,name="Dying Wish",level=20,requiredLevel=20,faction="none",expansion=5,zoneID=6662,mapID=535,description="This appears to be an ancient Draenei heirloom. Blood stains on it would indicate that it was taken from its owner by force. An inscription on the back says \"Ahm,\" which is likely its rightful owner.",objectivesText="Speak to Ahm at Archenon Siegeyard.",rewardGold=169800,rewardXP=2765,questType="standard"},
[33975] = {id=33975,name="Treasure: Blasting Charges - Rubble A",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6720,mapID=525,rewardGold=114000,rewardXP=200,questType="standard"},
[33976] = {id=33976,name="The Final Piece",level=20,requiredLevel=20,faction="both",expansion=5,zoneID=6662,mapID=535,description="I am too injured to fight, . I have failed my city and its people. This battle is yours. Vorpil waits just ahead. He's trying to use Auch'naaru 's powers for some sort of dark ritual. You must do what I could not. Cut Vorpil down and retrieve Auch'naaru so the Heart of Auchindoun can be whole once more!",objectivesText="Take Auch'naaru from Vorpil Ribcleaver in Telmor. Progress: We need the final piece of the Heart!",rewardGold=169800,rewardXP=2765,rewardItems={113042,113043,113044,113045,113046,113047,113048,113049},rewardChoices={113042,113043,113044,113045,113046,113047,113048,113049},starts={{npcID=77082}},ends={{npcID=77082}},coords={x=0.448,y=0.906,source="quest_giver",zoneID=6662},questType="standard"},
[33977] = {id=33977,name="Blessing of the Wolf",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6662,mapID=535,questType="standard"},
