[33982] = {id=33982,name="Touched by Ice",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6662,mapID=535,questType="standard"},
[33988] = {id=33988,name="Invasion of the Soul Eaters",level=20,requiredLevel=20,faction="both",expansion=5,zoneID=6662,mapID=535,description="Telmor is lost. The Shadow Council is dragging our fallen into piles and feeding the souls to their leader. There is blood on my hands... Please, if anyone reads this message, burn the bodies of our fallen so our enemy cannot use them. - Restalaan, Captain of the Guard",objectivesText="Use torches from a forge to burn 4 body piles in Telmor.",rewardGold=169800,rewardXP=2765,starts={{npcID=227069}},coords={x=0.492,y=0.88,source="quest_giver",zoneID=6662},questType="standard"},
