[34122] = {id=34122,name="Ogre Diplomacy",level=20,requiredLevel=20,faction="horde",expansion=5,zoneID=6662,mapID=535,description="They may be spirits, but the Ango'rosh are still ogres. Even with their books in hand, they won't respect you until you prove yourself, and there's only one way to earn that. By killing them. You should take out as many of the Ango'rosh spirits and their pets as you can while in the ruins.",objectivesText="Kill 10 Ango'rosh in the Ango'rosh Ruins. Progress: How goes your diplomatic mission?",rewardGold=169800,rewardXP=2765,starts={{npcID=75389}},ends={{npcID=75389}},coords={x=0.43,y=0.762,source="quest_giver",zoneID=6662},questType="standard"},
[34123] = {id=34123,name="To Thunder Pass",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,mapID=525,description="There is no time to mourn our fallen or lick our wounds. Your scouts have already reported sighting a massive Iron Horde army making its way through Thunder Pass. I advise you let your garrison forces secure this area while you and I make for the pass east of here with the rest of the Frostwolves. It is time to show this Iron Horde what a united Frostwolf clan can do.",objectivesText="Speak with Lokra at Wolf's Stand.",rewardGold=16980,rewardXP=175,starts={{npcID=76720}},ends={{npcID=76487}},questType="standard"},
[34124] = {id=34124,name="The Battle of Thunder Pass",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,mapID=525,description="The Iron Horde has an army tenfold our number marching down the Thunder Pass as we speak. Durotan is amassing our forces at the mouth of the pass. He is doing what he can to mount a defense but war on this scale is not what we Frostwolves are masters of. He will need your expertise. Please, go to him.",objectivesText="Defend Frostfire Ridge from the Iron Horde.",rewardGold=509400,rewardXP=2125,rewardItems={106137,106146,106169,107397},rewardChoices={107397,106137,106169,106146},rewardCurrencies={{id=824,amount=100}},starts={{npcID=76487}},ends={{npcID=76484},{npcID=77485}},coords={x=0.734,y=0.588,source="quest_giver",zoneID=6720},questType="standard"},
