[34144] = {id=34144,name="Retribution for the Light",level=20,requiredLevel=20,faction="horde",expansion=5,zoneID=6662,mapID=535,description="There are agents of darkness everywhere, fighting tooth and nail to envelop the world. The Light relies on us to balance the scale. You have the power needed to destroy Teron'gor's demonic minions once and for all. Send them to the Twisting Nether in pieces!",objectivesText="Kill 15 demons in Gul'rok.",rewardGold=169800,rewardXP=2765,starts={{npcID=75389}},ends={{npcID=75389},{npcID=77580}},coords={x=0.43,y=0.762,source="quest_giver",zoneID=6662},questType="standard"},
