[34154] = {id=34154,name="Destination: Unknown",level=20,requiredLevel=20,faction="alliance",expansion=5,zoneID=8485,mapID=535,description="Teron'gor and Gul'dan were just leaving through the portal as I arrived... and I... I know I won't be able to defeat them. I'll hold open the portal as long as I can. It will be up to you to strike the killing blow. Our fate is in your hands, .",objectivesText="Destroy Mongrethod in the Remains of Xandros.",rewardGold=339600,rewardXP=3455,rewardItems={113014,113015,113016,119061,119069},rewardChoices={113016,113015,113014,119061,119069},starts={{npcID=77582}},ends={{npcID=79434}},coords={x=0.312,y=0.736,source="quest_giver",zoneID=6662},questType="standard"},
[34155] = {id=34155,name="Treasure: Gorgrond Treasure 06",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6721,mapID=543,rewardGold=171000,rewardXP=200,questType="standard"},
[34157] = {id=34157,name="Into the Heart of Madness",level=20,requiredLevel=20,faction="alliance",expansion=5,zoneID=6662,mapID=535,description=", Nyami ran off to 'take down Teron'gor herself.' You need to find her. She has no chance against him on her own. I must remain here and organize our ranks should another attack fall upon us. I'm counting on you.",objectivesText="Speak to Soulbinder Nyami at the Seat of Depravity in Gul'rok.",rewardGold=84900,rewardXP=1385,starts={{npcID=75392}},ends={{npcID=77582}},coords={x=0.43,y=0.76,source="quest_giver",zoneID=6662},questType="standard"},
[34160] = {id=34160,name="Vignette: Nixxie the Goblin",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6721,mapID=543,questType="standard"},
[34162] = {id=34162,name="Vignette: Icklarv",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6721,mapID=543,questType="standard"},
[34163] = {id=34163,name="Hiding in the Shadows",level=20,requiredLevel=20,faction="both",expansion=5,zoneID=6662,mapID=535,description="Our final move must remain concealed from the Auchenai, my minions. Use the shadow orbs Gul'dan provided for us to veil Gul'rok in darkness. Prepare our forces, we march on Auchindoun on my order. We will feast on the souls of the draenei and usher our demonic allies into this world! shadow orbs would help the defenders at Auchindoun greatly.>",objectivesText="Destroy the three Shadow Orbs in Gul'rok.",rewardGold=169800,rewardXP=2765,starts={{npcID=227737}},coords={x=0.373,y=0.794,source="quest_giver",zoneID=6662},questType="standard"},
[34164] = {id=34164,name="Book Burning",level=20,requiredLevel=20,faction="both",expansion=5,zoneID=6662,mapID=535,description="Please, ... I don't have much time. The Shadow Council have allowed themselves to be turned into demons by Teron'gor and his warlocks! I have reason to believe that the shadowborne dementors are using spells given to them by Gul'dan to empower the demonic orcs. Take their spellbooks and cast them into the fire by me... it will be a pleasant sight to die to.",objectivesText="Obtain 3 Shadow Council Spellbooks and burn them in the fire by Kor'thos Dawnfury in Gul'rok. Progress: Yes?",rewardGold=169800,rewardXP=2765,starts={{npcID=77629}},ends={{npcID=77629}},coords={x=0.34,y=0.74,source="quest_giver",zoneID=6662},questType="standard"},
