[34192] = {id=34192,name="Things Are Not Goren Our Way",level=15,requiredLevel=15,faction="alliance",expansion=5,zoneID=7004,description="The abandoned mine shaft has been overrun with goren! They seem to be responding to commands from a big one farther down in the mine. If you can take him out, the rest will probably retreat. Once you have those goren cleared out, we can get that mine up and working!",objectivesText="Kill Stonetooth in the Garrison Mine. Progress: Were you able to take out the leader?",rewardGold=169800,rewardXP=2090,rewardItems={248660},starts={{npcID=77730}},ends={{npcID=77730}},questType="standard"},
[34193] = {id=34193,name="Clearing the Garden",level=30,requiredLevel=30,faction="horde",expansion=5,zoneID=7004,description="This cave is the perfect climate to grow herbs for our Garrison, there is just one little problem. All these damn nibblers! I need you to clear them out and we can get this garden growing.",objectivesText="Kill 8 Frostwall Nibblers . Progress: Did you get em?",rewardGold=169800,rewardXP=4115,starts={{npcID=81981}},ends={{npcID=81981}},coords={x=0.438,y=0.83,source="quest_giver",zoneID=7004},questType="standard"},
[34194] = {id=34194,name="Looking For Help",level=20,requiredLevel=20,faction="alliance",expansion=5,zoneID=6719,mapID=539,description="We have an accessible fishing spot here, but no bait seems to work! We need to find a local fisherman with some knowledge of the area to help us out. Head northwest and see if you can find anyone on the shoreline.",objectivesText="Find a local fisherman to help our cause. Progress: Find anyone?",rewardGold=169800,rewardXP=2765,starts={{npcID=77733}},ends={{npcID=84372}},coords={x=0.54,y=0.134,source="quest_giver",zoneID=7078},questType="standard"},
