[34239] = {id=34239,name="Treasure: Treasure of Tuurem",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6662,mapID=535,ends={{npcID=227996}},questType="standard"},
[34240] = {id=34240,name="Scheduled Pickup",level=20,requiredLevel=20,faction="alliance",expansion=5,zoneID=6662,mapID=535,description="You've proven yourself more than capable in battle, . As you know, there may be Shadow Council forces anywhere around Auchindoun, including near Telmor. Tuulani's powers as a soulpriest have not yet fully manifested; she isn't capable of protecting the shard alone. I need you to join her at Telmor to make sure the crystal makes it to Auchindoun safely.",objectivesText="Speak to Soulbinder Tuulani outside Telmor.",rewardGold=84900,rewardXP=1385,starts={{npcID=75250}},ends={{npcID=77869}},coords={x=0.572,y=0.77,source="quest_giver",zoneID=6662},questType="standard"},
[34241] = {id=34241,name="Treasure: Gorgrond Treasure 12",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6721,mapID=543,rewardGold=171000,rewardXP=200,starts={{npcID=78260}},ends={{npcID=227998}},questType="standard"},
[34242] = {id=34242,name="Scheduled Pickup",level=20,requiredLevel=20,faction="horde",expansion=5,zoneID=6662,mapID=535,description="You've proven yourself more than capable in battle, . There may be Shadow Council forces all around Auchindoun, including near Telmor. I want you to join Soulbinder Tuulani at Telmor to make sure the crystal makes it safely to Auchindoun. I know I can trust you to get it done.",objectivesText="Speak to Soulbinder Tuulani outside Telmor.",rewardGold=84900,rewardXP=1385,starts={{npcID=75246}},ends={{npcID=77869}},coords={x=0.61,y=0.724,source="quest_giver",zoneID=6662},questType="standard"},
[34243] = {id=34243,name="Vignette: Rak'nar Muzzlebash",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6721,mapID=543,questType="standard"},
[34244] = {id=34244,name="They Took My Father",level=40,requiredLevel=40,faction="none",expansion=5,description="$p! I have a lead on what happened to my father. There have been reports that he was seen in the presence of Shadow Council orcs in ____. My father was a powerful Anchorite with a vast amount of ancient knowledge. I dread to think what those within the Shadow Council would do to him to get that knowledge. Can you go to ___? Hunt down their officers and see what they know?",objectivesText="Collect Anchorite Dolruu's three notes.",rewardGold=169800,rewardXP=1365,questType="standard"},
