[35611] = {id=35611,name="Return to Veil Terokk",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6722,mapID=542,description="\" Percy should have brought with him a basket of goods, assuming he didn't dump it off somewhere along the way. The contents are a token of my gratitude and an apology for the altercation with your scout. I must urge you to return to Veil Terokk so we may press forward with our plans. - Reshad \"",objectivesText="Speak with Reshad in Veil Terokk.",rewardGold=16980,rewardXP=515,starts={{npcID=79748}},ends={{npcID=81770}},coords={x=0.4,y=0.602,source="quest_giver",zoneID=6722},questType="standard"},
