[35618] = {id=35618,name="Gidwin Goldbraids",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,mapID=539,rewardGold=309800,rewardXP=1415,questType="standard"},
[35619] = {id=35619,name="Pinchwhistle Gearworks",level=30,requiredLevel=30,faction="alliance",expansion=5,zoneID=6722,mapID=542,description="Commander, a goblin courier arrived this morning. He mentioned that he is from a settlement to the southeast called the Pinchwhistle Gearworks. They have requested our assistance with some sort of ecological disaster. If we can earn their trust it'll be worth the effort. Head down there and see what sort of assistance we can provide. I've already spoken to the flight master and he's set up a special flight to get you out there.",objectivesText="Speak to Firn Swiftbreeze to secure a flight to the Pinchwhistle Gearworks.",rewardGold=16980,rewardXP=515,starts={{npcID=85550}},ends={{npcID=81109}},coords={x=0.396,y=0.606,source="quest_giver",zoneID=6722},questType="standard"},
[35620] = {id=35620,name="Pinchwhistle Gearworks",level=30,requiredLevel=30,faction="horde",expansion=5,zoneID=6722,mapID=542,description="Commander, a courier arrived this morning. He said he's from a goblin settlement to the southeast called the Pinchwhistle Gearworks. They've asked for our assistance with some sort of ecological disaster. We're spread thin but if we can earn their trust then we might be able to gain a valuable ally. Head down there and see what sort of assistance we can provide. I've already spoken to the flight master and he's set up a special flight to get you out there.",objectivesText="Speak to Hutou Featherwind to secure a flight to the Pinchwhistle Gearworks.",rewardGold=16980,rewardXP=515,starts={{npcID=85566}},ends={{npcID=81109}},coords={x=0.4,y=0.438,source="quest_giver",zoneID=6722},questType="standard"},
