[35869] = {id=35869,name="A TON of Artifact Fragments",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=8485,mapID=588,objectivesText="Progress: As much as you can carry.",starts={{npcID=82966}},ends={{npcID=82966}},coords={x=0.446,y=0.744,source="quest_giver",zoneID=6941},questType="standard"},
[35870] = {id=35870,name="Basilisk Butcher",level=15,requiredLevel=15,faction="both",expansion=5,zoneID=9786,mapID=543,description="Basilisk is one of Nisha 's favorite meals. This is where she hunts, and that's likely how those Iron Horde bastards were able to capture her. Why would they go to the trouble to subdue her this way? Perhaps together, you and I might learn the answer as we punish them for their transgressions. For now, Nisha 's going to need some food. While I tend to her, will you do her hunting for her?",objectivesText="Collect 9 Basilisk Meat from Stoneshamble Basilisks or Decaying Basilisks. Progress: < Nisha sniffs deeply.>",rewardGold=254700,rewardXP=2090,rewardItems={113504},starts={{npcID=82832}},ends={{npcID=81674}},coords={x=0.442,y=0.616,source="quest_giver",zoneID=6721},questType="standard"},
[35871] = {id=35871,name="A Few Artifact Fragments",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=8485,mapID=588,objectivesText="Progress: Every little bit counts.",starts={{npcID=82893}},ends={{npcID=82893}},coords={x=0.44,y=0.754,source="quest_giver",zoneID=6941},questType="standard"},
