[35959] = {id=35959,name="The Power of Poison",level=30,requiredLevel=30,faction="alliance",expansion=5,zoneID=6722,mapID=542,description="G.V.? We need a full name. A location! I have an idea fer how we can find those out. This is my last vial o' wracking poison. We use it when we need tae extract information from prisoners. Coat yer weapon wi' it and head into the Shattered Hand camp just ahead. Engage them as normal and demand answers - the poison will take care o' the rest.",objectivesText="Interrogate Shattered Hand orcs in the Harvesting Pits to find out the name and location of \"G.V.\".",rewardGold=169800,rewardXP=4115,starts={{npcID=83773}},ends={{npcID=83773}},coords={x=0.536,y=0.274,source="quest_giver",zoneID=6722},questType="standard"},
