[35970] = {id=35970,name="Preservation Capitalization",level=40,requiredLevel=40,faction="both",expansion=5,zoneID=6755,mapID=550,description="I'm looking for precious artifacts. The kind of artifacts that can help solve some of the greatest mysteries of Draenor, and make the Steamwheedle Preservation Society a ton of moolah. And ladies love the moolah, know what I'm sayin? So, get me the artifacts, I'll get the ladies, and you get... wait, what are you looking for again?",objectivesText="Collect a Redtooth Necklace , Purpletooth Necklace , and an Ogre Bust . Progress: What do you find? Anything worth selling? Err.. preserving.",rewardGold=169800,rewardXP=1365,starts={{npcID=83734}},ends={{npcID=83734}},coords={x=0.396,y=0.244,source="quest_giver",zoneID=6755},questType="standard"},
[35971] = {id=35971,name="Tracking: Mill Treasure 7",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6721,mapID=543,questType="standard"},
[35972] = {id=35972,name="Ogre Onslaught",level=40,requiredLevel=40,faction="both",expansion=5,zoneID=6755,mapID=550,description="Those ogres are standing in the way of a full Steamwheedle Preservation excavation. They are brutal, violent, horrible smelling beasts. And if I'm being completely honest with myself, I'm pretty mad they broke my glider. Do me a favor will ya? Wipe 'em off the face of Draenor. It will make everyone's life easier, or at the very least, it will make my life easier.",objectivesText="Kill 3 Ogres and 3 Ogron.",rewardGold=339600,rewardXP=1365,starts={{npcID=83734}},ends={{npcID=83734}},coords={x=0.396,y=0.244,source="quest_giver",zoneID=6755},questType="standard"},
[35973] = {id=35973,name="Brokyo Beatdown",level=40,requiredLevel=40,faction="both",expansion=5,zoneID=6755,mapID=550,description="I'm almost done here, but I can't leave in good conscience. I spotted an ogron named Brokyo that is wearing a priceless ring. Priceless as in crazy expensive. I'm sure Nixxie will give me a promotion if I bring that ring back to her.",objectivesText="Kill Brokyo. Progress: Did you take care of Brokyo?",rewardGold=339600,rewardXP=1365,starts={{npcID=76508}},ends={{npcID=76508}},coords={x=0.406,y=0.13,source="quest_giver",zoneID=6755},questType="standard"},
[35974] = {id=35974,name="Assault on Darktide Roost",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=6719,description="The Iron Horde has Goblins now? Take them out!",objectivesText="Disrupt the Iron Horde and gather intelligence on them.",coords={mapID=539,x=0.6,y=0.84},questType="standard",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Darktide Roost Assaulted"},{orderIndex=5,type=0,amount=10,objectID=85726,text="Kill Iron Horde Vignette"},{orderIndex=8,type=0,amount=100,objectID=83800,text="Kill Iron Horde Soldier"},{orderIndex=3,type=2,amount=100,objectID=234587,text="Collect Rylak Eggs"},{orderIndex=1,type=2,amount=20,objectID=235826,text="Collect Giant Rylak Eggs"},{orderIndex=2,type=2,amount=34,objectID=235823,text="Collect Large Rylak Eggs"},{orderIndex=6,type=0,amount=34,objectID=85728,text="Kill Iron Horde Elite"},{orderIndex=7,type=0,amount=50,objectID=85727,text="Kill Iron Horde Boss"},{orderIndex=9,type=0,amount=334,objectID=85729,text="Kill Iron Horde Peon"},{orderIndex=10,type=3,amount=100,objectID=78183,text="Injured Rylak"},{orderIndex=4,type=2,amount=100,objectID=238984,text="Collect Rylak Eggs"}},worldTaskTitle="Assault on Darktide Roost"},
