[35985] = {id=35985,name="Garrison Campaign: The Broken Precipice",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=6755,mapID=550,description="Hey there! You're the commander of this keep, right? I represent the Steamwheedle Preservation Society. We've been trying to get a very important excavation up and running in Nagrand. Unfortunately, we've had trouble with ogres in the area. In fact, one of our best preservationists recently went missing while surveying the area. He's the third society member we've lost up there this week! We aren't really equipped for a rescue mission... so whad'ya say? We could really use the help.",objectivesText="Find Greblin Fastfizzle .",rewardGold=84900,rewardXP=1365,starts={{npcID=88892}},ends={{npcID=83686}},coords={x=0.548,y=0.148,source="quest_giver",zoneID=7004},questType="standard"},
[35986] = {id=35986,name="Nagrand - Treasure 021 - Bone-Carved Dagger",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6755,mapID=550,ends={{npcID=233532}},questType="standard"},
[35987] = {id=35987,name="Nagrand - Treasure 025 - Genedar Debris",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6755,mapID=550,ends={{npcID=233539}},questType="standard"},
[35996] = {id=35996,name="Vignette: Depthroot",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6721,mapID=543,questType="standard"},
[35997] = {id=35997,name="Empire's Fall",level=40,requiredLevel=40,faction="both",expansion=5,zoneID=6996,mapID=535,description="The Ogre Sorcerer King, Imperator Mar'gok, has mastered magical techniques we would consider on the fringe of arcane science. His felbreakers, among others, can actively dampen or nullify magic. Even fel magic! If we're to locate Gul'dan, we need to figure out how it's done. Acquire a felbreaker's tome from his felbreaker captain and acquire the sigil of the sorcerer king himself - I must know what he knows. Yes, , this means I expect you to storm Highmaul and defeat everyone inside. Get to it!",objectivesText="Collect a Felbreaker's Tome and the Sigil of the Sorcerer King from Highmaul. Progress: What have you found in Highmaul?",rewardGold=509400,rewardXP=1365,rewardItems={115288,115289},starts={{npcID=83823}},ends={{npcID=83823}},coords={x=0.852,y=0.316,source="quest_giver",zoneID=6662},questType="standard"},
[35998] = {id=35998,name="Legacy of the Sorcerer Kings",level=40,requiredLevel=40,faction="both",expansion=5,zoneID=6662,mapID=535,description="For over a thousand years, the ogre sorcerer kings maintained an iron grip over their empire using a variety of artifacts. Trusted lieutenants were given magical gems that allowed them to enforce the emperor's will out in the field. These \" Abrogator Stones \" still maintain their power even today, and can be found scattered throughout the Highmaul complex. Sometimes in clusters. Collect $1oa of these Abrogator Stones for me!",objectivesText="Collect 125 Abrogator Stones from creatures in Highmaul. Your garrison followers may also be able to locate stones in certain missions. Progress: Do you have the stones? I never thought I'd turn to ogres for magical might, but those ancient Sorcerer Kings knew a thing or two about raw arcane energy that would keep Kirin-Tor scholars busy for ages.",rewardGold=169800,rewardXP=1365,rewardItems={115280,115981},starts={{npcID=83823}},ends={{npcID=83823}},coords={x=0.852,y=0.316,source="quest_giver",zoneID=6662},questType="standard"},
[35999] = {id=35999,name="Nagrand - Treasure 071 - Genedar Debris",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6755,mapID=550,ends={{npcID=233549}},questType="standard"},
