[36041] = {id=36041,name="Draenei Tail",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=8485,mapID=588,objectivesText="Progress: NOTHING I HATE MORE THAN THOSE BLUE GOATS! I MEAN, WHAT ARE THOSE THINGS ANYWAYS?",rewardGold=339600,rewardItems={128215,170074},starts={{npcID=83869}},ends={{npcID=83869}},coords={x=0.458,y=0.288,source="quest_giver",zoneID=6941},questType="standard"},
