[36047] = {id=36047,name="We Have Him Now",level=30,requiredLevel=30,faction="horde",expansion=5,zoneID=6722,mapID=542,description="We have Gardul right where we want him, commander. You're far more equipped to face him than I am. Dispose of him, take his formula from his corpse, and grab as many barrels of poison as you can. I'll guard this ramp and make sure no reinforcements come to his aid.",objectivesText="Collect Venomshiv's Secret Formula and 6 Poison Barrels . Progress: Do you have everything we need?",rewardGold=169800,rewardXP=4115,starts={{npcID=83899},{npcID=83903}},ends={{npcID=83903}},coords={x=0.57,y=0.344,source="quest_giver",zoneID=6722},questType="standard"},
[36048] = {id=36048,name="We Have Him Now",level=30,requiredLevel=30,faction="alliance",expansion=5,zoneID=6722,mapID=542,description="We have Gardul right cornered, commander. Ye have a much better chance against him than me. Take him out, grab the formula from his corpse, and grab as many barrels o' poison as ye can carry. I'll stay here and make sure nae reinforcements come to Gardul's aid.",objectivesText="Collect Venomshiv's Secret Formula and 6 Poison Barrels . Progress: I don't want to stick around here any longer than we need to.",rewardGold=169800,rewardXP=4115,starts={{npcID=83900}},ends={{npcID=83900},{npcID=83904}},coords={x=0.57,y=0.344,source="quest_giver",zoneID=6722},questType="standard"},
