[36050] = {id=36050,name="Nagrand - Treasure 028 - Adventurer's Pouch",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6755,mapID=550,ends={{npcID=233623}},questType="standard"},
[36051] = {id=36051,name="Nagrand - Treasure 035 - Grizzlemaw's Favorite Bone",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6755,mapID=550,ends={{npcID=233626}},questType="standard"},
[36054] = {id=36054,name="Sealing Fate: Gold",level=40,requiredLevel=40,faction="both",expansion=5,zoneID=7333,objectivesText="Progress: Gold is indeed treasure, but additional treasure for gold? That's the offer I present. A Seal of Twisted Fate twists time, providing a burst of additional luck just when you need it. Remember, you can only obtain three Seals of Twisted Fate per week. This counts as one of those three. Next week, I may have others.",rewardCurrencies={{id=1129,amount=1}},starts={{npcID=87391}},ends={{npcID=87391},{npcID=88570}},coords={x=0.516,y=0.618,source="quest_giver",zoneID=7332},questType="standard"},
[36055] = {id=36055,name="Sealing Fate: Apexis Crystals",level=40,requiredLevel=40,faction="both",expansion=5,zoneID=7333,objectivesText="Progress: You seem like the type who is always seeking power, no? These seals provide an investment, if you will, in your future power. I also seek power, but one that is a more immediate and tangible. If you manage to find some crystals, we can make a deal. Remember, you can only obtain three seals per week. This counts as one of those three. Next week, I may have others.",rewardCurrencies={{id=1129,amount=1}},starts={{npcID=87391}},ends={{npcID=87391},{npcID=88570}},coords={x=0.516,y=0.618,source="quest_giver",zoneID=7332},questType="standard"},
[36056] = {id=36056,name="Sealing Fate: Garrison Resources",level=40,requiredLevel=40,faction="both",expansion=5,zoneID=7333,objectivesText="Progress: That extravagant fortification you built is impressive. Tell me, does it keep all the bad things away? Yes? How about an exchange for a bit of fate? A wall can be thick enough, but one is never lucky enough. Besides, safety can be so overpriced... Remember, you can only obtain three seals per week. This counts as one of those three. Next week, I may have others.",rewardCurrencies={{id=1129,amount=1}},starts={{npcID=87391}},ends={{npcID=87391},{npcID=88570}},coords={x=0.516,y=0.618,source="quest_giver",zoneID=7332},questType="standard"},
[36057] = {id=36057,name="Sealing Fate: Honor",level=40,requiredLevel=40,faction="both",expansion=5,zoneID=7333,objectivesText="Progress: To kill another for honor is peculiar...a relic of an older time, perhaps? No matter, this seal is of no use to me. It is far too burdened with power for me to control. Remember, you can only collect three seals per week. This counts as one of those three. Next week, I may have others.",rewardCurrencies={{id=1129,amount=1}},starts={{npcID=87391}},ends={{npcID=87391},{npcID=88570}},coords={x=0.516,y=0.618,source="quest_giver",zoneID=7332},questType="standard"},
[36059] = {id=36059,name="A Worthy Vessel",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6722,mapID=542,description="The time has come, $p. Awaken the Talon King from his long slumber. Call him into this world so that he may destroy our enemies!",objectivesText="Awaken the Talon King.",rewardGold=169800,rewardXP=4115,starts={{npcID=80153}},ends={{npcID=84122}},coords={x=0.458,y=0.456,source="quest_giver",zoneID=6722},questType="standard"},
