[36085] = {id=36085,name="On Ebon Wings",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6722,mapID=542,description="Now we bring our fight to the Adherents. Raastok is certain his new invention will give us control of the Apexis weapons, but we must get close - very close. Ka'alu and her ravens will fly us to the Windswept Terrace. We shall gain a foothold there before pressing on to the Terrace of Dawn.",objectivesText="Slay 8 Adherents and Windkeeper Koreyx . Speak with Ka'alu for a ride to Windswept Terrace. Progress: Quickly, we must not let this opportunity pass.",rewardGold=169800,rewardXP=4115,starts={{npcID=84276}},ends={{npcID=84262}},coords={x=0.514,y=0.502,source="quest_giver",zoneID=6722},questType="standard"},
