[36152] = {id=36152,name="Cataclysm 84-85",level=1,requiredLevel=1,faction="none",expansion=5,rewardGold=114000,rewardXP=400,rewardItems={156689},questType="standard"},
[36160] = {id=36160,name="Garrison Campaign: Every Rose Has Its Thorn",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=7078,mapID=582,description="These feelings are too strong. I can no longer hide my love away. I need to tell Thorn the truth. I need to tell Thorn, I love her. She mentioned her favorite flower is a rose. I've been so heads down with my work... I don't even know where I could find a rose on Draenor.",objectivesText="Find Baros a rose for Thorn. Progress: We are under attack!",rewardGold=169800,rewardXP=1365,rewardItems={114779},starts={{npcID=77209}},ends={{npcID=84270}},coords={x=0.32,y=0.314,source="quest_giver",zoneID=7078},questType="standard"},
[36161] = {id=36161,name="Where There Is Smoke...",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=7078,mapID=582,description="Burning Blade assassins have infiltrated the garrison. We must not let them take the Heart of Gorgorek, commander.",objectivesText="Kill Rag'sla Thunkblade , Akatha Blazeburn , and Drek the Firecaller .",rewardGold=169800,rewardXP=1365,starts={{npcID=84684}},ends={{npcID=84511}},coords={x=0.294,y=0.344,source="quest_giver",zoneID=7078},questType="standard"},
[36162] = {id=36162,name="A Stolen Heart",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=7078,mapID=582,description="Don't let Azuka take the heart, commander. Don't let her win.",objectivesText="Kill Azuka Bladefury .",rewardGold=169800,rewardXP=1365,starts={{npcID=84511}},ends={{npcID=84268}},coords={x=0.314,y=0.334,source="quest_giver",zoneID=7078},questType="standard"},
[36163] = {id=36163,name="Garrison Campaign: The Exarch's Call",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=6719,mapID=539,description="Ahhh, just the I were hopin' ta see, my dear. Yrel stopped by the garrison earlier lookin' fer ya. Such a lovely lass, that one! Asked me all about ma family back home when I be feelin' homesick. Bless her. Anyway, what were I goin' on about ag'in? Oh! She asked if ye'd meet her at Elodor to the east. She's been invited by the draenei council ta face the Exarch trials, whatever those may be. Anyway, ye'd better scooch!",objectivesText="Speak to Yrel at Elodor in Shadowmoon Valley.",rewardGold=339600,rewardXP=1365,starts={{npcID=82776}},ends={{npcID=73395}},coords={x=0.33,y=0.348,source="quest_giver",zoneID=7078},questType="standard"},
[36164] = {id=36164,name="The Trial of Courage",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=6720,mapID=539,description="An Exarch must be a pillar of strength, and no greater strength is there than the courage to face danger. Far to the northwest, among the snowy crags of Frostfire Ridge, lives a primal fury named Everburn . Only when you face one of these creatures eye to eye, will you know the extent of your courage.",objectivesText="Kill Everburn .",rewardGold=339600,rewardXP=1365,starts={{npcID=80078}},ends={{npcID=84973}},coords={x=0.558,y=0.328,source="quest_giver",zoneID=6719},questType="standard"},
[36165] = {id=36165,name="No Time to Waste",level=30,requiredLevel=30,faction="alliance",expansion=5,zoneID=6722,mapID=542,description="We're in luck, commander. The antidote is relatively easy tae make. I've made a small amount with what I had on me. You should take it tae Kolrigg before it's too late. It'll keep him alive long enough for me tae make more.",objectivesText="Administer the Spiresalve to Kolrigg Stoktron in Southport. Progress: <Kolrigg grumbles incoherently.>",rewardGold=16980,rewardXP=515,rewardItems={116394},starts={{npcID=83900},{npcID=83904}},ends={{npcID=84261}},coords={x=0.57,y=0.344,source="quest_giver",zoneID=6722},questType="standard"},
[36166] = {id=36166,name="No Time to Waste",level=30,requiredLevel=30,faction="horde",expansion=5,zoneID=6722,mapID=542,description="Commander, we're in luck. The antidote recipe is fairly simple. I was able to make a small amount with what I had on me. You should take it to Lunzul before it's too late. It should keep her alive long enough for me to make more.",objectivesText="Administer the Spiresalve to Lunzul in Axefall. Progress: < Lunzul grumbles incoherently.>",rewardGold=16980,rewardXP=515,rewardItems={116394},starts={{npcID=83903}},ends={{npcID=84259}},coords={x=0.57,y=0.344,source="quest_giver",zoneID=6722},questType="standard"},
[36167] = {id=36167,name="The Trial of Heart",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=6755,mapID=539,description="The Trial of Heart is a test of your willingness to persevere in the face of great adversity. Far to the west, there is a rangari outpost at Cerulean Lagoon. They have sent a request for help. Some sort of infection is making everyone in the area sick. They desperately need aid. Go and seek out the rangari stationed there. Help them find the cause of this terrible ailment.",objectivesText="Speak to Yrel at Cerulean Lagoon, then find out the cause of the poisonous mist.",rewardGold=339600,rewardXP=1365,starts={{npcID=80079}},ends={{npcID=84975}},coords={x=0.624,y=0.262,source="quest_giver",zoneID=6719},questType="standard"},
[36168] = {id=36168,name="The Trial of Faith",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=8485,mapID=539,description="No Exarch trial is complete without a holy pilgrimage to the sacred resting place of our fallen champions. On the way, I ask that you take Vindicator Maraad's ashes and lay them to rest within the hallowed halls of Auchindoun. There, the spirits of our fallen ancestors will test Yrel's greatest weakness. Good luck.",objectivesText="Speak to Soulbinder Tuulani outside the entrance to Auchindoun, then pass the Trial of Faith.",rewardGold=339600,rewardXP=1365,starts={{npcID=80073}},ends={{npcID=84974}},coords={x=0.624,y=0.262,source="quest_giver",zoneID=6719},questType="standard"},
[36169] = {id=36169,name="The Trial of Champions",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=6719,mapID=539,description="The first three trials you have passed with flying colors. For the final trial, you shall face the Exarch Council. Speak to me when you are ready to begin.",objectivesText="Defeat the Exarch Council.",rewardGold=509400,rewardXP=1365,rewardItems={119144,251477},starts={{npcID=84974}},ends={{npcID=84974}},coords={x=0.75,y=0.578,source="quest_giver",zoneID=6719},questType="standard"},
[36170] = {id=36170,name="Treasure: Femur of Improbability",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6721,mapID=543,rewardGold=171000,rewardXP=200,ends={{npcID=233917}},questType="standard"},
[36171] = {id=36171,name="Botani Invasion!",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=7004,description="The plants seem different today. Grass blades bend against the wind and catch on my boots. Twice this morning a tree branch struck my helmet as it fell.",objectivesText="Repel the botani invasion of your garrison. (Speak with Sergeant Crowler again to begin) Progress: We must hold the line!",rewardGold=169800,rewardXP=8200,starts={{npcID=78564}},ends={{npcID=78564}},coords={x=0.382,y=0.32,source="quest_giver",zoneID=7078},questType="standard"},
[36174] = {id=36174,name="Nagrand - Treasure 081 - Bounty of the Elements",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6755,mapID=550,ends={{npcID=233973}},questType="standard"},
[36176] = {id=36176,name="A Call for Huntsman",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,mapID=539,description="\"Any and all competitors are welcome to test their skills in a friendly hunting challenge.\"",objectivesText="Deliver the Dirty Note to Fanara in Embaari Village to join the competition. Provided item:",rewardGold=79250,rewardXP=1415,starts={{npcID=75043}},ends={{npcID=84385}},questType="standard"},
[36177] = {id=36177,name="Friendly Competition",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=7078,mapID=539,description="So you wish to join the competition, ? Best of luck to you. Be the first to gather a sack full of hides and talons from local wildlife and return them to me before the other competitors! Winner earns the opportunity for an apprenticeship under craftsman Garaal. Good luck!",rewardGold=84400,rewardXP=1415,starts={{npcID=84385}},ends={{npcID=84385}},coords={x=0.442,y=0.408,source="quest_giver",mapID=539},questType="standard"},
[36178] = {id=36178,name="Vignette: Mandrakor the Night Hunter",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6721,mapID=543,questType="standard"},
[36179] = {id=36179,name="Unwanted Pests",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6722,mapID=542,description="Those creatures out in the shallows keep busting the turrets as fast as we can get them operational. I'm supposed to go clear them out but my blaster is completely busted; the damn thing barely can light a candle like this! Could you do me a favor and go kill a few of those pests while I get my blaster fixed at the shop? Just let Gazwitz know you covered for me so I can get reimbursed for the repair.",objectivesText="Kill 10 Spore Drifters or Fungal Hulks in Sporemist Shallows.",rewardGold=169800,rewardXP=4115,starts={{npcID=85062}},ends={{npcID=81128}},coords={x=0.624,y=0.738,source="quest_giver",zoneID=6722},questType="standard"},
[36182] = {id=36182,name="Tree-i-cide",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=7004,description="Commander, the goblins have brought you a present. They call it the Tree Murderer 9000. What's it do? I reckon it murders trees - but more importantly it will allow for the harvesting of large timber. Do you know how much timber a large tree holds? Me neither, but I bet it's a lot! There's a large piece of timber ready to be murdered nearby. Why don't you give the contraption a test run? Bring me back whatever it harvests and I'll put it to good use.",objectivesText="Harvest a Timber Sample from Large Timber and return it to Lumber Lord Oktron . Progress: Did you harvest that timber sample yet?",rewardGold=679200,rewardXP=2830,rewardCurrencies={{id=824,amount=150}},starts={{npcID=84247}},ends={{npcID=84247}},coords={x=0.518,y=0.61,source="quest_giver",zoneID=7004},questType="standard"},
[36183] = {id=36183,name="Admiral Taylor",level=30,requiredLevel=30,faction="horde",expansion=5,zoneID=6722,mapID=542,description="Admiral Taylor had figured out who was behind all this. He told us to save who we could... he wanted to handle matters himself. We never heard from him again, but we have our orders. Please... please find him. He went towards the farm.",objectivesText="Find Admiral Taylor at Admiral Taylor 's Farm.",rewardGold=339600,rewardXP=5145,rewardItems={114945,118079,118080,118081,118082,118083,118084,118085,118086},rewardChoices={114945,118079,118083,118086,118080,118081,118082,118084,118085},starts={{npcID=82278},{npcID=82293}},ends={{npcID=82375}},coords={x=0.376,y=0.538,source="quest_giver",zoneID=6722},questType="standard"},
[36184] = {id=36184,name="Mother Lode",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6722,mapID=542,questType="standard"},
[36185] = {id=36185,name="Fair Trade",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,mapID=539,description="Alright. Here you go. Be sure to deliver them to Garaal quickly. He has a heavy interest in detail and fine craftsmanship. He'll surely appreciate your work.",objectivesText="Garaal awaits your delivery. Provided item:",rewardGold=169800,rewardXP=1415,rewardItems={111818,115358},starts={{npcID=84385}},ends={{npcID=84492}},coords={x=0.442,y=0.408,source="quest_giver",zoneID=6719},questType="standard"},
[36186] = {id=36186,name="Vignette: Greldrok the Cunning",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6721,mapID=543,questType="standard"},
[36189] = {id=36189,name="Easing into Lumberjacking",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=7078,description=", we're going to need a lot of lumber if we're going to build this garrison into a suitable fortress. That means we're going to have to do a little work. While I certainly wouldn't ask you to dirty your hands with manual labor, I do need you to go out and find timber for our mill. Once you mark a tree a lumberjack will come chop it down and give you the timber. Let's give our lumberjacks a test run. There's a tree nearby!",objectivesText="Harvest a Timber Sample from Small Timber and return it to Justin Timberlord . Progress: This garrison isn't going to build itself, commander! We need timber!",rewardGold=14300,rewardXP=1770,rewardCurrencies={{id=824,amount=50}},starts={{npcID=84248}},ends={{npcID=84248}},coords={x=0.348,y=0.496,source="quest_giver",zoneID=7078},questType="standard"},
[36192] = {id=36192,name="Turning Timber into Profit",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=7078,description="Now that you know how to put lumberjacks to work harvesting timber , we're going to create a work order for your mill. But first we're going to need some timber to process! All around Draenor are juicy trees ripe for the chopping. Go out and find suitable timber for the lumber mill. Come back here when you have enough and we'll get started on a work order. And as usual, let the lumberjacks do the hard work. Just keep 'em protected. Draenor's a dangerous place!",objectivesText="Collect 10 pieces of Timber from around Draenor and then Place a Work Order at your Garrison's Lumber Mill. Progress: We need lots and lots of timber , commander!",rewardGold=509400,rewardXP=2125,rewardCurrencies={{id=824,amount=100}},starts={{npcID=84248}},ends={{npcID=84248}},coords={x=0.348,y=0.496,source="quest_giver",zoneID=7078},questType="standard"},
[36193] = {id=36193,name="An Act of Kindness",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=6755,mapID=550,description="I know that you and Vindicator Yrel are here on important matters, but I must ask you a favor. A squad of rangari left on patrol just before the poisonous mist set in. If they were caught out in the swamp, they are surely in trouble. Harvest the Restorative Goldcaps growing among the reeds, and use them to restore any fallen rangari that you find. If you find yourself in trouble, eat one to combat the poison.",objectivesText="Use Restorative Goldcaps to revive fallen rangari. Progress: Were you able to find the others?",rewardGold=339600,rewardXP=1365,starts={{npcID=84459}},ends={{npcID=84459}},coords={x=0.494,y=0.166,source="quest_giver",zoneID=6755},questType="standard"},
[36194] = {id=36194,name="Sharper Blades, Bigger Timber",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=7078,description="Incredible news, Commander . Your ever-loyal servant has managed to secure us commandojacks. Now maybe you don't know what a commandojack is, so let me explain: they're like lumberjacks, only highly trained in the art of killing. Mostly they're out of work mercenaries and assassins. What this means is that we can now cut medium sized timber - but first we need to give these commandojacks a test run. There's a suitable tree nearby. Good luck!",objectivesText="Harvest a Timber Sample from Timber and return it to Justin Timberlord . Progress: Did you harvest that timber sample yet?",rewardGold=339600,rewardXP=1770,rewardCurrencies={{id=824,amount=100}},starts={{npcID=84248}},ends={{npcID=84248}},coords={x=0.348,y=0.496,source="quest_giver",zoneID=7078},questType="standard"},
[36195] = {id=36195,name="Tree-i-cide",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=7078,description="Commander, your engineers have brought you a present. They call it the Wood Annihilator XXI the Third, Jr. What's it do? I reckon it annihilates trees - but more importantly it will allow for the harvesting of large timber. Do you know how much timber a large tree holds? Me neither, but I bet it's a lot! There's a large piece of timber ready to be annihilated nearby. Why don't you give the contraption a test run? Bring me back whatever it harvests and I'll put it to good use.",objectivesText="Harvest a Timber Sample from Large Timber and return it to Justin Timberlord . Progress: Did you harvest that timber sample yet?",rewardGold=679200,rewardXP=2830,rewardCurrencies={{id=824,amount=150}},starts={{npcID=84248}},ends={{npcID=84248}},coords={x=0.348,y=0.496,source="quest_giver",zoneID=7078},questType="standard"},
[36199] = {id=36199,name="Moonshell Claws",level=20,requiredLevel=20,faction="alliance",expansion=5,zoneID=6719,mapID=539,description="I will help you, but you are going to need to prove to me that you are not only a worthy fisherman, but also a fearless warrior. The beach southeast of us is full of moonshell crawlers. Slaughter them and bring their claws back to me. They should work well as bait in these local waters.",objectivesText="Prove your worth to Madari by collecting 4 Moonshell Claws . Progress: Have those claws for me?",rewardGold=169800,rewardXP=2765,starts={{npcID=84372}},ends={{npcID=84372}},coords={x=0.27,y=0.066,source="quest_giver",zoneID=6719},questType="standard"},
[36201] = {id=36201,name="Proving Your Worth",level=20,requiredLevel=20,faction="alliance",expansion=5,zoneID=6719,mapID=539,description="Now that you have proven yourself as a warrior, let's see how your fishing skills hold up. I have fashioned a bait out of the moonshell claws you brought me. Use it to catch the shadow sturgeon in these coastal waters.",objectivesText="Prove your worth to Madari by catching 5 Shadow Sturgeon using the supplied bait. Progress: Catch those sturgeon?",rewardGold=169800,rewardXP=2765,starts={{npcID=84372}},ends={{npcID=84372}},coords={x=0.27,y=0.066,source="quest_giver",zoneID=6719},questType="standard"},
[36202] = {id=36202,name="Anglin' In Our Garrison",level=20,requiredLevel=20,faction="alliance",expansion=5,zoneID=7078,mapID=539,description="You have proven your worth, traveler. Now take this eventide fishing journal back to your garrison and study up. You will be catching all you can eat in no time.",rewardGold=169800,rewardXP=2765,rewardItems={114875,248335},starts={{npcID=84372}},ends={{npcID=77733}},coords={x=0.27,y=0.066,source="quest_giver",mapID=539},questType="standard"},
[36203] = {id=36203,name="Treasure: Goren Egg",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6721,mapID=543,ends={{npcID=234054}},questType="standard"},
[36204] = {id=36204,name="Vignette: Gorger the Hungry",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6721,mapID=543,questType="standard"},
[36205] = {id=36205,name="The Fractured Hammer",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,mapID=525,description="It is obvious that this elaborate smithing hammer has seen better days. Now fractured and dirty, it is merely a shadow of its former self. One thing is certain, its previous owner was neither ogre nor Iron Horde. Perhaps someone at Stonefang Outpost would know who this belongs to.",objectivesText="Search Stonefang Outpost for the hammer's previous owner. Progress: What do you want, <race>?",rewardGold=16980,rewardXP=175,ends={{npcID=78989}},coords={mapID=525,source="quest_giver",x=0.412,y=0.528},questType="standard"},
[36207] = {id=36207,name="Waruk the Frostforger",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,mapID=525,description="Many say my father was a legendary blacksmith, Waruk the Frostforger they called him. They will tell you tales of his mighty weapons, crafted with nothing more than ice and steel. Waruk the Lieforger, I call him. He promised he wouldn't be gone long, \"I must support our troops!\" he said. Why did he have to go? Why did they let him get captured!? I have no more need for broken tools than I do broken promises. His grave is east of here, you can leave this with the rest of his unwanted belongings.",objectivesText="Deliver Waruk's hammer to his grave site. Progress: Greetings <race>, what brings you to this old orc's grave?",rewardGold=19815,rewardXP=355,starts={{npcID=78989}},ends={{npcID=84494}},coords={x=0.412,y=0.528,source="quest_giver",zoneID=6720},questType="standard"},
[36208] = {id=36208,name="The Crystal Shard",level=15,requiredLevel=15,faction="alliance",expansion=5,zoneID=6721,mapID=543,description="I'm glad you arrived when you did. The Laughing Skull orcs practice some strange spirit magic, but one of their traditions could be quite useful in our situation. While I make preparations, can you gather the reagents? First, we'll need crystals from the husks of goren corpses. You can find their bodies in the canyon.",objectivesText="Collect 25 Goren Crystals from Longtooth Gorgers. Progress: I have learned some of the Laughing Skull traditions. This is less strange than many.",rewardGold=254700,rewardXP=2090,rewardItems={112863,112864,112865,112911,119076,119085},rewardChoices={112863,112864,112865,119076,119085},starts={{npcID=82610}},ends={{npcID=82610}},coords={x=0.462,y=0.55,source="quest_giver",zoneID=6721},questType="standard"},
[36209] = {id=36209,name="What's Under There?",level=15,requiredLevel=15,faction="alliance",expansion=5,zoneID=6721,mapID=543,description="It is done. With this enchantment, not only can you roam amongst the goren freely, but you can move as they do. Your travels through the canyon are now made easier. You have safe access to places otherwise impossible to reach. Perhaps these tunnels will lead to more information that could be used against the Iron Horde.",objectivesText="Use the goren disguise to explore locations in Gorgrond . Progress: That goren disguise smells awful.",rewardGold=254700,rewardXP=2090,rewardItems={112958,114963},starts={{npcID=82610}},ends={{npcID=82610}},coords={x=0.462,y=0.55,source="quest_giver",zoneID=6721},questType="standard"},
[36210] = {id=36210,name="Hard Shell",level=15,requiredLevel=15,faction="alliance",expansion=5,zoneID=9786,mapID=543,description="I have already learned much from watching the Laughing Skull. Traveling through goren tunnels was thought to be impossible due to the acid they leave behind, but the orcs found a way around it. We will need some of the shells of goren within the canyon. If you see any of their tunnel craters ready to burst, approach them and goren will come pouring out. This way, you can kill many at once and find the shells more quickly.",objectivesText="Collect 9 Goren Shells from Boneyard Gorgers. Progress: Goren seem willing to eat anything in their path, alive or otherwise.",rewardGold=254700,rewardXP=2090,rewardItems={112786},starts={{npcID=82610}},ends={{npcID=82610}},coords={x=0.462,y=0.55,source="quest_giver",zoneID=6721},questType="standard"},
[36211] = {id=36211,name="6.0 Tanaan - Boots Bootstrap",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6720,mapID=525,questType="standard"},
[36212] = {id=36212,name="6.0 Tanaan - Wrist Bootstrap",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6720,mapID=525,questType="standard"},
[36213] = {id=36213,name="6.0 Tanaan - Ring Bootstrap",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6720,mapID=525,questType="standard"},
[36214] = {id=36214,name="6.0 Tanaan - Hands Bootstrap",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6720,mapID=525,questType="standard"},
[36219] = {id=36219,name="Garrison Campaign: The Ring of Blood",level=40,requiredLevel=40,faction="both",expansion=5,zoneID=6755,mapID=550,description="Hey Champ, You were out when I stopped by. I've got a sweet gig set up at the Ring of Blood in Nagrand. Lots of ogres looking for the next big fight. Big money. You in? Who am I kidding, who wouldn't be interested in fame, fortune, and brawlin'? I'll meet you at my stash so we can talk a bit in private before your big debut.",objectivesText="Speak to Gurgthock at Gurgthock 's Stash in Nagrand.",rewardGold=16980,rewardXP=685,starts={{npcID=234243}},ends={{npcID=84637}},coords={x=0.438,y=0.481,source="quest_giver",zoneID=7004},questType="standard"},
[36220] = {id=36220,name="How Tough Are You?",level=40,requiredLevel=40,faction="both",expansion=5,zoneID=6755,mapID=550,description="Mogor's holding a special match over at the Ring of Blood to crown the new Blood Champion and I think you have what it takes! Now, these ogres respect one thing and one thing only: badass...ness. They have a big fella at the front door making sure only the toughest gladiators enter the proving grounds. If you're in, kill the grizzled gladiator Lug'dol at the tower just up the road and present his head to Kroggol the Wall . That oughta show 'em what you're made of.",objectivesText="Kill Lug'dol and present his head to Kroggol the Wall outside the Gorian Proving Grounds. Progress: Nobody gets in da proving grounds unless I say so.",rewardGold=169800,rewardXP=1365,starts={{npcID=84637}},ends={{npcID=84720}},coords={x=0.63,y=0.36,source="quest_giver",zoneID=6755},questType="standard"},
[36221] = {id=36221,name="Entry Fee",level=40,requiredLevel=40,faction="both",expansion=5,zoneID=6755,mapID=550,description="You looking for da Ring of Blood? HAH! That good one. Not just anybody able to compete in da ring. You gotta pay the entry fee: fifty blood marks. How do you get them? Oh, tiny one, you killing me! Dat one is yours. You kill others in da proving grounds to get da rest. Take dem to Wodin da troll servant by Mogor when you done. Don't talk to Mogor, though. Mogor da boss.",objectivesText="Gather 50 Blood Stones and bring them to Wodin the Troll Servant. Progress: Don't be wastin' my time, <race>. What business do you be havin' with Mogor?",rewardGold=169800,rewardXP=1365,starts={{npcID=84720}},ends={{npcID=84784}},coords={x=0.568,y=0.192,source="quest_giver",zoneID=6755},questType="standard"},
[36222] = {id=36222,name="The Champion of Blood",level=40,requiredLevel=40,faction="both",expansion=5,zoneID=6755,mapID=550,description="You have da blood stones required as proof of your worth. Hmm. Yes, you might be da champion Mogor be lookin' for. You be one of only two to complete da blood stone trial. Da two of ya be fightin' for da glory of becoming Blood Champion. Speak to Gurgthock and we be seein' if you be a champion... or just another stain on da arena floor.",objectivesText="Speak to Gurgthock to participate in the Blood Champion fight. Progress: Only da very best be havin' a chance at bein' da Blood Champion, mon.",rewardGold=169800,rewardXP=1365,starts={{npcID=84784}},ends={{npcID=84784}},coords={x=0.568,y=0.13,source="quest_giver",zoneID=6755},questType="standard"},
[36223] = {id=36223,name="Leave Every Soldier Behind",level=15,requiredLevel=15,faction="alliance",expansion=5,zoneID=6721,mapID=543,description="The ogron possess something of value to the Iron Horde. I am sure they're unaware, likely just bored and in need of something to torture. We could simply leave them to their fate, but we should follow up on this clue. With any luck, it will help us stop the Iron Horde from turning Gorgrond 's most fearsome creatures into weapons. Try to find Corporal Thukmar and his notes.",objectivesText="Find Corporal Thukmar and recover his intel. Progress: Again you've done well, friend.",rewardGold=254700,rewardXP=2090,rewardItems={113629},starts={{npcID=82610}},ends={{npcID=84131}},questType="standard"},
[36230] = {id=36230,name="The Restless Spirit",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,mapID=525,description="This hammer was once used to craft magnificent weapons for my Frostwolf brothers and sisters. When I was taken prisoner by the Thunderlords, however, I refused to wield it. How could I craft weapons to be used against my own people? It saddens me to see that it has been damaged and abused. I wished to one day pass it down to Kugra, but now, her anger prevents her from even visiting my grave. Please $p, can you help me repair my hammer and seek revenge on those that caused this? For Kugra....",objectivesText="Slay Kurgthuk the Merciless and use Waruk's hammer to salvage equipment from the Thunderlord orcs. Progress: So, it is done?",rewardGold=169800,rewardXP=1415,starts={{npcID=84494}},ends={{npcID=84494}},coords={x=0.46,y=0.486,source="quest_giver",zoneID=6720},questType="standard"},
[36236] = {id=36236,name="The Cryptic Tome of Tailoring",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=7078,mapID=539,description="The different sections of the tome describe tailoring techniques that seem strange compared to traditional methods. The author's name does not appear anywhere in the tome. Maybe someone in your garrison knows more about the book's origins.",objectivesText="Speak to Aerun in your garrison. Progress: What have you there, child?",rewardGold=16980,rewardXP=175,ends={{npcID=84776}},questType="standard"},
[36238] = {id=36238,name="Mending A Broken Heart",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,mapID=525,description="$p, thank you for avenging my death... but I have just one more favor to ask of you. If you help me see this through, I will forever be in your debt. Take these items and meet me at the forge in Stonefang Outpost. I have imbued them with a portion of my essence, but we still need the aid of another to reforge the hammer. It is time for me to reconcile with Kugra, so that we both may finally find peace....",objectivesText="Meet Waruk at Stonefang Outpost. Progress: My father... but, how did you....",rewardGold=169800,rewardXP=1415,rewardItems={111813,115356},starts={{npcID=84494}},ends={{npcID=78989}},coords={x=0.46,y=0.486,source="quest_giver",zoneID=6720},questType="standard"},
[36239] = {id=36239,name="A Mysterious Satchel",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,mapID=539,description="An empty satchel with an old, magical aura. It appears quite dilapidated, with remnants of herbs and mushrooms along the inner lining. Perhaps exploring Umbrafen will offer a clue.",objectivesText="Find the satchel's owner. Provided item:",rewardGold=32900,rewardXP=1415,ends={{npcID=84724}},coords={mapID=539,source="quest_giver",x=0.578,y=0.215},questType="standard"},
[36240] = {id=36240,name="Slow and Steady",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,mapID=539,description="Excellent! When you've collected enough herbs from the local wildlife, return to me and I'll craft them into an ink for Master Ardule. The sporebats and giants should have what you're looking for. And remember, be careful!",objectivesText="Gather the herbs and return to Sha'la . Progress: Ah, these are just what I was looking for!",rewardGold=169800,rewardXP=1415,starts={{npcID=84724}},ends={{npcID=84724}},coords={x=0.578,y=0.216,source="quest_giver",zoneID=6719},questType="standard"},
[36241] = {id=36241,name="The Power of Preservation",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,mapID=539,description="The ink is very precious to our people. It has the ability to preserve ancient texts. Master Ardule can explain further. He's just inside.",objectivesText="Deliver the ink to Master Ardule.",rewardGold=169800,rewardXP=1415,rewardItems={111815,111923,120136},starts={{npcID=84724}},ends={{npcID=84728}},coords={x=0.578,y=0.216,source="quest_giver",zoneID=6719},questType="standard"},
[36242] = {id=36242,name="Where There Is Smoke...",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=7004,mapID=590,description="You garrison is under attack by the Burning Blade! Kill the Burning Blade masters that are leading the assault and report back to Warmaster Zog .",objectivesText="Kill Rag'sla Thunkblade , Akatha Blazeburn , and Drek the Firecaller .",rewardGold=169800,rewardXP=1365,starts={{npcID=79740},{npcID=233956}},ends={{npcID=79740}},coords={x=0.538,y=0.542,source="quest_giver",zoneID=7004},questType="standard"},
[36243] = {id=36243,name="Spires - Treasure 001 - Outcast's Basket",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6722,mapID=542,ends={{npcID=234147}},questType="standard"},
[36244] = {id=36244,name="Spires - Treasure 002 - Misplaced Scrolls",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6722,mapID=542,starts={{npcID=9728}},ends={{npcID=234154}},questType="standard"},
[36245] = {id=36245,name="Spires - Treasure 004 - Relics of the Outcasts",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6722,mapID=542,starts={{npcID=9728}},ends={{npcID=234155}},questType="standard"},
[36246] = {id=36246,name="Spires - Treasure 005 - Fractured Sunstone",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6722,mapID=542,ends={{npcID=234157}},questType="standard"},
[36247] = {id=36247,name="Spires - Treasure 007 - Lost Herb Satchel",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6722,mapID=542,ends={{npcID=234159}},questType="standard"},
[36248] = {id=36248,name="A Stolen Heart",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=7004,mapID=590,description="This invasion is clearly an attempt to seize the Heart of Gorgorek. We need to fortify our guard before it's too late!",objectivesText="Defeat Azuka Bladefury .",rewardGold=169800,rewardXP=1365,starts={{npcID=79740}},ends={{npcID=79740}},coords={x=0.538,y=0.542,source="quest_giver",zoneID=7004},questType="standard"},
[36249] = {id=36249,name="Active Choice: Lumber Mill",level=1,requiredLevel=1,faction="horde",expansion=5,zoneID=6721,mapID=543,questType="standard"},
[36250] = {id=36250,name="Active Choice: Lumber Mill",level=1,requiredLevel=1,faction="horde",expansion=5,zoneID=6721,mapID=543,questType="standard"},
[36251] = {id=36251,name="Active Choice: Sparring Arena",level=1,requiredLevel=1,faction="horde",expansion=5,zoneID=6721,mapID=543,questType="standard"},
[36252] = {id=36252,name="Active Choice: Sparring Arena",level=1,requiredLevel=1,faction="horde",expansion=5,zoneID=6721,mapID=543,questType="standard"},
[36255] = {id=36255,name="Enchanted Highmaul Bracer",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=7004,mapID=525,description="A powerful enchantment emanates from these ancient Highmaul bracers. Maybe Yu'rina the Mystic , your garrison enchanting quartermaster, can tell you more about the bracer.",objectivesText="Take the bracer to Yu'rina the Mystic in your Garrison. Provided item:",rewardGold=16980,rewardXP=175,ends={{npcID=83482}},questType="standard"},
[36256] = {id=36256,name="The Arakkoan Enchanter",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,mapID=525,description="The arakkoa said it was going to investigate an anomaly in the Cracking Plains that might be related to another armor piece.",objectivesText="Find Delath on the edge of the Cracking Plains to the north. Progress: Greetings Enchanter. I can see you are acquainted with the art. Good, good. Perhaps you and I can help each other.",rewardGold=16980,rewardXP=175,rewardItems={115350},starts={{npcID=83482}},ends={{npcID=84739}},coords={x=0.474,y=0.378,source="quest_giver",zoneID=7004},questType="standard"},
[36257] = {id=36257,name="Failed Apprentice",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,mapID=525,description="Oru'kai was the first ogre mage to master the art of enchanting. Upon his death, his items were scattered across Draenor. I have tracked his scepter to the field you see before us. As you can see, the scepter's enchantment is making it difficult to retrieve. A would-be apprentice, Torag Stonefury , took one of Oru'kai's rings in to break the enchantment, but he failed and became trapped in ice. Free Torag, take the ring, and complete his task, and I will consider a reward.",objectivesText="Find and release Torag from his icy prison.",rewardGold=127350,rewardXP=1060,starts={{npcID=84739}},ends={{npcID=84747}},coords={x=0.544,y=0.518,source="quest_giver",zoneID=6720},questType="standard"},
[36260] = {id=36260,name="Oru'kai's Scepter",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,mapID=525,description="If I had known being an enchanter was this dangerous, I would have stayed in Wor'gol. Here, take this ring. The bird man told me to use the ring on the scepter to nullify the enchantment. Bring the scepter back to him and maybe he will teach you what he promised to teach me.",objectivesText="Retrieve Oru'kai's scepter and return it to Delath. Progress: Do you have it? Give it to me.",rewardGold=169800,rewardXP=1415,rewardItems={111817,111922},starts={{npcID=84747}},ends={{npcID=84739}},coords={x=0.558,y=0.486,source="quest_giver",zoneID=6720},questType="standard"},
[36261] = {id=36261,name="Garrison Campaign: Missing Grunt",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=7004,mapID=590,description="With the Heart of Gorgorek residing inside the garrison walls, we need to stay vigilant. The Burning Blade are known for attacking swiftly, and without warning. I have a number of grunts patrolling the keep. Dul'zak , one of our newer recruits, should have reported back by now.",objectivesText="Find Dul'zak .",rewardGold=169800,rewardXP=1365,starts={{npcID=79740}},ends={{npcID=79740}},coords={x=0.538,y=0.542,source="quest_giver",zoneID=7004},questType="standard"},
[36262] = {id=36262,name="Ameeka, Master Tailor",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,mapID=539,description="Ameeka created this book to document and pass down our most cherished crafting techniques to our children. She must have dropped it while traveling. She will be relieved to see her book. From what I have heard from other villagers, she was last seen on the road to Elodor. Perhaps you can find her there.",objectivesText="Speak to Ameeka in Elodor. Progress: Hello, traveler! Is there something that I can help you with?",rewardGold=16980,rewardXP=175,starts={{npcID=84776}},ends={{npcID=84523}},coords={x=0.43,y=0.54,source="quest_giver",zoneID=7078},questType="standard"},
[36266] = {id=36266,name="The Clothes on Their Backs",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,mapID=539,description="Such kindness you have shown me, perhaps I can ask for one more? In our village, we salvage and reuse old cloth to patch clothes and light armor. Sadly, most of my supply was taken or destroyed in the recent attacks. The Shadowmoon cultists might think twice about stealing from us if you were to relieve them of their own resources. If you can collect some ceremonial Shadowmoon robes for me, I will demonstrate some of my favorite tailoring techniques for you.",objectivesText="Collect 10 Ceremonial Shadowmoon Robes . Progress: Were you able to get the robes?",rewardGold=169800,rewardXP=1415,starts={{npcID=84523}},ends={{npcID=84523}},coords={x=0.582,y=0.266,source="quest_giver",zoneID=6719},questType="standard"},
[36269] = {id=36269,name="Hexcloth",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,mapID=539,description="I shall now impart to you the finer points of creating hexcloth. The process is quite simple. It involves immersing carefully woven fur into the ichor drawn from Gorgrond Flytraps. Normally, you would need to harvest it yourself, but I actually managed to liberate some from the Shadowmoon during their last raid. You are welcome to use it.",objectivesText="Use Ameeka 's Flytrap Ichor to create a Swatch of Hexweave. Progress: Were you successful, friend?",rewardGold=169800,rewardXP=1415,rewardItems={111816,115357},starts={{npcID=84523}},ends={{npcID=84523}},coords={x=0.582,y=0.266,source="quest_giver",zoneID=6719},questType="standard"},
[36271] = {id=36271,name="Breaking into the Trap Game",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=7078,description="When we came through the portal, we weren't able to bring any of our animals with us. For us to produce leather and furs, we'll need to trap some of the native beasts and bring them back here. We can get a load of leather from the elekk, or furs from the talbuk, right here in Shadowmoon. Take this iron trap and use it on a wounded adult talbuk or elekk, then bring the trap on back here and we'll start a work order.",objectivesText="Use the Iron Trap to capture an Elekk or Talbuk in Shadowmoon Valley and then place a Work Order at your Barn. Progress: Have you tried your hand at trapping yet?",rewardGold=248880,rewardXP=1770,rewardCurrencies={{id=824,amount=50}},starts={{npcID=84524}},ends={{npcID=84524}},coords={x=0.348,y=0.494,source="quest_giver",zoneID=7078},questType="standard"},
[36272] = {id=36272,name="Feeding An Army",level=15,requiredLevel=15,faction="alliance",expansion=5,zoneID=7078,description="We've had a chance to work with these beasts for a while now, and that's allowed us to develop a brand-new trap for you to try out. It should be much sturdier than the last one! Mind giving 'er a run, commander? The Improved Iron Trap will let you capture some of the meatiest wildlife, like the big boars and riverbeasts out in Gorgrond . We'll be able to turn them into some tasty steaks.",objectivesText="Use the Improved Iron Trap to capture a Boar or Riverbeast in Gorgrond and then place a Work Order at your Barn. Progress: Did ya try the trap out yet?",rewardGold=339600,rewardXP=2615,rewardCurrencies={{id=824,amount=50}},starts={{npcID=84524}},ends={{npcID=84524}},coords={x=0.348,y=0.494,source="quest_giver",zoneID=7078},questType="standard"},
[36273] = {id=36273,name="Whacking Weeds",level=35,requiredLevel=35,faction="both",expansion=5,zoneID=6755,mapID=550,description="Something needs to be done about the podling menace in Spiteleaf Thicket! Alongside Hemet Nesingwary, I've hunted some of the largest and most terrifying beasts around. Never in my life have I encountered a creature as vile, depraved, nefarious or degenerate as a podling! The vicious little monsters spread themselves like weeds and if something isn't done, they'll spread across the entire continent! Make your way into Spiteleaf Thicket and slay as many podlings as you can find!",objectivesText="Slay 20 Spiteleaf podlings.",rewardGold=245700,rewardXP=4790,starts={{npcID=84632}},ends={{npcID=84632}},coords={x=0.774,y=0.474,source="quest_giver",zoneID=6755},questType="standard"},
[36274] = {id=36274,name="Bigger Trap, Better Rewards",level=35,requiredLevel=35,faction="alliance",expansion=5,zoneID=7078,description="Good news, commander! With the materials we've gathered here in Draenor, we've been able to construct a trap strong enough to immobilize even the mightiest beast! Why don't you head on out to Nagrand and give it a try? Word has it that the western plains are home to some of the most magnificent beasts this side of Crystal Lake. I'm going to warn you, though, these beasts are tough. You may want to bring some friends along.",objectivesText="Use the Deadly Iron Trap to capture an Ironhide Bull, Direfang Alpha, or Wetland Trampler. Progress: Well? How'd it go?",rewardGold=274800,rewardXP=5990,rewardCurrencies={{id=824,amount=100}},starts={{npcID=84524}},ends={{npcID=84524}},coords={x=0.348,y=0.494,source="quest_giver",zoneID=7078},questType="group"},
[36275] = {id=36275,name="The Search For Research",level=35,requiredLevel=35,faction="both",expansion=5,zoneID=6755,mapID=550,description="My research notes are missing! They must have gone missing during the podling attack on the research station. All of my work will be lost if they are not found! Come to think of it, I'm also missing my expedition supply bag, as well as my anti-fungal boots .... How can I do biological research without my equipment?! No... this will not do at all. Please, go and search the Zangar Shore for my missing belongings so that I may continue my fungal research!",objectivesText="Return the Research Journal , Expedition Supplies , and Anti-fungal Boots to Dr. Hadley Ricard . Progress: Have you retrieved my missing belongings?",rewardGold=169800,rewardXP=4790,rewardItems={116829,116830,116831,119063,119071},rewardChoices={116829,116830,116831,119063,119071},starts={{npcID=84861}},ends={{npcID=84861}},coords={x=0.866,y=0.284,source="quest_giver",zoneID=6755},questType="standard"},
[36280] = {id=36280,name="Garrison Campaign: The Ring of Blood",level=40,requiredLevel=40,faction="both",expansion=5,zoneID=6755,mapID=550,description="Hey Champ, You were out when I stopped by. I've got a sweet gig set up at the Ring of Blood in Nagrand. Lots of ogres looking for the next big fight. Big money. You in? You're the one that brought a new meaning to pain at the Ring of Trials not too long ago, right? This is the next step in your climb to fame! You've gotta get down here. I'll meet you at my stash so we can talk a bit in private before your big debut.",objectivesText="Speak to Gurgthock at Gurgthock 's Stash in Nagrand.",rewardGold=16980,rewardXP=685,starts={{npcID=234243}},ends={{npcID=84637}},coords={x=0.438,y=0.481,source="quest_giver",zoneID=7004},questType="standard"},
[36281] = {id=36281,name="Garrison Campaign: The Ring of Blood",level=40,requiredLevel=40,faction="both",expansion=5,zoneID=6755,mapID=550,description="Hey Champ, You were out when I stopped by. I've got a sweet gig set up at the Ring of Blood in Nagrand. Lots of ogres looking for the next big fight. Big money. You in? If you think the Stonemaul arena was a thrill, this is way, way bigger than that. It's going to be HUGE, I'm calling it now. I'll meet you at my stash so we can talk a bit in private before your big debut.",objectivesText="Speak to Gurgthock at Gurgthock 's Stash in Nagrand.",rewardGold=16980,rewardXP=685,starts={{npcID=234243}},ends={{npcID=84637}},coords={x=0.438,y=0.481,source="quest_giver",zoneID=7004},questType="standard"},
[36282] = {id=36282,name="Garrison Campaign: The Ring of Blood",level=40,requiredLevel=40,faction="both",expansion=5,zoneID=6755,mapID=550,description="Hey Champ, You were out when I stopped by. You're the talk of the arena, friend! I mean, the Ring of Trials? Stonemaul? You're killing it out there! I've got a sweet gig set up at the Ring of Blood in Nagrand. Lots of ogres looking for the next big fight. Big money. You in? I'll meet you at my stash so we can talk a bit in private before your big debut.",objectivesText="Speak to Gurgthock at Gurgthock 's Stash in Nagrand.",rewardGold=16980,rewardXP=685,starts={{npcID=234243}},ends={{npcID=84637}},coords={x=0.438,y=0.481,source="quest_giver",zoneID=7004},questType="standard"},
[36284] = {id=36284,name="A Fascinating Fungus",level=35,requiredLevel=35,faction="both",expansion=5,zoneID=6755,mapID=550,description="The Zangar Shore is home to many peculiar strains of fungi, some of which are similar to those of our native Azeroth. However, one strain in particular is most fascinating! I call it \"Zangarium Draenormycota,\" due to its prevelance in Draenor's fungal ecosystem. This unique strain of fungus is highly adaptable and can be found on many of the living organisms throughout Zangar Shore. Why does it exist? What properties does it hold? To answer these questions, I will need additional spore samples.",objectivesText="Collect 12 Fungal Spores . Progress: Have you collected the spore samples for my research?",rewardGold=283700,rewardXP=4790,starts={{npcID=84861}},ends={{npcID=84861}},coords={x=0.866,y=0.284,source="quest_giver",zoneID=6755},questType="standard"},
[36285] = {id=36285,name="Dirgemire",level=35,requiredLevel=35,faction="both",expansion=5,zoneID=6755,mapID=550,description="In order to fully understand the nature and properties of the Zangarium Draenormycota, I need to examine the strain within a complex fungal structure. The fungal brain of a spore giant would do nicely. Not just any spore giant will serve though, it needs to be big... mean... primordial... the perfect specimen! In a cavern deep below the surface is an ancient spore giant the locals fearfully refer to as Dirgemire. Slay the monster, but be sure to carefully preserve the fungal brain for our research!",objectivesText="Retrieve the Fungal Brain from Dirgemire. Progress: Without a fungal brain to examine, the mysteries of the Zangar ecosystem will remain unsolved!",rewardGold=169800,rewardXP=4790,starts={{npcID=84861}},ends={{npcID=84861}},coords={x=0.866,y=0.284,source="quest_giver",zoneID=6755},questType="standard"},
[36286] = {id=36286,name="Transponder 047-B",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,mapID=539,description="The back of the transponder is etched in scribbled writing. Goggles near Eledor. It is of the utmost importance!>",objectivesText="Return the transponder to Goggles . Provided item:",rewardGold=7150,rewardXP=1415,ends={{npcID=84825}},coords={mapID=539,source="quest_giver",x=0.608,y=0.326},questType="standard"},
[36287] = {id=36287,name="Snatch 'n' Grab",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,mapID=539,description="We were able to map all of the data from the transponder you recovered! Now our location analyzer is complete! We're just missing a few final pieces, then the real testing begins. One of my pilots mentioned seeing a beached Iron Horde ship over by the shore. If you can salvage some parts we may just be able to get this thing up and running!",objectivesText="Search the beach for salvageable parts. Progress: Don't worry. We're just borrowing these from the Iron Horde!",rewardGold=169800,rewardXP=1415,rewardItems={109258,111921},starts={{npcID=84825}},ends={{npcID=84825}},coords={x=0.608,y=0.326,source="quest_giver",zoneID=6719},questType="standard"},
[36289] = {id=36289,name="Out of the Shadows",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=7078,mapID=550,description="Congratulations again, Blood Champion. You be fightin' like nobody I ever seen. While you were in da ring, one ayour bruddas came by and asked for you ta return ta your base. He called himself Bodrick Grey .",objectivesText="Speak to Bodrick Grey at your Garrison.",rewardGold=16980,rewardXP=685,starts={{npcID=84784}},ends={{npcID=81492}},coords={x=0.568,y=0.13,source="quest_giver",zoneID=6755},questType="standard"},
[36290] = {id=36290,name="Out of the Shadows",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=7004,mapID=550,description="Congratulations, Blood Champion. You be fightin' like nobody I ever seen. While you were in da ring, one a your bruddas came by and asked for you ta return ta your base. He called himself a shadow hunter.",objectivesText="Speak to Rokhan in your Garrison.",rewardGold=16980,rewardXP=685,starts={{npcID=84784}},ends={{npcID=78487}},coords={x=0.568,y=0.13,source="quest_giver",zoneID=6755},questType="standard"},
[36292] = {id=36292,name="Investigating the Invasion",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=4,mapID=17,description="I'm going to lead a small squad behind enemy lines. Meet me by Dreadmaul, . From there we can decide our next course of action.",objectivesText="Meet Thrall behind enemy lines.",rewardGold=14390,rewardXP=175,starts={{npcID=82851}},ends={{npcID=84928}},coords={x=0.718,y=0.478,source="quest_giver",zoneID=4},questType="standard"},
[36294] = {id=36294,name="Phylarch the Evergreen A",level=10,requiredLevel=10,faction="none",expansion=5,questType="standard"},
[36295] = {id=36295,name="Phylarch the Evergreen B",level=10,requiredLevel=10,faction="none",expansion=5,questType="standard"},
[36296] = {id=36296,name="Phylarch the Evergreen",level=10,requiredLevel=10,faction="none",expansion=5,zoneID=6755,mapID=550,rewardGold=169800,rewardXP=1415,ends={{npcID=84892}},questType="standard"},
[36301] = {id=36301,name="Trega's Tailoring Kit",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,mapID=525,description="The bag is filled with patterns and unfamiliar tailoring tools. You find the name \" Trega \" embroidered on the inside of the bag. You seem to recall seeing her in Wor'gol. With any luck, she's still there.",objectivesText="Find Trega in Wor'gol. Progress: That's my sewing kit! I never thought I would see this again.",rewardGold=16980,rewardXP=175,ends={{npcID=84689}},coords={mapID=525,source="quest_giver",x=0.204,y=0.605},questType="standard"},
[36307] = {id=36307,name="Investigating the Invasion",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=4,mapID=17,description="I'm going to lead a small squad behind enemy lines. Meet me by Dreadmaul, . From there we can decide our next course of action.",objectivesText="Meet Maraad behind enemy lines.",rewardGold=14390,rewardXP=175,starts={{npcID=82270}},ends={{npcID=84929}},coords={x=0.666,y=0.282,source="quest_giver",zoneID=4},questType="standard"},
[36308] = {id=36308,name="Enchanted Highmaul Bracer",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=7078,mapID=539,description="A powerful enchantment emanates from these ancient Highmaul bracers. Maybe Eileese Shadowsong , your garrison enchanting quartermaster, can tell you more about the bracer.",objectivesText="Take the bracer to Eileese Shadowsong in your Garrison. Provided item:",rewardGold=9470,rewardXP=175,ends={{npcID=83491}},questType="standard"},
[36309] = {id=36309,name="The Strength of Iron",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,mapID=539,description="A stitched patch along the side of the satchel clearly identifies its owner. You remember hearing stories of a great blacksmith just north of Embaari.",objectivesText="Deliver the satchel to Haephest . Provided item:",rewardGold=58650,rewardXP=1415,ends={{npcID=80827}},coords={mapID=539,source="quest_giver",x=0.452,y=0.388},questType="standard"},
[36310] = {id=36310,name="The Arakkoan Enchanter",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,mapID=539,description="The arakkoa said it was going to investigate an anomaly along the Forgotten Shore that might be related to another armor piece.",objectivesText="Find Delath on the Forgotten Shore to the south. Progress: Greetings Enchanter. I can see you are acquainted with the art. Good, good. Perhaps you and I can help each other.",rewardGold=26210,rewardXP=175,rewardItems={115350},starts={{npcID=83491}},ends={{npcID=84966}},coords={x=0.454,y=0.534,source="quest_giver",zoneID=7078},questType="standard"},
[36311] = {id=36311,name="Father and Son",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,mapID=539,description="Please find my boy! Before the looters came we were on the hill just northeast of here. There weren't many of them, but I'm a blacksmith, not a fighter! Have I let my only son down?",objectivesText="Find Haephest 's son.",rewardGold=169800,rewardXP=1415,rewardItems={111813,115356},starts={{npcID=80827}},ends={{npcID=80827}},coords={x=0.452,y=0.388,source="quest_giver",zoneID=6719},questType="standard"},
[36313] = {id=36313,name="Failed Apprentice",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,mapID=539,description="Oru'kai was the first ogre mage to master the art of enchanting on Draenor. Upon his death, his items were scattered across Draenor. I have tracked his staff to the shore you see before us. As you can see, the staff's enchantment is making it difficult to retrieve. A would-be apprentice, Deema , took one of Oru'kai's rings in to break the enchantment, but she failed and became trapped as well. Find and free Deema , take the ring, complete her task, and I will consider a reward.",objectivesText="Find and release Deema from her time prison.",rewardGold=127350,rewardXP=1060,starts={{npcID=84966}},ends={{npcID=84963}},coords={x=0.374,y=0.726,source="quest_giver",zoneID=6719},questType="standard"},
[36314] = {id=36314,name="The Intricate Pendant",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=7004,mapID=525,description="The crimson gem used in this pendant is unlike any you've seen before, and the filigree wrapped around it is masterfully crafted. There's likely to be much you can learn from the person who made this. Perhaps someone at your garrison will recognize the work.",objectivesText="Ask around your garrison to see if anyone recognizes the pendant. Progress: Why hello <name>, what do we have here?",rewardGold=16980,rewardXP=175,ends={{npcID=84967}},questType="standard"},
[36315] = {id=36315,name="Oru'kai's Staff",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,mapID=539,description="If I had known being an enchanter was this dangerous, I would have stayed in Shattrath. Here, take this ring. The arakkoa told me to use the ring on the staff to nullify the enchantment. Bring the scepter back to him and maybe he will teach you what he promised to teach me.",objectivesText="Retrieve Oru'kai's staff and return it to Delath. Progress: The staff! Give it to me!",rewardGold=169800,rewardXP=1415,rewardItems={111817,111922},starts={{npcID=84963}},ends={{npcID=84966}},coords={x=0.356,y=0.722,source="quest_giver",zoneID=6719},questType="standard"},
[36316] = {id=36316,name="Victory is Within Reach",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6988,mapID=542,description="We have dealt a crippling blow to the Adherents, but our fight is not yet finished. Gather your allies and prepare for the final siege on Skyreach! \"Shadows gather when the raven swallows the day. Burning sky is extinguished as black wings fold gently about the heavens. Rest, my children, rest. For even the sun must sleep.\" This was Rukhmar's lullaby, sung by her to the first arakkoa. My, how we've lost our way.",objectivesText="Slay Ranjit , Araknath , Rukhran and High Sage Viryx in the Skyreach dungeon. Progress: Let us finish what we have started.",rewardGold=679200,rewardXP=8230,starts={{npcID=81770}},ends={{npcID=81770}},coords={x=0.464,y=0.466,source="quest_giver",zoneID=6722},questType="dungeon"},
[36338] = {id=36338,name="Assault on Shattrath Harbor",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=6662,objectivesText="Shadow Council Assaulted Defeat Minus Enemies Defeat Normal Enemies Defeat Lieutenant Enemies Defeat Miniboss Enemies Caches Siege Cannons Soul Crystals Fel Fires Arkonite Crystals Sha'tari Belongings Orc Bodies Captured Guards",coords={mapID=535,x=0.44,y=0.23},questType="standard",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Shadow Council Assaulted"},{orderIndex=2,type=0,amount=100,objectID=85000,text="Defeat Normal Enemies"},{orderIndex=3,type=0,amount=34,objectID=85195,text="Defeat Lieutenant Enemies"},{orderIndex=1,type=0,amount=500,objectID=85197,text="Defeat Minus Enemies"},{orderIndex=12,type=0,amount=34,objectID=85103,text="Captured Guards"},{orderIndex=5,type=2,amount=20,objectID=234433,text="Caches"},{orderIndex=4,type=0,amount=4,objectID=85200,text="Defeat Miniboss Enemies"},{orderIndex=6,type=0,amount=45,objectID=84754,text="Siege Cannons"},{orderIndex=7,type=0,amount=50,objectID=83856,text="Soul Crystals"},{orderIndex=8,type=0,amount=50,objectID=84279,text="Fel Fires"},{orderIndex=9,type=0,amount=10,objectID=85370,text="Arkonite Crystals"},{orderIndex=11,type=0,amount=100,objectID=85393,text="Orc Bodies"},{orderIndex=10,type=0,amount=34,objectID=84997,text="Sha'tari Belongings"}},worldTaskTitle="Assault on Shattrath Harbor"},
[36340] = {id=36340,name="Spires - Treasure 058 - Ogron Plunder",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6722,mapID=542,ends={{npcID=234432}},questType="standard"},
[36341] = {id=36341,name="Primal Fury",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=6662,mapID=543,description="It looks like this is it, commander. We must stop the Iron Horde at all costs. I have sent stormcrows to your garrison, and called for Bodrick Grey to deploy your troops to the Gates of Tanaan at once. By the time you get to northern Talador, he should be waiting for you... with an entire army. There is no time to delay.",objectivesText="Meet Bodrick Grey near the Gates of Tanaan in Talador, then defeat Gorgorek and Warlord Azuka Bladefury .",rewardXP=1365,rewardItems={120311,120312},starts={{npcID=84185}},ends={{npcID=84268}},coords={x=0.41,y=0.43,source="quest_giver",zoneID=6721},questType="standard"},
[36342] = {id=36342,name="Primal Fury",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=6662,mapID=543,description="It looks like this is it, commander. We must stop the Iron Horde at all costs. I have sent stormcrows to your garrison, and called for Shadow Hunter Rokhan to deploy your troops to the Gates of Tanaan at once. By the time you get to northern Talador, he should be waiting for you... with an entire army. There is no time to delay.",objectivesText="Speak to Shadow Hunter Rokhan in northern Talador, then defeat Gorgorek and Warlord Azuka Bladefury .",rewardXP=1365,rewardItems={120311,120312},starts={{npcID=88530}},ends={{npcID=79740}},coords={x=0.41,y=0.43,source="quest_giver",zoneID=6721},questType="standard"},
[36344] = {id=36344,name="Feeding An Army",level=15,requiredLevel=15,faction="horde",expansion=5,zoneID=7004,description="We've had a chance to work with these beasts for a while now, and that's allowed us to develop a brand-new trap for you to try out. It should be much sturdier than the last one. The Improved Iron Trap will let you capture some of the meatiest beasts on Draenor. You will find that a single riverbeast or boar from Gorgrond can feed many warriors. Trap one and bring it back, and we will cook you a savage meal.",objectivesText="Use the Improved Iron Trap to capture a Boar or Riverbeast in Gorgrond and then place a Work Order at your Barn. Progress: Did you try the trap out yet?",rewardGold=339600,rewardXP=2615,rewardCurrencies={{id=824,amount=50}},starts={{npcID=85048}},ends={{npcID=85048}},coords={x=0.514,y=0.62,source="quest_giver",zoneID=7004},questType="standard"},
[36345] = {id=36345,name="Breaking into the Trap Game",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=7004,description="When we came through the portal, we weren't able to bring any of our animals with us. For us to produce leather and furs, we'll need to trap some of the native beasts and bring them back here. Although the plains are frozen, there are many clefthooves and wolves in Frostfire. We can gather leather from the clefthooves, or furs from the wolves. Take this iron trap and use it on a wounded adult beast. Bring the trapped creature back to us, and we will begin our work.",objectivesText="Use the Iron Trap to capture a Clefthoof or Wolf in Frostfire Ridge and then place a Work Order at your Barn. Progress: Have you tried your hand at trapping yet?",rewardGold=339600,rewardXP=1770,rewardCurrencies={{id=824,amount=50}},starts={{npcID=85048}},ends={{npcID=85048}},coords={x=0.514,y=0.62,source="quest_giver",zoneID=7004},questType="standard"},
[36346] = {id=36346,name="Bigger Trap, Better Rewards",level=35,requiredLevel=35,faction="horde",expansion=5,zoneID=7004,description="Ah, commander, it is good to see you again. With the materials we have gathered here in Draenor, we have been able to construct a trap strong enough to immobilize even the mightiest beast. These enormous creatures can be found on the western side of Nagrand , among the most fertile plains. A word of warning: these beasts are great and powerful. You may want to bring some friends along.",objectivesText="Use the Deadly Iron Trap to capture a Ironhide Bull, Direfang Alpha, or Wetland Trampler. Progress: Did you manage to break one of the great beasts?",rewardGold=339600,rewardXP=5990,rewardCurrencies={{id=824,amount=100}},starts={{npcID=85048}},ends={{npcID=85048}},coords={x=0.514,y=0.62,source="quest_giver",zoneID=7004},questType="group"},
[36347] = {id=36347,name="Assault on Socrethar's Rise",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=6719,objectivesText="Socrethar's Rise Disrupted Defeat Minus Enemies Defeat Tier 1 Enemies Defeat Tier 2 Enemies Defeat Tier 2+ Enemies Defeat Tier 3 Enemies Defeat Tier 3+ Enemies Defeat Minibosses",coords={mapID=539,x=0.48,y=0.73},questType="standard",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Socrethar's Rise Disrupted"},{orderIndex=1,type=0,amount=500,objectID=85079,text="Defeat Minus Enemies"},{orderIndex=2,type=0,amount=100,objectID=85319,text="Defeat Tier 1 Enemies"},{orderIndex=3,type=0,amount=77,objectID=81542,text="Defeat Tier 2 Enemies"},{orderIndex=4,type=0,amount=34,objectID=84945,text="Defeat Tier 2+ Enemies"},{orderIndex=5,type=0,amount=20,objectID=84908,text="Defeat Tier 3 Enemies"},{orderIndex=6,type=0,amount=16,objectID=81543,text="Defeat Tier 3+ Enemies"},{orderIndex=7,type=0,amount=4,objectID=85321,text="Defeat Minibosses"}},worldTaskTitle="Assault on Socrethar's Rise"},
[36348] = {id=36348,name="Assault on Socrethar's Rise",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=6719,objectivesText="Socrethar's Rise Disrupted Defeat Minus Enemies Defeat Tier 1 Enemies Defeat Tier 2 Enemies Defeat Tier 2+ Enemies Defeat Tier 3 Enemies Defeat Tier 3+ Enemies Defeat Minibosses",coords={mapID=539,x=0.48,y=0.73},questType="standard",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Socrethar's Rise Disrupted"},{orderIndex=1,type=0,amount=500,objectID=85079,text="Defeat Minus Enemies"},{orderIndex=2,type=0,amount=100,objectID=85319,text="Defeat Tier 1 Enemies"},{orderIndex=3,type=0,amount=77,objectID=81542,text="Defeat Tier 2 Enemies"},{orderIndex=4,type=0,amount=34,objectID=84945,text="Defeat Tier 2+ Enemies"},{orderIndex=5,type=0,amount=20,objectID=84908,text="Defeat Tier 3 Enemies"},{orderIndex=6,type=0,amount=16,objectID=81543,text="Defeat Tier 3+ Enemies"},{orderIndex=7,type=0,amount=4,objectID=85321,text="Defeat Minibosses"}},worldTaskTitle="Assault on Socrethar's Rise"},
[36352] = {id=36352,name="Locating the Lapidarist",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,mapID=525,description="Are you sure I can't take this off your hands? I'll give you a fair price! Alright, alright... if you insist on finding the owner, you might want to try visiting Wor'gol. Rumor has it there is a master craftsman there who's skilled in manipulating precious metals and stones. Might be your guy.",objectivesText="Search for the owner of the pendant in Wor'gol.",rewardGold=42450,rewardXP=355,starts={{npcID=84967}},ends={{npcID=85106}},coords={x=0.706,y=0.504,source="quest_giver",zoneID=7004},questType="standard"},
