[36366] = {id=36366,name="Spires - Treasure 046 - Goblin Rum",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6722,mapID=542,ends={{npcID=234473}},questType="standard"},
[36368] = {id=36368,name="Lost Lumberjack",level=15,requiredLevel=15,faction="alliance",expansion=5,zoneID=6721,mapID=543,description="All o' them mole machines got mighty unreliable here in Gorgrond . I hear tell that one of 'em might've crashed here in Tangleheart. See if you can find Frenna . She would've been on the one we tracked to this location. I'll go lookin' for the mole machine to see if it can be repaired.",objectivesText="Find Frenna within Tangleheart.",rewardGold=254700,rewardXP=2090,starts={{npcID=82575},{npcID=85119}},ends={{npcID=82569}},coords={x=0.558,y=0.714,source="quest_giver",zoneID=6721},questType="standard"},
[36375] = {id=36375,name="Spires - Treasure 026 - Sethekk Idol",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6722,mapID=542,ends={{npcID=85190}},questType="standard"},
[36376] = {id=36376,name="Goren Invasion!",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=7004,description="Quakes have been shaking the garrison, and our scouts haven't reported in hours.",objectivesText="Repel the goren invasion. (Speak with Sergeant Crowler again to begin) Progress: We must hold the line!",rewardGold=169800,rewardXP=8200,starts={{npcID=78564}},ends={{npcID=78564}},coords={x=0.382,y=0.32,source="quest_giver",zoneID=7078},questType="standard"},
[36377] = {id=36377,name="Spires - Treasure 049 - Rukhmar's Image",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6722,mapID=542,ends={{npcID=85206}},questType="standard"},
[36378] = {id=36378,name="No Pressure, No Diamonds",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,mapID=525,description="You wish to understand the secrets of our gems, ? In exchange for returning my pendant, I am willing to help. I must warn you, however, that the materials will not be easy to obtain. To the north, you will find magma pools that give birth to living lava creatures. Contained within these, you may find magnificent diamonds. Please return to me with a few of these diamonds...",objectivesText="Acquire Lava Diamonds from the Lava Slimes that reside in Frostfire Ridge. Progress: Have you obtained the materials I asked for?",rewardGold=169800,rewardXP=1415,starts={{npcID=85106}},ends={{npcID=85106}},coords={x=0.2,y=0.564,source="quest_giver",zoneID=6720},questType="standard"},
[36379] = {id=36379,name="Peeking into the Portal",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=4,mapID=17,description="I sent Scout Pazerp to get a better look at the portal. She should have reported back by now; what could be taking her so long? She is one of my best scouts, I hope she is alright.",objectivesText="Find Scout Pazerp and use her telescope .",rewardGold=43200,rewardXP=1415,starts={{npcID=85213}},ends={{npcID=85213}},coords={x=0.668,y=0.28,source="quest_giver",zoneID=4},questType="standard"},
[36380] = {id=36380,name="Diamonds Are Forever",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,mapID=525,description="Please watch closely . I shall craft this jewel into a fine pendant for you. Hopefully you will learn a bit of true jewelcrafting in the process.",objectivesText="Wait for Orolak to finish crafting the pendant. Progress: It is finished, and even more beautiful than the last!",rewardGold=42450,rewardXP=355,rewardItems={111814,115359,115503},starts={{npcID=85106}},ends={{npcID=85106}},coords={x=0.2,y=0.564,source="quest_giver",zoneID=6720},questType="standard"},
[36382] = {id=36382,name="Peeking into the Portal",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=4,mapID=17,description="I sent Scout Pazaztick to be gettin' a better look at da portal. He shoulda reported back by dis time; what be taking him so long? Dis is what happens when you hire da goblins as help.",objectivesText="Find Scout Pazaztick and use her telescope .",rewardGold=169800,rewardXP=1415,starts={{npcID=85247}},ends={{npcID=85247}},coords={x=0.718,y=0.488,source="quest_giver",zoneID=4},questType="standard"},
[36383] = {id=36383,name="Assault on the Pit",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=6721,description="The Iron Horde are stockpiling their weapons and ammunition outside of the Foundry. Their campaign throughout Draenor has left their caches vulnerable. Get in there and cause as much chaos as you can, and while you're at it use some of that ammunition against them if they're just going to leave it lying around!",objectivesText="Destroy Iron Horde weapons cache and take out as many of them as you can.",coords={mapID=543,x=0.484,y=0.258},questType="standard",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Blackrock Foundry Assaulted"},{orderIndex=1,type=0,amount=100,objectID=85228,text="Kill Iron Horde"},{orderIndex=2,type=0,amount=20,objectID=85229,text="Kill Iron Horde"},{orderIndex=3,type=0,amount=5,objectID=85230,text="Kill Iron Horde"},{orderIndex=4,type=0,amount=200,objectID=86298,text="Kill Iron Horde"},{orderIndex=5,type=2,amount=100,objectID=236277,text="Destroy Training Manuals"},{orderIndex=6,type=2,amount=50,objectID=236421,text="Free Rangari Prisoners"}},worldTaskTitle="Assault on the Pit"},
[36384] = {id=36384,name="Field Trial",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6722,mapID=542,description="Look, I didn't tell Kimzee about this because I don't want to hurt her feelings, I chose not to leave Pinchwhistle Point. See, I've been working on a serum that I think should be able to cure the infected, but when I tried to test it I got surrounded and I injured my leg during the escape. I know I'm on the right track but I need to test it. Do me a favor and take this vial and go try it out on one of the infected outside.",objectivesText="Venture into Pinchwhistle Point and use the Vial of Untested Serum on an Infected Bruiser or Infected Lumberjack. Return to Krixel Pinchwhistle to report the results. Progress: Have you completed the field test, <name>?",rewardGold=189540,rewardXP=3085,rewardItems={115475},starts={{npcID=81443}},ends={{npcID=81443}},coords={x=0.584,y=0.922,source="quest_giver",zoneID=6722},questType="standard"},
[36385] = {id=36385,name="Legacy of the Ancients",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=6755,mapID=550,description="Opening the ancient tome you see that it's not actually a tome at all, but a container. Inside are four empty slots. Upon closer inspection each slot has next to it a carving of what appears to be a unique Draenor ancient, some glyphs and a receptacle used to hold a piece of the pictured ancient. There also appear to be directions to where these ancients may be found: medium timber -- Shadowmoon, Gorgrond, the Spires of Arak and Nagrand. These are assassination instructions. From trees to kill trees.",objectivesText="Collect the Heart of Kuruk , the Trunk of Autuk , the Twig of Loruk , and the Roots of Hanuk . Progress: What have you got there, commander?",rewardGold=679200,rewardXP=2830,rewardItems={115506},ends={{npcID=84247},{npcID=84248}},questType="standard"},
[36395] = {id=36395,name="Spires - Treasure 003 - Elixir of Shadow Sight 01",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6722,mapID=542,starts={{npcID=9728}},ends={{npcID=234703}},questType="standard"},
