[36403] = {id=36403,name="Spires - Treasure 010 - Offering to the Raven Mother 01",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6722,mapID=542,starts={{npcID=9728}},ends={{npcID=234744}},questType="standard"},
[36404] = {id=36404,name="Clearing the Garden",level=30,requiredLevel=30,faction="alliance",expansion=5,zoneID=7078,description="This clearing is the perfect spot to grow herbs for our Garrison, there is just one little problem. All these dang raccoons! I need you to clear them out and we can get this garden growing.",objectivesText="Kill 8 Lunarfall Raccoons . Progress: Did you get 'em?",rewardGold=169800,rewardXP=4115,rewardItems={248334},starts={{npcID=85344}},ends={{npcID=85344}},coords={x=0.586,y=0.53,source="quest_giver",zoneID=7078},questType="standard"},
[36405] = {id=36405,name="Spires - Treasure 051 - Offering to the Raven Mother 02",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6722,mapID=542,starts={{npcID=9728}},ends={{npcID=234746}},questType="standard"},
[36406] = {id=36406,name="Spires - Treasure 052 - Offering to the Raven Mother 03",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6722,mapID=542,starts={{npcID=9728}},ends={{npcID=234748}},questType="standard"},
[36407] = {id=36407,name="Spires - Treasure 053 - Offering to the Raven Mother 04",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6722,mapID=542,starts={{npcID=9728}},ends={{npcID=235073}},questType="standard"},
[36408] = {id=36408,name="A Power Lost",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,mapID=539,description="The power within the fragment appears to be drained. You recall hearing travelers speak of a local in Embaari Village who specializes in imbuing gems with magic.",objectivesText="Find someone in Embaari Village well-versed in gemology and magic. Provided item:",rewardGold=58650,rewardXP=1415,ends={{npcID=84830}},coords={mapID=539,source="quest_giver",x=0.47,y=0.385},questType="standard"},
[36409] = {id=36409,name="Restoration",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,mapID=539,description="As mentioned, our larger defense crystals have been drained of power, creating gaps in our defenses. The crystal you brought me is only a reminder of the severity of this situation. It's Shadowmoon magic to blame, I'm sure of it. One of our rangari scouts spotted an orc fleeing north, past Palemoon Village, and into the valley beyond. Go, find this orc, and see if you can't retrieve whatever vessel he's storing the power inside of. If we get it back, I'm sure I can restore the crystals.",objectivesText="Retrieve the sample for Artificer Baleera . Progress: The crystal's power pulses as it is carried.",rewardGold=169800,rewardXP=1415,rewardItems={111814,115359},starts={{npcID=84830}},ends={{npcID=84830}},coords={x=0.47,y=0.386,source="quest_giver",zoneID=6719},questType="standard"},
[36410] = {id=36410,name="Spires - Treasure 054 - Offering to the Raven Mother 05",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6722,mapID=542,starts={{npcID=9728}},ends={{npcID=235090}},questType="standard"},
[36411] = {id=36411,name="Spires - Treasure 014 - A Lost Ring",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6722,mapID=542,ends={{npcID=235091}},questType="standard"},
[36412] = {id=36412,name="Shadowmoon Invasion!",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=7004,description="Scouts report that the Shadowmoon clan is buzzing like a kicked hornets' nest. Time again to earn our pay, Commander?",objectivesText="Repel the Shadowmoon clan invasion of your garrison. (Speak with Sergeant Crowler again to begin) Progress: We must hold the line!",rewardGold=169800,rewardXP=8200,starts={{npcID=78564}},ends={{npcID=78564}},coords={x=0.382,y=0.32,source="quest_giver",zoneID=7078},questType="standard"},
[36414] = {id=36414,name="Shadowmoon Invasion!",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=7078,description="Scouts say the Shadowmoon clan looms close, ready with their necromancy. If I die and rise again, Commander, finish me quickly. I don't want to be a ghoul.",objectivesText="Repel the Shadowmoon clan invasion of your garrison. (Speak with Sergeant Grimjaw again to begin) Progress: We must hold the line!",rewardGold=169800,rewardXP=8200,starts={{npcID=79774}},ends={{npcID=79774}},coords={x=0.44,y=0.476,source="quest_giver",zoneID=7004},questType="standard"},
[36416] = {id=36416,name="Spires - Treasure 049 - Misplaced Scroll",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6722,mapID=542,starts={{npcID=9728}},ends={{npcID=235095}},questType="standard"},
[36417] = {id=36417,name="From Their Cold Dead Hands",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,mapID=525,description="Those ogres took all of my hexweave! I kept it hidden at the bottom of my bag. How could they possibly know of its importance? If they discover even a portion of hexweave's properties, it means trouble for us all. , this is a Frostwolf problem. It requires a Frostwolf solution. Will you help me?",objectivesText="Collect 10 Damaged Hexweave from Bladespire Ogres. Progress: Well, is it done?",rewardGold=58650,rewardXP=1415,starts={{npcID=84689}},ends={{npcID=84689}},questType="standard"},
[36418] = {id=36418,name="Spires - Treasure 013 - Dark Grimoire",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6722,mapID=542,ends={{npcID=235097}},questType="standard"},
[36419] = {id=36419,name="Dyed in the Fur",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,mapID=525,description="I can't believe they tried to physically rip the magic out of the material! It seems we were never in danger of my secrets falling into the wrong hands after all. Better safe than dead... In return for your help, I will share with you my methods of fusing magic to cloth. Flytrap Ichor is very rare in this region, but I do have a bit in reserve. Take this woven fur and dip it in the ichor here. You will see for yourself what all of the fuss is about.",objectivesText="Use Trega 's Flytrap Ichor to create a Swatch of Hexweave. Progress: Has the cloth been enchanted?",rewardGold=169800,rewardXP=1415,rewardItems={111816,115357},starts={{npcID=84689}},ends={{npcID=84689}},coords={x=0.204,y=0.606,source="quest_giver",zoneID=6720},questType="standard"},
[36420] = {id=36420,name="Spires - Treasure 011 - Garrison Supplies",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6722,mapID=542,ends={{npcID=235103}},questType="standard"},
[36421] = {id=36421,name="Spires - Treasure 024 - Sun-Touched Cache",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6722,mapID=542,ends={{npcID=235104}},questType="standard"},
[36422] = {id=36422,name="Spires - Treasure 029 - Sun-Touched Cache",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6722,mapID=542,starts={{npcID=9728}},ends={{npcID=235105}},questType="standard"},
[36423] = {id=36423,name="Pets Versus Pests",level=35,requiredLevel=35,faction="alliance",expansion=5,zoneID=7078,description="I've been trying to get this place ready for your pets, but we've uncovered some rude pests while building the garrison. I tried to take care of them myself, but they are too tough for my meager team. There's an angry carrot in the garden, an enormous rat eating our food rations, and an ornery water creature harassing the fishermen. If you can take care of them, I'll be free to finish up my work on your menagerie.",objectivesText="Defeat the three pests in your garrison. Progress: Any luck?",rewardGold=169800,rewardXP=4790,starts={{npcID=85418}},ends={{npcID=85418}},coords={x=0.288,y=0.392,source="quest_giver",zoneID=7078},questType="standard"},
[36425] = {id=36425,name="Egg Punt",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6722,mapID=542,description="A swift kick should take care of these.>",objectivesText="Kick 10 Ravager Eggs in Camp Thornscar.",rewardGold=169800,rewardXP=4115,starts={{npcID=85425}},ends={{npcID=85425}},coords={x=0.47,y=0.316,source="quest_giver",zoneID=6722},questType="standard"},
[36426] = {id=36426,name="Dueling Orbs",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6662,mapID=535,questType="standard"},
[36427] = {id=36427,name="The Rise and Fall of Barov Industries: Alexi Barov",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,mapID=525,rewardGold=679200,rewardXP=2830,starts={{npcID=85379}},ends={{npcID=85379}},questType="standard"},
[36428] = {id=36428,name="Curing With Force",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6722,mapID=542,description="The infection is getting stronger so I made some adjustments and I'm pretty sure I have the right formula now. It should now work but it needs to have less competition with the infected blood for it to have any effect. This means you will need to weaken them before you apply the serum for it to function properly. The infection is getting more advanced and will soon be untreatable so we have this one shot to save as many as we can.",objectivesText="Cure 6 Infected Goblins . Progress: Any progress to report with that cure?",rewardGold=169800,rewardXP=4115,rewardItems={115533},starts={{npcID=81443}},ends={{npcID=81443}},coords={x=0.584,y=0.922,source="quest_giver",zoneID=6722},questType="standard"},
[36429] = {id=36429,name="The Rise and Fall of Barov Industries: Weldon Barov",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6720,mapID=525,rewardGold=679200,rewardXP=2830,starts={{npcID=85378}},ends={{npcID=85378}},questType="standard"},
[36430] = {id=36430,name="Tracking: Mill Treasure 18",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6721,mapID=543,questType="standard"},
[36431] = {id=36431,name="Vignette: Soul-twister Torek",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6719,mapID=539,questType="standard"},
[36432] = {id=36432,name="Seeking the Scout",level=15,requiredLevel=15,faction="alliance",expansion=5,zoneID=6721,mapID=543,description="We are still trying to locate all of our scouts out in the field. One of these, Altauur , enjoys handling the more dangerous missions. He has not checked in and I feel we should check to make sure he has not taken on more than he can handle.",objectivesText="Find Altauur at Dionor's Demise in Gorgrond .",rewardGold=187785,rewardXP=1045,starts={{npcID=75146}},ends={{npcID=85426}},coords={x=0.632,y=0.522,source="quest_giver",zoneID=6721},questType="standard"},
[36433] = {id=36433,name="Spires - Treasure 008 - Smuggled Apexis Artifacts",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6722,mapID=542,starts={{npcID=9728}},ends={{npcID=235135}},questType="standard"},
[36434] = {id=36434,name="Penny From Heaven",level=15,requiredLevel=15,faction="horde",expansion=5,zoneID=6721,mapID=543,description="Durotan looks at you curiously.> Those from your world are not much for subtlety, are they? Go on ahead and greet our new companion. We will join you as soon as we can make ready.",objectivesText="Speak to Penny Clobberbottom at Beastwatch.",rewardGold=11888,rewardXP=260,starts={{npcID=74594}},ends={{npcID=85147}},coords={x=0.372,y=0.77,source="quest_giver",zoneID=6721},questType="standard"},
[36435] = {id=36435,name="Unintelligible Intelligence",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,mapID=525,description="The notes are unreadable, but based on previous experience, the text appears to be very similar to standard Orcish. It is possible that the notes could contain strategic information. Perhaps it would be of great value to the Frostwolf Orcs. Someone in Wor'gol might be able to help interpret the text.",objectivesText="Look around Wor'gol for someone who can help translate the notes. Progress: <Raleigh looks up from the scrolls.> Commander <name>, what brings you to Wor'gol?!",rewardGold=16980,rewardXP=175,ends={{npcID=85439}},coords={mapID=525,source="quest_giver",x=0.21,y=0.56},questType="standard"},
[36436] = {id=36436,name="Plant Pruning",level=15,requiredLevel=15,faction="alliance",expansion=5,zoneID=6721,mapID=543,description="There may be more to this aberrant growth than it seems, but we will need to clear the way a bit before we can get to the bottom of this, yes? I suggest clearing out some of the angrier defenders to be on the safe side.",objectivesText="Kill 12 defenders at Dionor's Demise. Progress: How goes the pruning <class>?",rewardGold=41625,rewardXP=2090,rewardItems={118034,118035,118036,118037},rewardChoices={118035,118037,118036,118034},starts={{npcID=85426}},ends={{npcID=85432}},coords={x=0.494,y=0.496,source="quest_giver",zoneID=6721},questType="standard"},
[36437] = {id=36437,name="Ambassador to the Ancient",level=15,requiredLevel=15,faction="alliance",expansion=5,zoneID=6721,mapID=543,description="It appears that a genesaur was killed here not long ago and this growth has sprung up. It is stirring up the local monsters and I fear for our outpost. There is a strange ancient that wallows in grief here and is not hostile. Perhaps you could \"harvest\" its story?",objectivesText="Talk to Birchus at Dionor's Demise in Gorgrond .",rewardGold=254700,rewardXP=2090,starts={{npcID=85426},{npcID=85432}},ends={{npcID=85432}},coords={x=0.494,y=0.496,source="quest_giver",zoneID=6721},questType="standard"},
[36438] = {id=36438,name="Beatface vs. Boulder",level=15,requiredLevel=15,faction="alliance",expansion=5,zoneID=6721,mapID=543,description="The saberon took their treasure up the rise and barricaded themselves in after Birchus attacked. It will be difficult to get in but I hear you have resources to handle this. One of their entrances is covered with a large boulder. Too large for you or I, but perhaps an ogre with a large enough hammer could break it. I think you know who I am talking about...",objectivesText="Break the boulder barrier using Beatface the gladiator.",rewardGold=254700,rewardXP=2090,starts={{npcID=85432}},ends={{npcID=85431}},coords={x=0.512,y=0.48,source="quest_giver",zoneID=6721},questType="standard"},
[36439] = {id=36439,name="Shredder vs. Saberon",level=15,requiredLevel=15,faction="alliance",expansion=5,zoneID=6721,mapID=543,description="The saberon took their treasure up the rise and barricaded themselves in after Birchus attacked. It will be difficult to get in but I hear you have resources to handle this. One of their entrances is covered with tough vegetation. I believe you have a mechanical solution to this problem in the form of a shredder. I think you know what to do...",objectivesText="Break the vine barrier using your shredder.",rewardGold=254700,rewardXP=2090,starts={{npcID=85432}},ends={{npcID=85431}},coords={x=0.512,y=0.48,source="quest_giver",zoneID=6721},questType="standard"},
[36440] = {id=36440,name="Saberon Population Reduction",level=15,requiredLevel=15,faction="alliance",expansion=5,zoneID=6721,mapID=543,description="We are closer to our goals but a host of sharp toothed saberon bar our way. If we are to get anywhere up here, some of the more aggressive ones will need to be put down I think.",objectivesText="Slay 10 saberon at Steamscar Rise.",rewardGold=254700,rewardXP=2090,rewardItems={112875,118004,118005,118012,118013,118014},rewardChoices={118005,112875,118004,118013,118014,118012},starts={{npcID=85431}},ends={{npcID=85436}},coords={x=0.52,y=0.494,source="quest_giver",zoneID=6721},questType="standard"},
[36441] = {id=36441,name="Reclaiming Property",level=15,requiredLevel=15,faction="alliance",expansion=5,zoneID=15347,mapID=543,description="You are attracted by a low green glow to the container. Inside there is a glowing bundle of herbs that was most likely stolen from the overgrowth below. It would be best to collect all of these so the saberon don't continue their dabbling in plant magic and irritating the nearby magnaron.",objectivesText="Find 8 Herb Bundles in saberon stashes at Steamscar Rise. Progress: The saberon should definitely NOT have any of the herbs you have found!",rewardGold=254700,rewardXP=2090,rewardItems={115442},starts={{npcID=234474}},ends={{npcID=85431},{npcID=85436}},coords={x=0.519,y=0.5,source="quest_giver",zoneID=6721},questType="standard"},
[36442] = {id=36442,name="Taking the Death Bloom",level=15,requiredLevel=15,faction="alliance",expansion=5,zoneID=6721,mapID=543,description="Your work has born fruit. Inside the nearby cave a powerful saberon shaman is learning to channel the genesaur magic using the Death Bloom we seek. The solution is before us: kill the shaman, take the Death Bloom, return it to Birchus . That should improve the safety of our outpost.",objectivesText="Take the Death Bloom from Smokemaster Snarl in Steamscar Rise. Progress: Do you have something for me little beast?",rewardGold=254700,rewardXP=2090,starts={{npcID=85436}},ends={{npcID=82302}},coords={x=0.528,y=0.516,source="quest_giver",zoneID=6721},questType="standard"},
[36443] = {id=36443,name="Laying Dionor to Rest",level=15,requiredLevel=15,faction="alliance",expansion=5,zoneID=6721,mapID=543,description="You have given me a tremendous gift with this bloom. I can finally send Dionor back to the Overgrowth for good and end this nightmare. All that remains is the ritual... stay and behold something you will never see again in your lifetime...",objectivesText="Watch Birchus 's ritual.",rewardGold=509400,rewardXP=2615,rewardItems={112959,112960,112961,119049,119054},rewardChoices={112959,112960,112961,119049,119054},starts={{npcID=82302}},ends={{npcID=82302}},coords={x=0.502,y=0.474,source="quest_giver",zoneID=6721},questType="standard"},
[36444] = {id=36444,name="Spires - Treasure 006 - Iron Horde Explosives",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6722,mapID=542,ends={{npcID=235141}},questType="standard"},
[36445] = {id=36445,name="Spires - Treasure 015 - Iron Horde Spear",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6722,mapID=542,ends={{npcID=235143}},questType="standard"},
[36446] = {id=36446,name="Spires - Treasure 016 - Outcast's Pouch",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6722,mapID=542,ends={{npcID=235168}},questType="standard"},
[36447] = {id=36447,name="Spires - Treasure 020 - Outcast's Basket",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6722,mapID=542,ends={{npcID=235172}},questType="standard"},
[36448] = {id=36448,name="Reduction in Force",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6755,description="I was a fool to trust him after the fiasco over the Barov family fortune! What I should have done is killed him the first chance I had. And now he thinks he's going to plumb this land for all that it's worth and cut me out?! No, dear brother, not this time! There can only be one CEO of Barov Industries and it will be me. My peasant friend, you must do me this service. Find my brother, Alexi, and serve him a notice of termination! You will likely find him out in the wilds, near small timber.",objectivesText="Collect the Head of Alexi Barov . Progress: Did you deliver the... notice of termination?",rewardGold=16980,rewardXP=2830,rewardItems={116154},starts={{npcID=85413}},ends={{npcID=85413}},coords={x=0.35,y=0.492,source="quest_giver",zoneID=7078},questType="standard"},
[36449] = {id=36449,name="Reduction in Force",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6755,description="I was a fool to trust him after the fiasco over the Barov family fortune! What I should have done is killed him the first chance I had. And now he thinks he's going to plumb this land for all that it's worth and cut me out?! No, dear brother, not this time! There can only be one CEO of Barov Industries and it will be me. My peasant friend, you must do me this service. Find my brother, Weldon, and serve him a notice of termination! You will likely find him out in the wilds, near small timber.",objectivesText="Collect the Head of Weldon Barov . Progress: Has my brother been served the notice of termination yet?",rewardGold=16980,rewardXP=2830,rewardItems={116154},starts={{npcID=85414}},ends={{npcID=85414}},coords={x=0.546,y=0.484,source="quest_giver",zoneID=7004},questType="standard"},
[36450] = {id=36450,name="Spires - Treasure 028 - Sethekk Ritual Brew",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6722,mapID=542,ends={{npcID=235282}},questType="standard"},
[36451] = {id=36451,name="Spires - Treasure 033 - Craftsman's Hammer",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6722,mapID=542,ends={{npcID=235289}},questType="standard"},
[36452] = {id=36452,name="Spawn Tracking & Spell Visuals: Do They Work?",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=22,description="Here's some text.",objectivesText="Use the What's It to see a Spell Visual play through the magic of Spawn Tracking tech.",rewardGold=154000,rewardXP=200,questType="standard"},
