[36469] = {id=36469,name="Pets Versus Pests",level=35,requiredLevel=35,faction="horde",expansion=5,zoneID=7004,description="I been tryin' ta get dis place ready for your pets, but we uncovered some rude pests while buildin' da garrison. I tried takin' care o' dem myself, but they be too tough for my little friends. Beat da angry carrot in da garden, da rat eatin' our food, and da ornery water creature harassing da fishermen. If you can do it, I be free to finish up da work on your menagerie.",objectivesText="Defeat the three pests in your garrison. Progress: How'd you fare, <name>?",rewardGold=169800,rewardXP=4790,starts={{npcID=79858}},ends={{npcID=79858}},coords={x=0.324,y=0.424,source="quest_giver",zoneID=7004},questType="standard"},
[36471] = {id=36471,name="A New Darkmoon Challenger!",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=5861,description="Look at me, now look at my horse, now look back at me, are I not the most impressive battler of pets that you have ever seen? Look now at my compatriot over there. Is he on a horse? Of course not! Is his hat made of fireworks? Not in a million years! Everything about me is more impressive, from my coat color to my last name, which I made myself. Dare you step up to the might of Christoph Willikens Dennis Ragnaros VonFeasel the First? I can see you trembling!",objectivesText="Defeat Christoph VonFeasel in a pet battle. Progress: Ready, eh? Put up your cat's tiny dukes!",rewardGold=341600,rewardXP=200,rewardItems={116062,116064},rewardCurrencies={{currencyID=515,quantity=1}},starts={{npcID=85519}},ends={{npcID=85519}},coords={x=0.474,y=0.622,source="quest_giver",zoneID=5861},questType="standard"},
[36473] = {id=36473,name="Affliction Ridge",level=15,requiredLevel=15,faction="none",expansion=5,zoneID=6721,mapID=543,rewardGold=849000,rewardXP=2090,questType="world",db2Objectives={{orderIndex=0,type=0,amount=25,objectID=81786,text="Monsters slain"},{orderIndex=1,type=0,amount=5,objectID=85524,text="Ancient Seedbearer burned"}},worldTaskTitle="Affliction Ridge"},
[36474] = {id=36474,name="The Razorbloom",level=15,requiredLevel=15,faction="horde",expansion=5,zoneID=6721,mapID=543,description="The Laughing Skull shaman Kaz ran off while we were coming here. She claimed to be looking for more of her people in the jungles to the south. Draka insisted on following her to safeguard us against betrayal. Commander, if Kaz is telling the truth, then she and Draka are going to need all the help they can get. Will you join them? They could not have gotten far. This could prove to be the perfect test for your new shredder and lumber mill resources.",objectivesText="Find Draka and Kaz at the Razorbloom.",rewardGold=40373,rewardXP=260,starts={{npcID=74594}},ends={{npcID=74593}},coords={x=0.372,y=0.77,source="quest_giver",zoneID=6721},questType="standard"},
[36475] = {id=36475,name="Stealing the Declaration",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,mapID=525,description="Commander, you and Raleigh did a great job finding me, but I'm exactly where I need to be. We've been working tirelessly since we got here, trying to crack these Draenic texts. I really thought I was gonna get the scrolls, but they nabbed me at the last possible second! Please, you've gotta help me out... up the hill to the east, you'll find the Master Siegesmith's tent. If you can grab the documents out of his chest, possibly this key too, I'll finally have enough to translate their languages.",objectivesText="Loot the contents of Master Siegesmith Uratok's Strongbox. Progress: A book of poems? I'll let you hang onto that one for now....",rewardGold=169800,rewardXP=1415,rewardItems={111815,111923,116114,120136},starts={{npcID=85440}},ends={{npcID=85440}},coords={x=0.612,y=0.712,source="quest_giver",zoneID=6720},questType="standard"},
[36476] = {id=36476,name="South Gronn Canyon",level=15,requiredLevel=15,faction="none",expansion=5,zoneID=9786,mapID=543,rewardGold=849000,rewardXP=2090,questType="world",db2Objectives={{orderIndex=0,type=0,amount=15,objectID=85528,text="Goren or Gronnling slain"},{orderIndex=1,type=0,amount=10,objectID=75091,text="Grom'kar Grunt slain"},{orderIndex=2,type=0,amount=8,objectID=85540,text="Dying Grom'kar Peon executed"}},worldTaskTitle="South Gronn Canyon"},
[36477] = {id=36477,name="Broken Promises",level=40,requiredLevel=40,faction="both",expansion=5,zoneID=5861,description="A heavily-scratched ring, faintly stained with blood. Someone at the Darkmoon Faire might be able to provide more information about this item.",objectivesText="Find someone at the Darkmoon Faire that might be interested in the ring. Provided item:",rewardGold=84900,rewardXP=1365,rewardItems={116067},ends={{npcID=85484}},coords={mapID=407,x=0.748,y=0.334},questType="standard"},
[36480] = {id=36480,name="Valley of Destruction",level=15,requiredLevel=15,faction="none",expansion=5,zoneID=6721,mapID=543,rewardGold=849000,rewardXP=2090,questType="world",db2Objectives={{orderIndex=2,type=0,amount=15,objectID=85567,text="Goren Eggs broken"}},worldTaskTitle="Valley of Destruction"},
[36481] = {id=36481,name="Firebird's Challenge",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=5861,description="You're ready to fly high and give the Firebird's challenge a shot? That's great! Simply collect 15 rings to win! Speak to me when you're ready for takeoff!",objectivesText="Collect 15 rings while flying. Progress: How was the flight?",rewardItems={93724},starts={{npcID=85546}},ends={{npcID=85546}},coords={x=0.484,y=0.714,source="quest_giver",zoneID=5861},questType="standard"},
[36482] = {id=36482,name="A Green Ogron?",level=15,requiredLevel=15,faction="horde",expansion=5,zoneID=6721,mapID=543,description="Kaz always told me green ogron are bad. The botani here have a green ogron and it is mean. It was strong enough to take out my dad's entire hunting party. Are you strong enough to kill it?",objectivesText="Kill the Infested Ogron .",rewardGold=393150,rewardXP=2090,rewardItems={112591,112592,112593,112594},rewardChoices={112591,112592,112593,112594},starts={{npcID=82254},{npcID=82274}},ends={{npcID=82274}},coords={x=0.436,y=0.84,source="quest_giver",zoneID=6721},questType="standard"},
[36483] = {id=36483,name="Battle Pet Roundup",level=1,requiredLevel=1,faction="alliance",expansion=5,zoneID=7078,description="Looks like we've got some visitors in the battle pen today, and they're looking for a fight. Why don't you show 'em how a master of pet battles handles ?",objectivesText="Defeat the pets in the battle area. Progress: Those pets looked tough. How'd you do?",rewardGold=34100,rewardXP=25,rewardItems={163036,116415},starts={{npcID=85418}},ends={{npcID=85418}},coords={x=0.288,y=0.392,source="quest_giver",zoneID=7078},questType="standard"},
[36488] = {id=36488,name="Thieving Dwarves",level=15,requiredLevel=15,faction="horde",expansion=5,zoneID=6721,mapID=543,description="Cutter is on the trail of the artifact the dwarves stole. He has the nose of a wolf when it comes to hunting in the jungle. Follow the canyons south until you find him. It would seem the wolf queen and I are going to do more damage here before we leave. We will follow as quickly as we can.",objectivesText="Find Cutter at Bastion Rise.",rewardGold=118875,rewardXP=2090,starts={{npcID=82228}},ends={{npcID=85601}},coords={x=0.42,y=0.858,source="quest_giver",zoneID=6721},questType="standard"},
[36489] = {id=36489,name="Assault on the Pit",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=6721,description="The Iron Horde are stockpiling their weapons and ammunition outside of the Foundry. Their campaign throughout Draenor has left their caches vulnerable. Get in there and cause as much chaos as you can, and while you're at it use some of that ammunition against them if they're just going to leave it lying around!",objectivesText="Destroy Iron Horde weapons cache and take out as many of them as you can.",coords={mapID=543,x=0.484,y=0.258},questType="standard",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Blackrock Foundry Assaulted"},{orderIndex=1,type=0,amount=100,objectID=85228,text="Kill Iron Horde"},{orderIndex=2,type=0,amount=20,objectID=85229,text="Kill Iron Horde"},{orderIndex=3,type=0,amount=5,objectID=85230,text="Kill Iron Horde"},{orderIndex=4,type=0,amount=200,objectID=86298,text="Kill Iron Horde"},{orderIndex=5,type=2,amount=100,objectID=236277,text="Destroy Training Manuals"},{orderIndex=6,type=2,amount=50,objectID=236444,text="Free Laughing Skull Prisoners"}},worldTaskTitle="Assault on the Pit"},
