[36494] = {id=36494,name="News from Talador",level=20,requiredLevel=20,faction="horde",expansion=5,zoneID=7004,mapID=543,description="Rokhan sends word that you are needed at Frostwall. The Iron Horde have landed on the shores of Talador .",objectivesText="Speak to Rokhan at your garrison in Frostfire Ridge.",rewardGold=26680,rewardXP=345,starts={{npcID=74594}},ends={{npcID=78487}},coords={x=0.372,y=0.77,source="quest_giver",zoneID=6721},questType="standard"},
[36495] = {id=36495,name="News from Talador",level=20,requiredLevel=20,faction="alliance",expansion=5,zoneID=7078,mapID=543,description="Bodrick Grey sends word from your garrison that they have spotted a fleet of Iron Horde at the shores of Talador . We must not allow them to destroy Shattrath.",objectivesText="Speak to Bodrick Grey at your garrison in Shadowmoon Valley.",rewardGold=8955,rewardXP=345,starts={{npcID=75127}},ends={{npcID=81492}},coords={x=0.528,y=0.596,source="quest_giver",zoneID=6721},questType="standard"},
[36498] = {id=36498,name="Iron Horde Invasion",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=4,mapID=17,description="By order of his royal highness, King Varian Wrynn, all able-bodied citizens of the Alliance are to report to Vindicator Maraad at the Shattered Beachhead in Blasted Lands . Use the portal at the Wizard's Sanctum in Stormwind to head directly to the front line. This new threat is known only as the Iron Horde. They have taken over the Dark Portal and must be stopped. For the glory and honor of the Alliance!",objectivesText="Speak with Vindicator Maraad at the Shattered Beachhead in Blasted Lands .",rewardGold=169800,rewardXP=1415,starts={{npcID=206111},{npcID=206294}},ends={{npcID=82270}},coords={x=0.629,y=0.717,source="quest_giver",zoneID=1519},questType="standard"},
[36500] = {id=36500,name="The Razorbloom",level=15,requiredLevel=15,faction="none",expansion=5,zoneID=6721,mapID=543,rewardGold=849000,rewardXP=2090,questType="world",db2Objectives={{orderIndex=0,type=0,amount=12,objectID=81617,text="Infested slain"},{orderIndex=2,type=0,amount=25,objectID=85732,text="Toxic Slimemold squished"}},worldTaskTitle="The Razorbloom"},
[36502] = {id=36502,name="Trophy of Glory: Biolante",level=15,requiredLevel=15,faction="alliance",expansion=5,zoneID=6721,mapID=543,description="Defeating Biolante has yielded you a trophy worthy of showing off at your outpost. Return this to Maraad to increase your glory!",objectivesText="Take the trophy to Maraad at Highpass in Gorgrond . Provided item:",rewardGold=509400,rewardXP=2615,ends={{npcID=75127}},coords={mapID=543,source="quest_giver",x=0.6,y=0.564},questType="standard"},
[36503] = {id=36503,name="Trophy of Glory: Biolante",level=15,requiredLevel=15,faction="horde",expansion=5,zoneID=6721,mapID=543,description="Defeating Biolante has yielded you a trophy worthy of acclaim. Take this to Durotan at Beastwatch.",objectivesText="Take the trophy to Durotan at Beastwatch in Gorgrond . Provided item:",rewardGold=237750,rewardXP=2615,ends={{npcID=74594}},coords={mapID=543,source="quest_giver",x=0.415333,y=0.737333},questType="standard"},
