[36505] = {id=36505,name="A Warrior's Shroud",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,mapID=525,description="Although this cloak has seen better days, the workmanship is still quite impressive. Any normal cloak would have most certainly fallen apart by now. Perhaps one of the Frostwolf orcs within Wor'gol would be willing to help you repair it.",objectivesText="Locate a Frostwolf leatherworker in Wor'gol that can help you. Progress: Greetings, <race>. do you require any repairs?",rewardGold=16980,rewardXP=175,ends={{npcID=85751}},coords={mapID=525,source="quest_giver",x=0.206,y=0.602},questType="standard"},
