[36508] = {id=36508,name="Is This One of Yours?",level=15,requiredLevel=15,faction="alliance",expansion=5,zoneID=6721,mapID=543,description="I found this one skulking nearby. She claims to be an ally of yours. Is this true? Or does she cook slowly over my fire?",objectivesText="Talk to Rexxar and vouch for Rangari Erdanii .",rewardGold=375570,rewardXP=2090,starts={{npcID=83569}},ends={{npcID=82610}},coords={x=0.46,y=0.548,source="quest_giver",zoneID=6721},questType="standard"},
