[36510] = {id=36510,name="Fire Ammonite",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=7078,description="We need to stock the garrison pond with local fish. I need you to search the waters in Frostfire Ridge for fish that we can stock up with. Once you have the fish, you will need to slice them up and look for eggs inside.",objectivesText="Ron Ashton wants you to collect 10 Fire Ammonite Eggs from Frostfire Ridge. Progress: Anything biting?",rewardGold=169800,rewardXP=1415,rewardItems={112623},starts={{npcID=77733}},ends={{npcID=77733}},coords={x=0.54,y=0.134,source="quest_giver",zoneID=7078},questType="standard"},
