[36516] = {id=36516,name="Cut 'Em Out!",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,mapID=525,description="After all that you've done for us, I would love to help you. Regrettably, I don't have the materials I would need to repair this perfectly. Use my knife to gather a few hides from the clefthoof that roam near the spire and find some sootweed pitch to properly cure them. Unfortunately, those miserable ogres have taken up residence in the only place that I know of sootweed to grow. You may be in for a fight . Return to me if you can obtain these and I will gladly help you repair your cloak.",rewardGold=169800,rewardXP=1415,rewardItems={111818,115358,117566},starts={{npcID=85751}},ends={{npcID=85751}},coords={x=0.206,y=0.602,source="quest_giver",mapID=525},questType="standard"},
