[36523] = {id=36523,name="A Green Ogron?",level=15,requiredLevel=15,faction="alliance",expansion=5,zoneID=6721,mapID=543,description="Them botani got themselves a green ogron. A green ogron! I mean I may not know much about plant people but that canno' be a good thing. Think ya can take it in a fight?",objectivesText="Kill the Infested Ogron .",rewardGold=393150,rewardXP=2090,rewardItems={112591,112592,112593,112594},rewardChoices={112591,112592,112593,112594},starts={{npcID=81601}},ends={{npcID=81601}},coords={x=0.42,y=0.834,source="quest_giver",zoneID=6721},questType="standard"},
