[36567] = {id=36567,name="Bigger is Better",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=7004,mapID=525,description="Ya know boss, I think I know how we can take this place to the next level. Bigger walls. More buildings. Some space to stretch your arms after a long day of adventuring. Don't get me wrong, it's going to take a lot of resources, but what else are these things for? We can plot it out on the drafting table whenever you're ready. It's going to be GLORIOUS.",objectivesText="Use the Architect Table to select your Town Hall and upgrade your garrison to Tier 2. Progress: What ya waitin' for boss? Let's take this thing to the next level!",starts={{npcID=78466}},ends={{npcID=78466}},coords={x=0.488,y=0.65,source="quest_giver",zoneID=6720},questType="standard"},
[36568] = {id=36568,name="Vignette: Malgosh Shadowkeeper",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6719,mapID=539,questType="standard"},
[36571] = {id=36571,name="Iyun Weald",level=15,requiredLevel=15,faction="none",expansion=5,zoneID=6721,mapID=543,rewardGold=849000,rewardXP=2090,questType="world",db2Objectives={{orderIndex=1,type=0,amount=20,objectID=85815,text="Thorny Leafling punted"}},worldTaskTitle="Iyun Weald"},
[36573] = {id=36573,name="Strike While the Iron is Hot",level=15,requiredLevel=15,faction="horde",expansion=5,zoneID=6721,mapID=543,description="With the Heart of the Mangaron, we wield a powerful weapon against the Iron Horde. They amass far to the north at the Iron Approach. This will not be easy, but we must seize the opportunity to deal a blow to the Iron Horde while we possess the artifact. We are prepared to depart at your command. Speak with Grinslicer when you are ready.",objectivesText="Speak to Grinslicer to fly to the Iron Approach and attack the Iron Horde. Progress: The mysteries of this land sometimes bear fruit.",rewardGold=15750,rewardXP=260,rewardItems={112885,112887,112889,118019,118020,118021},rewardChoices={118020,118021,118019},starts={{npcID=74594}},ends={{npcID=74594}},coords={x=0.372,y=0.77,source="quest_giver",zoneID=6721},questType="standard"},
[36574] = {id=36574,name="Strike While the Iron is Hot",level=15,requiredLevel=15,faction="horde",expansion=5,zoneID=6721,mapID=543,description="With the Will of the Genesaur, we wield a powerful weapon. Our scouts have discovered an Iron Horde base, and I believe it is time to seize an opportunity. They amass far to the north at the Iron Approach. This will not be easy, but we must deal a blow to the Iron Horde while we possess the artifact. We are prepared to depart at your command. Speak with Grinslicer when you are ready.",objectivesText="Speak to Grinslicer to fly to the Iron Approach and attack the Iron Horde. Progress: The mysteries of this land sometimes bear fruit.",rewardGold=254700,rewardXP=2090,rewardItems={112885,112887,112889},rewardChoices={112887,112889,112885},starts={{npcID=74594}},ends={{npcID=74594}},coords={x=0.372,y=0.77,source="quest_giver",zoneID=6721},questType="standard"},
[36575] = {id=36575,name="Strike While the Iron is Hot",level=15,requiredLevel=15,faction="alliance",expansion=5,zoneID=6721,mapID=543,description="With the Will of the Genesaur, we wield a powerful weapon. Our scouts have discovered an Iron Horde base, and I believe this is the time to seize an opportunity. They amass far to the north at the Iron Approach. This will not be easy, but we must deal a blow to the Iron Horde while we possess the artifact. We are prepared to depart at your command. Speak with Rangari Rajess when you are ready.",objectivesText="Speak to Rangari Rajess to fly to the Iron Approach and attack the Iron Horde. Progress: We must eradicate the Iron Horde.",rewardGold=40373,rewardXP=260,rewardItems={112885,112887,112889},rewardChoices={112887,112889,112885},starts={{npcID=75127}},ends={{npcID=75127}},coords={x=0.528,y=0.596,source="quest_giver",zoneID=6721},questType="standard"},
[36576] = {id=36576,name="Strike While the Iron is Hot",level=15,requiredLevel=15,faction="alliance",expansion=5,zoneID=6721,mapID=543,description="With the Heart of the Magnaron, we wield a powerful weapon against the Iron Horde. They amass far to the north at the Iron Approach. This will not be easy, but we must seize the opportunity to deal a blow to the Iron Horde while we possess the artifact. We are prepared to depart at your command. Speak with Rangari Rajess when you are ready.",objectivesText="Speak to Rangari Rajess to fly to the Iron Approach and attack the Iron Horde. Progress: We must eradicate the Iron Horde.",rewardGold=40373,rewardXP=260,rewardItems={112885,112887,112889},rewardChoices={112887,112889,112885},starts={{npcID=75127}},ends={{npcID=75127}},coords={x=0.528,y=0.596,source="quest_giver",zoneID=6721},questType="standard"},
