[36589] = {id=36589,name="Heavy Arms",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=7004,mapID=525,description="The burned out shell of some sort of weapon of mass destruction. It might be worth asking around your garrison to see if anyone can help get it working again.",objectivesText="Look around the garrison for help with the repairs. Progress: Yo, boss. Whatchya got for me?",rewardGold=16980,rewardXP=175,ends={{npcID=85882}},questType="standard"},
[36590] = {id=36590,name="The Howling Crag",level=30,requiredLevel=30,faction="none",expansion=5,zoneID=6722,objectivesText="Pale Orcs slain Rylak Eggs destroyed Ritual of Siphoning Disrupted Ritual of the Void Disrupted Ritual of Destruction Disrupted Stored Projection Slain",rewardGold=849000,rewardXP=4115,coords={mapID=542,x=0.65,y=0.259},questType="standard",db2Objectives={{orderIndex=1,type=0,amount=5,objectID=85877,text="Rylak Eggs destroyed"},{orderIndex=0,type=0,amount=15,objectID=85883,text="Pale Orcs slain"},{orderIndex=2,type=0,amount=1,objectID=85884,text="Ritual of Siphoning Disrupted"},{orderIndex=3,type=0,amount=1,objectID=85885,text="Ritual of the Void Disrupted"},{orderIndex=4,type=0,amount=1,objectID=85886,text="Ritual of Destruction Disrupted"},{orderIndex=5,type=0,amount=1,objectID=85887,text="Stored Projection Slain"}},worldTaskTitle="The Howling Crag"},
[36592] = {id=36592,name="Bigger is Better",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=7078,description="Commander, I've been working on schematics that you might be interested in. What do you think about pushing out the walls and making room to get some additional structures in here? Our forces have been growing, and things are getting a little cramped, and I'd really like us to put some of those additional blueprints to use. If you could, take a look at the plans on the table here. As soon as I have your go ahead, I'll get everyone to work immediately.",objectivesText="Use the Architect Table to select your Town Hall and upgrade your garrison to Tier 2. Progress: What do you think? Time for an upgrade?",rewardItems={248661},starts={{npcID=77209}},ends={{npcID=77209}},coords={x=0.32,y=0.314,source="quest_giver",zoneID=7078},questType="standard"},
[36594] = {id=36594,name="\"Spare\" Parts",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,description="I've never seen anything like this before! No problem though, boss man. If it can be used to blow things up, I can get it working again. We are definitely going to need some parts--some sort of ammunition wouldn't hurt either. Sounds like those Iron Horde guys over yonder are no stranger to things that go boom. Take these tools with you and let's see if we can't commandeer us some spare parts!",objectivesText="Recover 20 Black Iron Shells and 50 Siege Cannon Parts . Progress: Got the stuff yet boss?",rewardGold=276200,rewardXP=1415,starts={{npcID=85882}},ends={{npcID=85882}},coords={x=0.622,y=0.734,source="quest_giver",zoneID=7004},questType="standard"},
[36595] = {id=36595,name="He Drew Aggro...culture",level=15,requiredLevel=15,faction="alliance",expansion=5,zoneID=6721,mapID=543,description="What you saw was the wake of the genesaur, Iyu. It was chasing this mechanical monstrosity and the person who drove it. I believe the pilot of this vessel is still alive and trapped within the ruins of the camp. If you wish them to be recovered, I recommend doing so now.",objectivesText="Find the pilot of the Dark Iron tank.",rewardGold=386100,rewardXP=2090,starts={{npcID=75146}},ends={{npcID=75136}},coords={x=0.632,y=0.522,source="quest_giver",zoneID=6721},questType="standard"},
[36596] = {id=36596,name="Treasure: Iron Horde Weapon Stash",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6721,mapID=543,ends={{npcID=235869}},questType="standard"},
