[36601] = {id=36601,name="News from Nagrand",level=30,requiredLevel=30,faction="alliance",expansion=5,zoneID=7078,mapID=542,description="One of your soldiers stopped by asking for you while you were out. Something about a caravan heading out to Nagrand. Whatever it was, it can't have gone well for them. That's Warsong territory.",objectivesText="Speak to Bodrick Grey at your garrison in Shadowmoon Valley.",rewardGold=16980,rewardXP=515,starts={{npcID=80153}},ends={{npcID=81492}},coords={x=0.458,y=0.456,source="quest_giver",zoneID=6722},questType="standard"},
[36602] = {id=36602,name="News from Nagrand",level=30,requiredLevel=30,faction="horde",expansion=5,zoneID=7004,mapID=542,description="One of your soldiers stopped by asking for you while you were out. Something about a caravan heading out to Nagrand. Whatever it was, it can't have gone well for them. That's Warsong territory.",objectivesText="Speak to Rokhan at your garrison in Frostfire Ridge.",rewardGold=16980,rewardXP=515,starts={{npcID=80153}},ends={{npcID=78487}},coords={x=0.458,y=0.456,source="quest_giver",zoneID=6722},questType="standard"},
[36603] = {id=36603,name="Brimstone Springs",level=15,requiredLevel=15,faction="none",expansion=5,zoneID=6721,mapID=543,rewardGold=849000,rewardXP=2090,questType="world",db2Objectives={{orderIndex=0,type=0,amount=8,objectID=85924,text="Brimfury slain"}},worldTaskTitle="Brimstone Springs"},
[36604] = {id=36604,name="Treasure: Dark Iron Emergency Pack",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6721,mapID=543,starts={{npcID=78260}},ends={{npcID=236092}},questType="standard"},
[36605] = {id=36605,name="Treasure: Dark Iron Remains",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6721,mapID=543,ends={{npcID=236096}},questType="standard"},
[36606] = {id=36606,name="News from Nagrand",level=30,requiredLevel=30,faction="alliance",expansion=5,zoneID=7078,mapID=542,description="Welcome back, . One of Bodrick's men delivered a message about a caravan being dispatched for Nagrand. He's awaiting your approval on a new outpost. I've been hearing whispers around camp about Nagrand. They say it's Warsong territory. They might need your help .",objectivesText="Speak to Bodrick Grey at your garrison in Shadowmoon Valley.",rewardGold=16980,rewardXP=515,starts={{npcID=81929}},ends={{npcID=81492}},coords={x=0.398,y=0.608,source="quest_giver",zoneID=6722},questType="standard"},
[36607] = {id=36607,name="News from Nagrand",level=30,requiredLevel=30,faction="horde",expansion=5,zoneID=7004,mapID=542,description="Welcome back, . One of our shadow hunters delivered a message about a caravan being dispatched for Nagrand. Rokhan 's awaiting your approval on a new outpost. I've been hearing whispers around camp about Nagrand. They say it's Warsong territory. They might need your help .",objectivesText="Speak to Rokhan at your garrison in Frostfire Ridge.",rewardGold=16980,rewardXP=515,starts={{npcID=81920}},ends={{npcID=78487}},coords={x=0.402,y=0.434,source="quest_giver",zoneID=6722},questType="standard"},
[36608] = {id=36608,name="Finding Nat Pagle",level=20,requiredLevel=20,faction="both",expansion=5,zoneID=6134,mapID=418,description="Now that you have proof, we might just have a shot at convincing Nat Pagle to join us out here. Last I heard, he was in fishing with the local Angler's faction out in Pandaria. Somewhere off the coast of Krasarang Wilds. Head out there, show him your catch and see if you can get him to come back with you!",objectivesText="Travel to the Angler's Wharf in Krasarang Wilds and talk to Nat Pagle . Progress: You came all this way for me? Well, I am pretty important.",rewardGold=276200,rewardXP=2765,starts={{npcID=79971},{npcID=85708}},ends={{npcID=63721}},coords={x=0.376,y=0.702,source="quest_giver",zoneID=7004},questType="standard"},
[36609] = {id=36609,name="The Great Angler Returns",level=20,requiredLevel=20,faction="horde",expansion=5,zoneID=7004,mapID=418,description="What's this species, a molten catfish you say? I have never even heard of a fish like this, much less seen one in person! I have to find more fish like this, it's what I live for! And if the fishing is as good as you say it is, there is just no way I can pass this opportunity up. Take this page from my journal as proof that you found me and I will meet you back at your Garrison.",objectivesText="Return to Rak'jin with Nat's journal page as proof that you found him. Progress: You found Nat? The real Nat Pagle ?!",rewardGold=169800,rewardXP=2765,starts={{npcID=63721}},ends={{npcID=79971}},coords={x=0.684,y=0.434,source="quest_giver",zoneID=6134},questType="standard"},
[36610] = {id=36610,name="Treasure: Gorge Spear",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6721,mapID=543,ends={{npcID=236099}},questType="standard"},
[36611] = {id=36611,name="A True Draenor Angler",level=20,requiredLevel=20,faction="both",expansion=5,zoneID=7078,description="If you want me to help you permanently, you have to show me a few of these big Draenor catches first. Head out into the wild and bring me back the biggest fish you can find from all the surrounding areas. I made this custom lure for you to use, please take care of it, it's never let me down!",objectivesText="Catch a Lunker in each of the Draenor zones and bring them back to Nat Pagle . Progress: What did you catch?",rewardGold=169800,rewardXP=2765,starts={{npcID=85984}},ends={{npcID=85984}},coords={x=0.382,y=0.72,source="quest_giver",zoneID=7004},questType="standard"},
[36612] = {id=36612,name="Luring Nat",level=20,requiredLevel=20,faction="horde",expansion=5,zoneID=7004,description="Now that you are experienced enough with Draenor fishing, we might have a shot at convincing Nat Pagle to join us out here. If we want Nat to actually come all the way out here, we are going to have to show him real proof of the incredible catches on Draenor. Head out to the lava lakes here in Frostfire and see what you can do. All that time you spend honing your skill here in Draenor should pay off now.",objectivesText="Catch a Molten Catfish in Frostfire Ridge and bring it back to Rak'jin . Progress: Any luck near those lava pools?",rewardGold=169800,rewardXP=2765,starts={{npcID=79971}},ends={{npcID=79971}},coords={x=0.376,y=0.702,source="quest_giver",zoneID=7004},questType="standard"},
[36614] = {id=36614,name="My Very Own Fortress",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=7004,mapID=525,description="Boss! Guess what?! I finally got that new larger draft paper in that I ordered when we first came here. And ya know what larger draft paper means? It means I can draw a bigger fortress! And if I can draw it, I can certainly make it! Making's the easy part, as long as you've got a few thousand stones and logs lying around. So whada'ya say, boss? Shall we get building?",objectivesText="Gather 2000 Garrison Resources and then use the Architect Table to select your Town Hall and upgrade your garrison to Tier 3.",starts={{npcID=78466}},ends={{npcID=78466}},coords={x=0.488,y=0.65,source="quest_giver",zoneID=6720},questType="standard"},
[36615] = {id=36615,name="My Very Own Castle",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=7078,description="Commander! Some good news. I finally got that new larger draft paper in that I ordered when we first came here. And do you know what larger draft paper means? It means I can draw a bigger castle! And if I can draw it, we can certainly make it! Making it is the easy part, assuming you have a few thousand stones and logs lying around. So what do you say, sir? Shall we get building?",objectivesText="Gather 2000 Garrison Resources and then use the Architect Table to select your Town Hall and upgrade your garrison to Tier 3.",rewardItems={248800},starts={{npcID=77209}},ends={{npcID=77209}},coords={x=0.32,y=0.314,source="quest_giver",zoneID=7078},questType="standard"},
[36616] = {id=36616,name="An Angler on Our Team",level=20,requiredLevel=20,faction="both",expansion=5,zoneID=7078,description="You truly are a master fisherman! I would be delighted to join you here on Draenor and help you catch as many lunkers as you can. But first, let's grab a drink.",objectivesText="Talk to Nat Pagle and ask him to join our cause.",rewardGold=169800,rewardXP=2765,starts={{npcID=85984}},ends={{npcID=85984}},questType="standard"},
[36617] = {id=36617,name="A Winter Veil Gift",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=1637,mapID=85,rewardItems={116763},starts={{npcID=187236}},ends={{npcID=187236}},coords={x=0.335,y=0.66,source="quest_giver",mapID=85},questType="standard"},
[36618] = {id=36618,name="Treasure: Iron Supply Chest",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6721,mapID=543,ends={{npcID=236138}},questType="standard"},
[36621] = {id=36621,name="Treasure: Gnome Canister",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6721,mapID=543,starts={{npcID=78260}},ends={{npcID=236139}},questType="standard"},
[36623] = {id=36623,name="Ogre Invasion!",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=7078,description="Commander, our scouts say that ogre bands march through the snow. If they want more battle after the beating we already delivered, then I'm eager to oblige them.",objectivesText="Repel the ogre invasion of your garrison. (Speak with Sergeant Grimjaw again to begin) Progress: We must hold the line!",rewardGold=169800,rewardXP=8200,starts={{npcID=79774}},ends={{npcID=79774}},coords={x=0.44,y=0.476,source="quest_giver",zoneID=7004},questType="standard"},
[36624] = {id=36624,name="Ashran Appearance",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=7332,description="Our base on Ashran is almost complete, commander. It would be a huge show of support if you could make a trip out there and put your stamp of approval on their staging area. I can arrange a flight if you are interested.",objectivesText="Speak with Private Tristan at Stormshield in Ashran.",rewardGold=127350,rewardXP=1060,starts={{npcID=79953}},ends={{npcID=86065}},coords={x=0.292,y=0.346,source="quest_giver",zoneID=7078},questType="standard"},
[36625] = {id=36625,name="Treasure: Discarded Pack",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6721,mapID=543,starts={{npcID=78260}},ends={{npcID=236141}},questType="standard"},
[36626] = {id=36626,name="Host Howell",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=7332,description="Lieutenant Howell said you might be showing up. It's such an honor to meet you in person. The lieutenant is at the inn, I'll escort you over there.",objectivesText="Speak with Lieutenant Howell .",rewardGold=42450,rewardXP=355,starts={{npcID=86065}},ends={{npcID=86069}},coords={x=0.318,y=0.496,source="quest_giver",zoneID=7332},questType="standard"},
[36627] = {id=36627,name="Big Frostfire Gun",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=7004,description="One of my finest works, ! Momma would be so proud of me right now... if she was still in one piece. We gotta test this bad boy out though before I'm comfortable letting you run around with it all willy-nilly. I heard there were some clefthooves out back causing a ruckus.",objectivesText="Subdue 6 Clefthooves. Progress: Did you manage to subdue those rowdy clefthooves?",rewardGold=59440,rewardXP=1060,rewardItems={109258,111921},starts={{npcID=85882}},ends={{npcID=85882}},coords={x=0.622,y=0.734,source="quest_giver",zoneID=7004},questType="standard"},
[36628] = {id=36628,name="Treasure: Hammer of Glory",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6721,mapID=543,ends={{npcID=236147}},questType="standard"},
[36629] = {id=36629,name="Inspiring Ashran",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=7332,description="I hope you will find our facilities to be up to your high standards. This inn is run by Jaesia Rosecheer , in my opinion this is the best place to hearth in Draenor. We have new recruits coming through the portal daily. In fact our latest recruit, Knewbie McGreen just came through the portal today. If you are looking to trade for weapons or armor, Vindicator Nuurem will be happy to help.",objectivesText="Speak with Jaesia Rosecheer , Vindicator Nuurem , and Knewbie McGreen . Progress: How did your walk go?",rewardGold=127350,rewardXP=1060,starts={{npcID=86069}},ends={{npcID=86069}},coords={x=0.356,y=0.754,source="quest_giver",zoneID=7332},questType="standard"},
[36630] = {id=36630,name="A Surly Dwarf",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=7332,description="Before you go there is someone you might want to talk with. He's opinionated, a bit gruff, and very overbearing, but he's the best damn warrior I've met in ages. He belongs on the front lines with you, commander. And trust me, he knows it.",objectivesText="Speak with Delvar Ironfist .",rewardGold=169800,rewardXP=1415,starts={{npcID=86069}},ends={{npcID=86084}},coords={x=0.356,y=0.754,source="quest_giver",zoneID=7332},questType="standard"},
[36631] = {id=36631,name="Treasure: Sasha's Stash",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6721,mapID=543,ends={{npcID=236149}},questType="standard"},
[36632] = {id=36632,name="The Secrets of Gorgrond",level=15,requiredLevel=15,faction="alliance",expansion=5,zoneID=6721,mapID=543,description="Commander, I was dispatched to intercept you. Yrel and Maraad have landed at Wildwood Wash, the rangari base of operations for the area. Your presence is requested immediately. We keep a small feywing presence just east of here. If you speak with the flight master they should be able to provide you safe passage to the Wash.",objectivesText="Seek Yrel at the Wildwood Wash in Gorgrond . Speak with your Garrison Gryphon Master or the Flight Master at Bastion Rise to fly there.",rewardGold=11888,rewardXP=260,starts={{npcID=86088}},ends={{npcID=80978}},coords={x=0.42,y=0.94,source="quest_giver",zoneID=6721},questType="standard"},
[36633] = {id=36633,name="Delvar Ironfist",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=7332,rewardGold=17450,rewardXP=1415,starts={{npcID=86084}},ends={{npcID=86084}},coords={x=0.476,y=0.306,source="quest_giver",zoneID=7332},questType="standard"},
[36634] = {id=36634,name="Treasure: Sniper's Crossbow",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6721,mapID=543,ends={{npcID=236158}},questType="standard"},
