[36640] = {id=36640,name="Followers Obtained",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6662,mapID=535,questType="standard"},
[36641] = {id=36641,name="Your First Alchemy Work Order",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=7078,description="Now that the alchemy lab is complete, we can start producing alchemical catalysts for you. When you have the ingredients, please speak with my assistant to start the first work order.",objectivesText="Start and collect your first Alchemy work order at the Alchemy Lab. Progress: Yes?",rewardGold=16980,rewardXP=175,rewardItems={108996},starts={{npcID=77363}},ends={{npcID=77791}},coords={x=0.502,y=0.578,source="quest_giver",zoneID=7078},questType="standard"},
[36642] = {id=36642,name="Your First Leatherworking Work Order",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=7078,description="Now that the tannery is complete, we can start producing burnished leather for you. When you have the ingredients, please speak with my assistant to start the first work order.",objectivesText="Start and collect your first Leatherworking work order at the Tannery. Progress: Yes?",rewardGold=16980,rewardXP=175,rewardItems={110611},starts={{npcID=77383}},ends={{npcID=78207}},coords={x=0.502,y=0.574,source="quest_giver",zoneID=7078},questType="standard"},
[36643] = {id=36643,name="Your First Tailoring Work Order",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=7078,description="Now that the tailoring emporium is complete, we can start producing hexweave cloth for you. When you have the ingredients, please speak with my assistant to start the first work order.",objectivesText="Start and collect your first Tailoring work order at the Tailoring Emporium. Progress: Yes?",rewardGold=16980,rewardXP=175,rewardItems={111556},starts={{npcID=77382}},ends={{npcID=77778}},coords={x=0.468,y=0.59,source="quest_giver",zoneID=7078},questType="standard"},
[36644] = {id=36644,name="Your First Jewelcrafting Work Order",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=7078,description="Now that the gem boutique is complete, we can start producing taladite crystals for you. When you have the ingredients, please speak with my assistant to start the first work order.",objectivesText="Start and collect your first Jewelcrafting work order at the Gem Boutique. Progress: Yes?",rewardGold=16980,rewardXP=175,rewardItems={115524},starts={{npcID=77356}},ends={{npcID=77775}},coords={x=0.504,y=0.578,source="quest_giver",zoneID=7078},questType="standard"},
[36645] = {id=36645,name="Your First Enchanting Work Order",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=7078,description="Now that the enchanter's study is complete, we can start producing draenic dust for you. When you have the ingredients, please speak with my assistant to start the first work order.",objectivesText="Start and collect your first Enchanting work order at the Enchanter's Study. Progress: Yes?",rewardGold=16980,rewardXP=175,rewardItems={115504},starts={{npcID=77354}},ends={{npcID=77781}},coords={x=0.468,y=0.594,source="quest_giver",zoneID=7078},questType="standard"},
[36646] = {id=36646,name="Your First Engineering Work Order",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=7078,description="Now that the engineering works is complete, we can start producing gearspring parts for you. When you have the ingredients, please speak with my assistant to start the first work order.",objectivesText="Start and collect your first Engineering work order at the Engineering Works. Progress: Yes?",rewardGold=16980,rewardXP=175,rewardItems={111366},starts={{npcID=77365}},ends={{npcID=77831}},coords={x=0.504,y=0.574,source="quest_giver",zoneID=7078},questType="standard"},
[36647] = {id=36647,name="Your First Inscription Work Order",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=7078,description="Now that the scribe's quarters are complete, we can start producing war paints for you. When you have the ingredients, please speak with my assistant to start the first work order.",objectivesText="Start and collect your first Inscription work order at the Scribe's Quarters. Progress: Yes?",rewardGold=16980,rewardXP=175,rewardItems={112377},starts={{npcID=77372}},ends={{npcID=77777}},coords={x=0.502,y=0.574,source="quest_giver",zoneID=7078},questType="standard"},
[36648] = {id=36648,name="Assault on Stonefury Cliffs",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=7078,mapID=539,description="Bloodmaul ogres from Frostfire Ridge have been ambushing trade routes throughout the continent, and are putting captured soldiers to work in their slag mines. Bodrick Grey has requested the rescue of friendly troops that have been taken prisoner in the main Bloodmaul compound at Stonefury Cliffs.",objectivesText="Assault the Bloodmaul ogres at Stonefury Cliffs in Frostfire Ridge.",rewardGold=509400,rewardXP=1365,rewardCurrencies={{id=823,amount=800}},ends={{npcID=81152}},coords={mapID=539,source="quest_giver",x=0.406,y=0.548},questType="standard"},
[36649] = {id=36649,name="Assault on Shattrath Harbor",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=7078,mapID=539,description="Shattrath City is in the hands of Sargerei forces under the leadership of the traitor Exarch, Socrethar. Members of the Sha'tari Defense have been requesting aid against the Shadow Council forces in the eastern portions of the city.",objectivesText="Assault the Sargerei forces at Shattrath City in Talador.",rewardGold=509400,rewardXP=1365,rewardCurrencies={{id=823,amount=800}},ends={{npcID=81152}},coords={mapID=539,source="quest_giver",x=0.406,y=0.548},questType="standard"},
[36650] = {id=36650,name="Ogre Invasion!",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=7004,description="Scouts report that ogre packs march through Shadowmoon Valley. We've left our impression with them, eh Commander?",objectivesText="Repel the ogre invasion of your garrison. (Speak with Sergeant Crowler again to begin) Progress: We must hold the line!",rewardGold=169800,rewardXP=8200,starts={{npcID=78564}},ends={{npcID=78564}},coords={x=0.382,y=0.32,source="quest_giver",zoneID=7078},questType="standard"},
[36651] = {id=36651,name="Treasure: SHarvest Crystal",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6721,mapID=543,ends={{npcID=236169}},questType="standard"},
[36653] = {id=36653,name="Botani Invasion!",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=7078,description="There's a weight in the air. Reminds me of battles in Stranglethorn Valley. Jungle warfare is good for axe-play.",objectivesText="Repel the botani invasion of your garrison. (Speak with Sergeant Grimjaw again to begin) Progress: We must hold the line!",rewardGold=169800,rewardXP=8200,starts={{npcID=79774}},ends={{npcID=79774}},coords={x=0.44,y=0.476,source="quest_giver",zoneID=7004},questType="standard"},
[36654] = {id=36654,name="Treasure: Lost Dwarf",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6721,mapID=543,starts={{npcID=78260}},ends={{npcID=236170}},questType="standard"},
[36655] = {id=36655,name="Iron Horde Invasion!",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=7004,description="There's smoke on the horizon... The Iron Horde is coming.",objectivesText="Speak with Sergeant Crowler . Progress: Repel the Iron Horde invasion. (Speak with Sergeant Crowler again to begin)",rewardGold=169800,rewardXP=8200,starts={{npcID=78564}},ends={{npcID=78564}},coords={x=0.382,y=0.32,source="quest_giver",zoneID=7078},questType="standard"},
