[36658] = {id=36658,name="Treasure: Botani Stockpile",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=6721,mapID=543,ends={{npcID=236178}},questType="standard"},
[36660] = {id=36660,name="Bloodmane Pridelands",level=30,requiredLevel=30,faction="none",expansion=5,zoneID=6722,mapID=542,rewardGold=849000,rewardXP=4115,questType="world",db2Objectives={{orderIndex=1,type=0,amount=6,objectID=86159,text="Free captured Ravenspeakers"}},worldTaskTitle="Bloodmane Pridelands"},
[36662] = {id=36662,name="Scrappin'",level=1,requiredLevel=1,faction="horde",expansion=5,zoneID=7004,description="Ever since we built da menagerie, a lot o' \"visitors\" been showin' up. I know da look, and they be lookin' for a fight. , you show 'em you da real master 'round here.",objectivesText="Defeat the pets in the battle area. Progress: Did you show 'em the mojo?",rewardGold=34100,rewardXP=25,rewardItems={163036,116415},starts={{npcID=79858}},ends={{npcID=79858}},coords={x=0.324,y=0.424,source="quest_giver",zoneID=7004},questType="standard"},
[36663] = {id=36663,name="Garrison Max-level Choice Tracker: ANY CHOICE MADE",level=1,requiredLevel=1,faction="alliance",expansion=5,zoneID=6720,mapID=525,rewardGold=616000,rewardXP=50,rewardItems={94219},questType="standard"},
[36664] = {id=36664,name="Garrison Max-level Choice Tracker: ANY CHOICE MADE",level=1,requiredLevel=1,faction="alliance",expansion=5,zoneID=6719,mapID=539,rewardGold=616000,rewardXP=50,rewardItems={94219},questType="standard"},
[36666] = {id=36666,name="Garrison Max-level Choice Tracker: ALL CHOICES DEBUG",level=1,requiredLevel=1,faction="alliance",expansion=5,zoneID=6719,mapID=539,rewardGold=616000,rewardXP=50,rewardItems={94219},questType="standard"},
[36667] = {id=36667,name="Assault on Shattrath Harbor",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=7004,description="Shattrath City is in the hands of Sargerei forces under the leadership of the once Exarch, Socrethar. The Shadow Council forces in the eastern portion of the city are gaining in power through the aid of demons from the Nether, and need to be culled before they become a threat to all of our operations.",objectivesText="Assault the Sargerei forces at Shattrath City in Talador.",rewardGold=509400,rewardXP=1365,rewardCurrencies={{id=823,amount=800}},ends={{npcID=78495}},coords={mapID=590,x=0.41,y=0.508},questType="standard"},
[36669] = {id=36669,name="Assault on Stonefury Cliffs",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=7004,description="Bloodmaul ogres from Frostfire Ridge have been ambushing trade routes throughout the continent, and are putting captured soldiers to work in their slag mines. Shadow Hunter Rokhan has requested the rescue of friendly troops that have been taken prisoner in the main Bloodmaul compound at Stonefury Cliffs.",objectivesText="Assault the Bloodmaul ogres at Stonefury Cliffs in Frostfire Ridge.",rewardGold=509400,rewardXP=1365,rewardCurrencies={{id=823,amount=800}},ends={{npcID=78495}},coords={mapID=590,x=0.41,y=0.508},questType="standard"},
[36670] = {id=36670,name="The Ring of Blood: Skull Chewer!",level=1,requiredLevel=1,faction="alliance",expansion=5,zoneID=6755,mapID=550,description="Welcome to Nagrand 's one and only Ring of Blood, where hopefuls become gladiators and gladiators become discarded piles of meat on the arena floor! Talk to me to start a fight, hop down into the ring, and fight for your life. It's positively brutal - and the crowd loves it! You'll face off against an ogron that has a hankering for freshly severed heads. You'll be fine... and I'll be rich!",objectivesText="Defeat Skull Chewer in the Ring of Blood.",starts={{npcID=84783}},ends={{npcID=84783}},coords={x=0.568,y=0.13,source="quest_giver",zoneID=6755},questType="group"},
[36674] = {id=36674,name="Assault on the Iron Siegeworks",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=7078,mapID=539,description="Iron Horde war machines are being shipped onto battlefields by the dozens, and our forces are struggling to hold their ground. Most of these machines seem to be originating from the Iron Siegeworks in eastern Frostfire Ridge. A strategic attack to disrupt and dismantle the Iron Horde at the siegeworks could be just what we need to turn the tide of the war.",objectivesText="Assault the Iron Horde forces at the Iron Siegeworks in Frostfire Ridge.",rewardGold=509400,rewardXP=1365,rewardCurrencies={{id=823,amount=800}},ends={{npcID=81152}},coords={mapID=539,source="quest_giver",x=0.406,y=0.548},questType="standard"},
[36675] = {id=36675,name="Assault on Magnarok",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=7078,mapID=539,description="Colossal magnaron, gronn, and other stone monstrosities have been threatening our outposts in the west. Most seem to originate from Magnarok in Frostfire Ridge. If we strike at them at their home, we should be able to force them back. It's risky, but it may be our best move. While you're there, see if you can recover any of our supplies.",objectivesText="Assault the stone monstrosities at Magnarok in Frostfire Ridge. Progress: How goes the assault, sir?",rewardGold=509400,rewardXP=1365,rewardCurrencies={{id=823,amount=800}},ends={{npcID=81152}},coords={mapID=539,source="quest_giver",x=0.406,y=0.548},questType="standard"},
[36676] = {id=36676,name="Assault on the Everbloom Wilds",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=7078,mapID=539,description="Botani and the plant monstrosities they conjure have been slowly encroaching on our outposts in the north. For every plant we kill, new ones seem to rise in its place. Bodrick Grey has put together a plan for striking at the heart of their lands, in Everbloom Wilds. He thinks this will draw them back into the wilds of Gorgrond, giving us more room to maneuver around them.",objectivesText="Assault the botani forces in the Everbloom Wilds of Gorgrond.",rewardGold=509400,rewardXP=1365,rewardCurrencies={{id=823,amount=800}},ends={{npcID=81152}},coords={mapID=539,source="quest_giver",x=0.406,y=0.548},questType="standard"},
[36677] = {id=36677,name="Assault on the Broken Precipice",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=7078,mapID=539,description="Massive ogron have been battering our frontlines, and no matter how many we down, there seem to be more to replace them. Most of these ogron appear to be coming from the Broken Precipice , deep in western Nagrand. If we're to stand a chance in the coming battles, we need to find a way to remove these ogron from the battlefield.",objectivesText="Assault the ogron forces at the Broken Precipice in Nagrand.",rewardGold=509400,rewardXP=1365,rewardCurrencies={{id=823,amount=800}},ends={{npcID=81152}},coords={mapID=539,source="quest_giver",x=0.406,y=0.548},questType="standard"},
[36678] = {id=36678,name="Assault on Mok'gol Watchpost",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=7078,mapID=539,description="Warsong raiders out of Mok'gol Watchpost have been terrorizing anything and everything not behind a tall wall. We've warned travelers not to stray out alone, but many don't listen. If we were to launch an assault on Mok'gol Watchpost, we would almost certainly put the Warsong back on the defensive, restricting most of their riders to Nagrand.",objectivesText="Assault the Warsong forces at Mok'gol Watchpost in Nagrand.",rewardGold=509400,rewardXP=1365,rewardCurrencies={{id=823,amount=800}},ends={{npcID=81152}},coords={mapID=539,source="quest_giver",x=0.406,y=0.548},questType="standard"},
[36679] = {id=36679,name="Assault on Darktide Roost",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=7078,mapID=539,description="There's been a resurgence of rylaks on the battlefield in our skirmishes against the Iron Horde. If we don't stop them at the source, we'll quickly lose control of the roads and be pushed back into our outposts. The most likely source of these additional rylaks is in southeastern Shadowmoon Valley, at Darktide Roost. If we move quickly, we should still have time to get ahead of the problem.",objectivesText="Assault the Iron Horde forces at Darktide Roost in Shadowmoon Valley.",rewardGold=509400,rewardXP=1365,rewardCurrencies={{id=823,amount=800}},ends={{npcID=81152}},coords={mapID=539,source="quest_giver",x=0.406,y=0.548},questType="standard"},
[36680] = {id=36680,name="Assault on Socrethar's Rise",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=7078,mapID=539,description="Recent reports suggest a notable rise of activity by Sargerei forces at Socrethar's Rise in southern Shadowmoon Valley. Socrathar's disciples pose a threat to draenei and our garrison alike. We need to quell them at our soonest convenience.",objectivesText="Assault the Sargerei forces at Socrethar's Rise in Shadowmoon Valley.",rewardGold=509400,rewardXP=1365,rewardCurrencies={{id=823,amount=800}},ends={{npcID=81152}},coords={mapID=539,source="quest_giver",x=0.406,y=0.548},questType="standard"},
[36681] = {id=36681,name="Assault on Lost Veil Anzu",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=7078,mapID=539,description="Some of our best scouts have gone missing in the vicinity of the lost ruins of Veil Anzu. Bodrick Grey has requested any available resources be dispatched to identify the threat and see if any of our men yet remain alive within the ruins.",objectivesText="Assault the hostile creatures at Lost Veil Anzu in Spires of Arak.",rewardGold=509400,rewardXP=1365,rewardCurrencies={{id=823,amount=800}},ends={{npcID=81152}},coords={mapID=539,source="quest_giver",x=0.406,y=0.548},questType="standard"},
[36682] = {id=36682,name="Assault on Pillars of Fate",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=7078,mapID=539,description="Remnants of the Shadowmoon clan continue to operate out of the peaks on the eastern border of Spires of Arak. Bodrick Grey is concerned at their proximity to the garrison, and has put out a request that we thin their forces as soon as possible.",rewardGold=509400,rewardXP=1365,rewardCurrencies={{id=823,amount=800}},ends={{npcID=81152}},coords={mapID=582,x=0.307,y=0.318},questType="standard"},
[36683] = {id=36683,name="Assault on Skettis",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=7078,mapID=539,description="We've been receiving regular reports of birdmen from the south ambushing and burning caravans along the main roads. Guards from our outposts are requesting that we launch a counter attack against the main presence of Adherents of Rukhmar at Skettis in Spires of Arak.",objectivesText="Assault the Adherents of Rukhmar at Skettis in Spires of Arak.",rewardGold=509400,rewardXP=1365,rewardCurrencies={{id=823,amount=800}},ends={{npcID=81152}},coords={mapID=539,source="quest_giver",x=0.406,y=0.548},questType="standard"},
[36684] = {id=36684,name="Battle in Ashran",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=7078,mapID=539,description="As we do battle all across Draenor, the cowardly Horde try to seize our territory within Ashran. Our men would be inspired to see you join the battlefield, striking terror into the hearts of the Horde.",objectivesText="Join the battle in Ashran.",rewardGold=679200,rewardXP=1365,rewardCurrencies={{id=823,amount=1000}},ends={{npcID=81152}},coords={mapID=539,source="quest_giver",x=0.406,y=0.548},questType="pvp"},
[36685] = {id=36685,name="Assault on the Heart of Shattrath",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=7078,mapID=539,description="Sargerei forces from deep in Shattrath have grown stronger and bolder by the day. We can no longer risk ignoring the threat that they pose. Bring allies if you wish to face the Sargerei so deep within the city.",objectivesText="Assault the Sargerei forces deep within Shattrath City in Talador.",rewardGold=679200,rewardXP=1365,rewardItems={251547},rewardCurrencies={{id=823,amount=1000}},ends={{npcID=81152}},coords={mapID=539,source="quest_giver",x=0.406,y=0.548},questType="group"},
[36686] = {id=36686,name="Assault on the Pit",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=7078,mapID=539,description="The Blackrock forces based out of the Pit in Gorgrond make up the bulk of the Iron Horde army. If we crush them on their home soil, the rest of the Iron Horde will have little hope of standing against us. If you choose the battle, bring friends. The Blackrock won't be defeated easily.",objectivesText="Assault the Blackrock orcs at the Pit in Gorgrond.",rewardGold=679200,rewardXP=1365,rewardCurrencies={{id=823,amount=1000}},ends={{npcID=81152}},coords={mapID=539,source="quest_giver",x=0.406,y=0.548},questType="group"},
[36687] = {id=36687,name="Challenge at the Ring of Blood",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=7078,mapID=539,description="A challenge has been issued at the Ring of Blood. Bring friends and do battle to prove your right as champion.",objectivesText="Do battle at the Ring of Blood.",rewardGold=679200,rewardXP=1365,rewardCurrencies={{id=823,amount=1000}},ends={{npcID=81152}},coords={mapID=539,source="quest_giver",x=0.406,y=0.548},questType="group"},
[36688] = {id=36688,name="Assault on Skettis",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=7004,description="We've been receiving regular reports of birdmen from the south ambushing and burning caravans along the main roads. Guards from our outposts are requesting that we launch a counter attack against the main presence of Adherents of Rukhmar at Skettis in Spires of Arak.",objectivesText="Assault the arakkoa forces at Skettis in Spires of Arak. Progress: Da assault be goin' well I hope?",rewardGold=509400,rewardXP=1365,rewardCurrencies={{id=823,amount=800}},ends={{npcID=78495}},coords={mapID=590,x=0.41,y=0.508},questType="standard"},
[36689] = {id=36689,name="Assault on Pillars of Fate",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=7004,mapID=525,description="Remnants of the Shadowmoon clan continue to operate out of the peaks on the eastern border of Spires of Arak. Rokhan is concerned at their proximity to key choke points leading into Shadowmoon Valley, and has put out a request that we thin their forces as soon as possible.",rewardGold=509400,rewardXP=1365,rewardCurrencies={{id=823,amount=800}},ends={{npcID=78495}},coords={mapID=590,x=0.41,y=0.508},questType="standard"},
[36690] = {id=36690,name="Assault on Lost Veil Anzu",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=7004,description="Some of our best scouts have gone missing in the vicinity of the lost ruins of Veil Anzu. Rokhan has requested any available resources be dispatched to identify the threat and see if any of our men yet remain alive within the ruins.",objectivesText="Assault the hostile creatures at Lost Veil Anzu in Spires of Arak.",rewardGold=509400,rewardXP=1365,rewardCurrencies={{id=823,amount=800}},ends={{npcID=78495}},coords={mapID=590,x=0.41,y=0.508},questType="standard"},
[36691] = {id=36691,name="Assault on Socrethar's Rise",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=7004,description="Recent reports suggest a notable rise of activity by Sargerei forces at Socrethar's Rise in southern Shadowmoon Valley. Socrathar's disciples pose a threat all over Draenor. We must not allow them to gain a foothold so far from our reach.",objectivesText="Assault the Sargerei forces at Socrethar's Rise in Shadowmoon Valley.",rewardGold=509400,rewardXP=1365,rewardCurrencies={{id=823,amount=800}},ends={{npcID=78495}},coords={mapID=590,x=0.41,y=0.508},questType="standard"},
[36692] = {id=36692,name="Assault on Darktide Roost",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=7004,description="There's been a resurgence of rylaks on the battlefield in our skirmishes against the Iron Horde. If we don't stop them at the source, we'll quickly lose control of the roads and be pushed back into our outposts. The most likely source of these additional rylaks is in southeastern Shadowmoon Valley, at Darktide Roost. If we move quickly, we should be able to stop their operation cold.",objectivesText="Assault the Iron Horde forces at Darktide Roost in Shadowmoon Valley.",rewardGold=509400,rewardXP=1365,rewardCurrencies={{id=823,amount=800}},ends={{npcID=78495}},coords={mapID=590,x=0.41,y=0.508},questType="standard"},
[36693] = {id=36693,name="Assault on Mok'gol Watchpost",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=7004,description="Warsong raiders out of Mok'gol Watchpost have been terrorizing anything and everything not behind a tall wall. We've warned travelers not to stray out alone, but many don't listen. If we were to launch an assault on Mok'gol Watchpost, we would almost certainly put the Warsong back on the defensive, restricting most of their riders to Nagrand.",objectivesText="Assault the Warsong force at Mok'gol Watchpost in Nagrand.",rewardGold=509400,rewardXP=1365,rewardCurrencies={{id=823,amount=800}},ends={{npcID=78495}},coords={mapID=590,x=0.41,y=0.508},questType="standard"},
[36694] = {id=36694,name="Assault on the Broken Precipice",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=7004,description="Massive ogron have been battering our frontlines, and no matter how many we down, there seem to be more to replace them. Most of these ogron appear to be coming from the Broken Precipice , deep in western Nagrand. If we're to stand a chance in the coming battles, we need to find a way to remove these ogron from the battlefield.",objectivesText="Assault the ogron forces at the Broken Precipice in Nagrand.",rewardGold=509400,rewardXP=1365,rewardCurrencies={{id=823,amount=800}},ends={{npcID=78495}},coords={mapID=590,x=0.41,y=0.508},questType="standard"},
[36695] = {id=36695,name="Assault on the Everbloom Wilds",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=7004,description="Botani and the plant monstrosities they conjure have been slowly encroaching on our outposts in the north. For every plant we kill, new ones seem to rise in its place. Rokhan has put together a plan for striking at the heart of their lands, in Everbloom Wilds. He thinks this will draw them back into the jungles of Gorgrond, giving us more room to maneuver around them.",objectivesText="Assault the Botani forces in the Everbloom Wilds in Gorgrond. Progress: Da assault be goin' well I hope?",rewardGold=509400,rewardXP=1365,rewardCurrencies={{id=823,amount=800}},ends={{npcID=78495}},coords={mapID=590,x=0.41,y=0.508},questType="standard"},
[36696] = {id=36696,name="Assault on the Iron Siegeworks",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=7004,description="Iron Horde war machines are being shipped onto battlefields by the dozens, and our forces are struggling to hold their ground. Most of these machines seem to be originating from the Iron Siegeworks in eastern Frostfire Ridge. A strategic attack to disrupt and dismantle the Iron Horde at the siegeworks could be just what we need to turn the tide of the war.",objectivesText="Assault the Iron Horde forces at the Iron Siegeworks in Frostfire Ridge.",rewardGold=509400,rewardXP=1365,rewardCurrencies={{id=823,amount=800}},ends={{npcID=78495}},coords={mapID=590,x=0.41,y=0.508},questType="standard"},
[36697] = {id=36697,name="Assault on Magnarok",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=7004,description="Colossal magnaron, gronn, and other stone monstrosities have been threatening our garrison. Most seem to originate from Magnarok, just to the north. If we strike at them at their home, we should be able to force them back. It's risky, but it may be our best move. While you're there, see if you can recover any of our supplies.",objectivesText="Assault the stone monstrosities at Magnarok in Frostfire Ridge.",rewardGold=509400,rewardXP=1365,rewardCurrencies={{id=823,amount=800}},ends={{npcID=78495}},coords={mapID=590,x=0.41,y=0.508},questType="standard"},
[36698] = {id=36698,name="Battle in Ashran",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=7004,description="As we do battle all across Draenor, the cowardly Alliance try to seize our territory within Ashran. Our men would be inspired to see you join the battlefield, striking terror into the hearts of the Alliance.",objectivesText="Join the battle in Ashran.",rewardGold=679200,rewardXP=1365,rewardCurrencies={{id=823,amount=1000}},ends={{npcID=78495}},coords={mapID=590,x=0.41,y=0.508},questType="pvp"},
[36699] = {id=36699,name="Assault on the Heart of Shattrath",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=7004,description="Sargerei forces from deep in Shattrath have grown stronger and bolder by the day. We can no longer risk ignoring the threat that they pose. Bring allies if you wish to face the Sargerei so deep within the city.",objectivesText="Assault the Sargerei force in Shattrath City in Talador. Progress: Da assault be goin' well I hope?",rewardGold=679200,rewardXP=1365,rewardCurrencies={{id=823,amount=1000}},ends={{npcID=78495}},coords={mapID=590,x=0.41,y=0.508},questType="group"},
