[36701] = {id=36701,name="Assault on the Pit",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=7004,description="The Blackrock forces based out of the Pit in Gorgrond make up the bulk of the Iron Horde army. If we crush them on their home soil, the rest of the Iron Horde will have little hope of standing against us. If you choose the battle, bring friends. The Blackrock won't be defeated easily.",objectivesText="Assault the Blackrock forces at the Pit in Gorgrond. Progress: Da assault be goin' well I hope?",rewardGold=679200,rewardXP=1365,rewardCurrencies={{id=823,amount=1000}},ends={{npcID=78495}},coords={mapID=590,x=0.41,y=0.508},questType="group"},
[36702] = {id=36702,name="Meatball",level=40,requiredLevel=40,faction="both",expansion=5,zoneID=6298,mapID=109,rewardGold=169800,rewardXP=1365,starts={{npcID=86272}},ends={{npcID=86272}},questType="standard"},
[36705] = {id=36705,name="The Ring of Blood: Mogor!",level=1,requiredLevel=1,faction="alliance",expansion=5,zoneID=6755,mapID=550,description="You've really done it this time, champ. Mogor has challenged you to uphold his title as lord of the ring! I wish I could give you tips to help you make it out of there in one piece, but I've never seen Mogor fight. Nobody's ever gotten this far! Good luck.",objectivesText="Defeat Mogor in the Ring of Blood.",starts={{npcID=84783}},ends={{npcID=84783}},coords={x=0.568,y=0.13,source="quest_giver",zoneID=6755},questType="group"},
[36706] = {id=36706,name="Ashran Appearance",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=7333,mapID=525,description="Our base on Ashran is almost complete, commander. It would be a huge show of support if you could make a trip out there and put your stamp of approval on their staging area. I can arrange a flight if you are interested.",objectivesText="Speak with Private Stomphoof at Warspear in Ashran.",rewardGold=127350,rewardXP=1060,starts={{npcID=78466}},ends={{npcID=86315}},coords={x=0.488,y=0.65,source="quest_giver",zoneID=6720},questType="standard"},
[36707] = {id=36707,name="Warspear Welcome",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=7333,description="Lieutenant Kragil said you might be showing up. I've been ordered to take you to the inn.",objectivesText="Speak with Lieutenant Kragil .",rewardGold=13375,rewardXP=355,starts={{npcID=86315}},ends={{npcID=86312}},coords={x=0.452,y=0.346,source="quest_giver",zoneID=7333},questType="standard"},
[36708] = {id=36708,name="Inspiring Ashran",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=7333,description="I hope you will find our facilities to be up to your high standards. This inn is run by Narnin Dawnglow , in my opinion this is the best place to hearth in Draenor. We have new recruits coming through the portal daily. In fact one of out latest recruits, Zarjhin , just came through the portal today. If you are looking for weapons or armor Beska Redtusk will be happy to help.",objectivesText="Speak with Narnin Dawnglow , Beska Redtusk , and Zarjhin . Progress: How did your walk go?",rewardGold=127350,rewardXP=1060,starts={{npcID=86312}},ends={{npcID=86312}},coords={x=0.444,y=0.452,source="quest_giver",zoneID=7333},questType="standard"},
[36709] = {id=36709,name="Burning Beauty",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=7004,description="Before you go, there is someone you should meet. She might set some of your stuff on fire, but I believe she's the best mage this side of Draenor. She belongs on the front lines with you, commander.",objectivesText="Speak with Vivianne .",rewardGold=169800,rewardXP=1415,starts={{npcID=86312}},ends={{npcID=81765}},coords={x=0.444,y=0.452,source="quest_giver",zoneID=7333},questType="standard"},
