[36741] = {id=36741,name="Vintage Free Action Potion",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=8485,mapID=588,description="I hear our heroes in the front line are becoming victim to massive amounts of snares, roots and stuns! Luckily I have just the potion for them. The recipe is a little old, but it'll work. A key ingredient I need can be found here in Ashran , at the beach near that Ogre Tower.",objectivesText="Bring Gimlett Ginfizz 10 Ashmaul Pearls . Progress: Have you got the pearls, <name>?",rewardGold=339600,rewardItems={116925},starts={{npcID=85749}},ends={{npcID=85749}},questType="standard"},
[36742] = {id=36742,name="Vintage Free Action Potion",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=8485,mapID=588,description="The Alliance have increased their usage of snares, roots and stuns on our melee forces. Luckily I have just the potion for them. The recipe is a little old, but it'll work. A key ingredient I need can be found here in Ashran , at the beach near that Ogre Tower.",objectivesText="Bring Tyra Silverblood 10 Ashmaul Pearls . Progress: I need those pearls for the potion, did you find them <name>?",rewardGold=339600,rewardItems={116925},starts={{npcID=86366}},ends={{npcID=86366}},questType="standard"},
