[36790] = {id=36790,name="The Initiate's Revenge",level=30,requiredLevel=30,faction="both",expansion=5,zoneID=6722,mapID=542,description="I... I'm finished. My spirit will be with the Raven Mother soon. I beg of you, stranger... avenge me! Slay these filthy beasts.",objectivesText="Kill 18 Bloodmane Saberon.",rewardGold=169800,rewardXP=4115,starts={{npcID=86381}},ends={{npcID=80746}},coords={x=0.508,y=0.558,source="quest_giver",zoneID=6722},questType="standard"},
[36791] = {id=36791,name="Phantom Potion",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=8485,mapID=588,description="Every turn you take in Ashran you run into danger. But don't fret , I've developed the perfect solution. It's my very own riff on the popular Invisibility Potion. I'm just missing one of the ingredients: cave mushrooms. Luckily, a variety grows right here in Ashran .",objectivesText="Bring Gimlett Ginfizz 10 Ghost Truffles . Progress: Are those the truffles?",rewardGold=339600,rewardItems={114124},starts={{npcID=85749}},ends={{npcID=85749}},questType="standard"},
[36792] = {id=36792,name="Bladefist Hold",level=30,requiredLevel=30,faction="none",expansion=5,zoneID=6722,mapID=542,rewardGold=849000,rewardXP=4115,questType="world",db2Objectives={{orderIndex=2,type=0,amount=6,objectID=86524,text="Detonate Iron Grenades"}},worldTaskTitle="Bladefist Hold"},
[36794] = {id=36794,name="Vignette: Sylldross",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6721,mapID=543,questType="standard"},
[36798] = {id=36798,name="Rooby Roo",level=11,requiredLevel=11,faction="alliance",expansion=5,zoneID=6722,mapID=542,questType="standard"},
[36800] = {id=36800,name="Fire Ammonite Lunker",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=7078,objectivesText="Progress: Woooo daddy! Now that's a lunker <name>! I don't think I will ever get used to fishing in lava but nothing is really normal about this crazy place.",rewardXP=175,rewardItems={117397},starts={{npcID=85984}},ends={{npcID=85984}},coords={x=0.382,y=0.72,source="quest_giver",zoneID=7004},questType="standard"},
[36801] = {id=36801,name="One Step Ahead",level=20,requiredLevel=20,faction="alliance",expansion=5,zoneID=6662,mapID=535,description="Commander, Vindicator Maraad set off with Yrel and Thaelin Darkanvil to track the Iron Horde's movements in the nearby forest. They await your arrival on a small rise to the southwest.",objectivesText="Speak to Vindicator Maraad at Redemption Rise.",rewardGold=16980,rewardXP=345,starts={{npcID=86442}},ends={{npcID=75803}},coords={x=0.696,y=0.208,source="quest_giver",zoneID=6662},questType="standard"},
[36802] = {id=36802,name="Abyssal Gulper Lunker",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=7078,objectivesText="Progress: I'm surprised you made it back in one piece! Abyssal Gulpers are a delicacy to local Arakkoa in Spires of Arak.",rewardXP=175,rewardItems={117397},starts={{npcID=85984}},ends={{npcID=85984}},coords={x=0.382,y=0.72,source="quest_giver",zoneID=7004},questType="standard"},
[36803] = {id=36803,name="Blackwater Whiptail Lunker",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=7078,objectivesText="Progress: Those Draenei bother you over in Talador? I never fancied them fisherman but word is they are very territorial with local fishing spots. No matter, it looks like you got the prize this time!",rewardXP=175,rewardItems={117397},starts={{npcID=85984}},ends={{npcID=85984}},coords={x=0.382,y=0.72,source="quest_giver",zoneID=7004},questType="standard"},
[36804] = {id=36804,name="Blind Lake Lunker",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=7078,objectivesText="Progress: That's a fine Blind Lake Lunker you got there <name>. How long did you fight it? Fish like these don't come around very often, but when they do, it's a fight!",rewardXP=175,rewardItems={117397},starts={{npcID=85984}},ends={{npcID=85984}},coords={x=0.382,y=0.72,source="quest_giver",zoneID=7004},questType="standard"},
[36805] = {id=36805,name="Fat Sleeper Lunker",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=7078,objectivesText="Progress: Looks like you caught a Fat Sleeper Lunker there. Can't beat that river fishing in Nagrand, hoping to get out there soon myself.",rewardXP=175,rewardItems={117397},starts={{npcID=85984}},ends={{npcID=85984}},coords={x=0.382,y=0.72,source="quest_giver",zoneID=7004},questType="standard"},
[36806] = {id=36806,name="Jawless Skulker Lunker",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=7078,objectivesText="Progress: A Jawless Skulker Lunker ? Must have been fishing in Gorgrond then! I hear lots of things grow big out there...",rewardXP=175,rewardItems={117397},starts={{npcID=85984}},ends={{npcID=85984}},coords={x=0.382,y=0.72,source="quest_giver",zoneID=7004},questType="standard"},
[36808] = {id=36808,name="Assault on Shattrath Harbor",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=6662,objectivesText="Shadow Council Assaulted Defeat Minus Enemies Defeat Normal Enemies Defeat Lieutenant Enemies Defeat Miniboss Enemies Caches Siege Cannons Soul Crystals Fel Fires Arkonite Crystals Sha'tari Belongings Orc Bodies Captured Guards",coords={mapID=535,x=0.44,y=0.23},questType="standard",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Shadow Council Assaulted"},{orderIndex=1,type=0,amount=500,objectID=85197,text="Defeat Minus Enemies"},{orderIndex=2,type=0,amount=100,objectID=85000,text="Defeat Normal Enemies"},{orderIndex=3,type=0,amount=34,objectID=85195,text="Defeat Lieutenant Enemies"},{orderIndex=4,type=0,amount=4,objectID=85200,text="Defeat Miniboss Enemies"},{orderIndex=5,type=2,amount=20,objectID=234433,text="Caches"},{orderIndex=6,type=0,amount=45,objectID=84754,text="Siege Cannons"},{orderIndex=7,type=0,amount=50,objectID=83856,text="Soul Crystals"},{orderIndex=8,type=0,amount=50,objectID=84279,text="Fel Fires"},{orderIndex=10,type=0,amount=34,objectID=84997,text="Sha'tari Belongings"},{orderIndex=9,type=0,amount=10,objectID=85370,text="Arkonite Crystals"},{orderIndex=11,type=0,amount=100,objectID=85393,text="Orc Bodies"},{orderIndex=12,type=0,amount=34,objectID=85103,text="Captured Guards"}},worldTaskTitle="Assault on Shattrath Harbor"},
[36812] = {id=36812,name="Penny For Your Thoughts",level=15,requiredLevel=15,faction="horde",expansion=5,zoneID=6721,mapID=543,rewardXP=260,starts={{npcID=85077}},ends={{npcID=85077}},coords={x=0.464,y=0.696,source="quest_giver",mapID=543},questType="standard"},
[36813] = {id=36813,name="Subversive Infestation",level=35,requiredLevel=35,faction="both",expansion=5,zoneID=7109,description="As lord of the Everbloom my charge was the weaponization of nature. You have likely seen the fruits of my labor in your journeys across my world. My discoveries have allowed my kind to control the invasive species of Draenor through subversive infestation. I speak of total systemic control of the invading organism - the mind and the body. Now that you are my master I offer these gifts to you, but first you must retrieve my research and tools from the Everbloom . Do this and great power is yours.",objectivesText="Recover Phylarch's Research , Xeri'tac's Venom Gland , and 3 Depleted Everbloom Seeds from the Everbloom and return to Phylarch the Evergreen . Progress: Retrieve what I have asked for, master. I will show you the true strength of nature.",rewardGold=679200,rewardXP=1200,rewardItems={117398},starts={{npcID=84889}},ends={{npcID=84889}},coords={x=0.582,y=0.258,source="quest_giver",zoneID=7004},questType="dungeon"},
