[36843] = {id=36843,name="They Came From Above",level=20,requiredLevel=20,faction="both",expansion=5,zoneID=6662,mapID=535,description="Please, traveler, I need your help. Aruuna, my home, has been destroyed by the arakkoa. They swooped down from their spires and killed anyone who tried to escape. My family... did not make it out. My brother Barum stayed behind to find his daughter amidst the chaos. I beseech you, please, go to Aruuna and find Barum. He is the only family I have left.",objectivesText="Find Crystal-Shaper Barum near Aruuna in Talador .",rewardGold=16980,rewardXP=345,starts={{npcID=86522}},ends={{npcID=75896}},coords={x=0.674,y=0.422,source="quest_giver",zoneID=6662},questType="standard"},
[36844] = {id=36844,name="Your Second Leatherworking Work Order",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=7004,mapID=525,description="Place another work order with my assistant. Once it is complete, we will leave it out here for you to collect.",objectivesText="Place a work order, then collect it once it completes. Progress can be monitored through the Garrison Report pane accessible through the button on your minimap.",rewardGold=16980,rewardXP=175,ends={{npcID=78207},{npcID=79833}},questType="standard"},
