[36848] = {id=36848,name="Ogre Waygates",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=7004,description="Six unique gates exist in Draenor, built by ogre magi in ages past. We've discovered their potency has not diminished over the millennia. If you can collect enough ogre waystones to activate one of these ancient waygates, we can build a portal from your garrison to that location.",objectivesText="Collect 25 Ogre Waystones and use them to activate an Ogre Waygate in Draenor. Progress: Did you activate a waygate?",rewardGold=169800,rewardXP=1415,starts={{npcID=77367},{npcID=79836}},ends={{npcID=77367},{npcID=79836}},coords={x=0.39,y=0.588,source="quest_giver",zoneID=7078},questType="standard"},
