[36927] = {id=36927,name="Nemesis: Becoming Death",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=7004,description="You have chosen your quarry and surely soon they will feel your merciless wrath, but first you must venture out into the wilds of Draenor and rip out the still-beating heart of a worgen in mortal combat. Return here with your prize. Through the heart of your enemy the spirits will attune your senses, granting you second sight and keenness in hearing - all to stalk your prey and claim dominance.",objectivesText="Kill a Worgen Player in Player versus Player combat while in Draenor and retrieve their Worgen Heart . Progress: Have you recovered the heart of a worthy foe?",rewardGold=339600,rewardXP=1770,rewardCurrencies={{id=824,amount=50}},starts={{npcID=86629}},ends={{npcID=86629}},coords={x=0.516,y=0.584,source="quest_giver",zoneID=7004},questType="pvp"},
