[36995] = {id=36995,name="Boar Training: Riplash",level=15,requiredLevel=15,faction="alliance",expansion=5,zoneID=7078,description="That boar's seen it's share of combat out in Gorgrond , so it'll be a bit easier to train. We'll start off in it's home, as you've done with yer other beasties. See if the two of you can't take down the mighty raptor known as Riplash .",objectivesText="Defeat Riplash while riding your Boar-In-Training.",rewardGold=339600,rewardXP=2615,rewardCurrencies={{id=824,amount=20}},starts={{npcID=86973}},questType="standard"},
