[37305] = {id=37305,name="Bronze Victory",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=7078,mapID=539,objectivesText="Progress: Surrounded as we are, we cannot be weak. We must win every battle, and win them decisively.",rewardGold=43200,rewardXP=1365,rewardCurrencies={{id=823,amount=33}},starts={{npcID=88458}},ends={{npcID=88458}},coords={x=0.372,y=0.364,source="quest_giver",mapID=539},questType="standard"},
[37306] = {id=37306,name="Silver Victory",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=7078,mapID=539,objectivesText="Progress: The harder we beat our enemies, the less quickly they'll return.",rewardGold=168800,rewardXP=1365,rewardCurrencies={{id=823,amount=50}},starts={{npcID=88458}},ends={{npcID=88458}},coords={x=0.372,y=0.364,source="quest_giver",mapID=539},questType="standard"},
[37307] = {id=37307,name="Gold Victory",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=7078,mapID=539,objectivesText="Progress: The stronger our enemies, the more soundly we must beat them. With so much at stake, a single weak blow could prove disastrous. Lead us to great victory, Commander.",rewardGold=172800,rewardXP=1365,rewardItems={116980},rewardCurrencies={{id=823,amount=75}},starts={{npcID=88458}},ends={{npcID=88458}},coords={x=0.372,y=0.364,source="quest_giver",mapID=539},questType="standard"},
