[37332] = {id=37332,name="Fungal Bundle",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=6719,mapID=539,description="The umbraspore giant you killed seemed immune to the volatile spores in the area. Perhaps the odd growths you found all over its body contribute to its immunity. You grab a big, disgusting fungal lump in order to give it to the rangari for study.",objectivesText="Take the Curious Growth to Rangari Sheera at the Rangari Enclave in Shadowmoon Valley . Progress: What did you find, <class>?",rewardGold=339600,rewardXP=1770,starts={{npcID=82318}},ends={{npcID=81324}},questType="standard"},
[37333] = {id=37333,name="LFGDungeons - Draenor - Heroic Random - 1st",level=10,requiredLevel=10,faction="none",expansion=5,rewardGold=1018800,rewardXP=2830,rewardCurrencies={{id=824,amount=200}},questType="standard"},
[37335] = {id=37335,name="LFGDungeons - Draenor - Normal Random - 1st",level=10,requiredLevel=10,faction="none",expansion=5,rewardGold=679200,rewardXP=2830,questType="standard"},
[37416] = {id=37416,name="Feast of the Spires",level=30,requiredLevel=30,faction="horde",expansion=5,zoneID=6722,mapID=542,description="Boss-mon, I prepared a great feast for you right over dere. You should be havin' a bite or two before you be goin' out for da day. Trust me, you will feel much betta if you do!",objectivesText="Eat a Feast of the Spires at Axefall.",rewardGold=16980,rewardXP=515,questType="standard"},
[37417] = {id=37417,name="Feast of the Spires",level=30,requiredLevel=30,faction="alliance",expansion=5,zoneID=6722,mapID=542,description="Commander, I prepared a great feast for ye right over there. You should be have a bite o' two before you be go out fer the day. Trust me, it's good fer ya!",objectivesText="Eat a Feast of the Spires at Southport.",rewardGold=4320,rewardXP=515,questType="standard"},
