[37467] = {id=37467,name="The Walk of Shame",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=7334,mapID=630,description="The echoes of Nar'thalas still haunt me, and I cannot bear the pain of this accursed town any longer. I may still be able to get you closer to the Tidestone, however. We will need to skirt around the edge of town. Follow me.",objectivesText="Escort Prince Farondis around the edge of Nar'thalas.",rewardGold=202200,rewardXP=1415,starts={{npcID=88867}},ends={{npcID=88890}},coords={x=0.518,y=0.442,source="quest_giver",zoneID=7334},questType="standard"},
[37468] = {id=37468,name="Into the Academy",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=7334,mapID=630,description="The sunken structure on the other side of this bridge was once called Nar'thalas Academy: the center of magical studies in all of Azeroth. You should have seen her in her full splendor. The Tidestone should be locked up within. I dare not enter, but you - my champion - you go with my blessing.",objectivesText="Enter the halls of the Nar'thalas Academy.",rewardGold=91380,rewardXP=710,starts={{npcID=88890}},ends={{npcID=88890}},questType="standard"},
[37469] = {id=37469,name="The Tidestone: Shattered",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=7334,mapID=630,description="I suppose you can go in, then. The shattered pieces of the Tidestone of Golganneth are contained within the academy's eastern wing. Even as curator, I cannot attest to their condition, as I have not been in to inspect them in many millennia. Oh, young ? Please do not touch anything.",objectivesText="Collect the 5 Tidestone Shards . Progress: <The last remaining piece of the Tidestone lies before you.>",rewardGold=202200,rewardXP=1415,rewardItems={120401},starts={{npcID=89660}},ends={{npcID=89660}},questType="standard"},
[37470] = {id=37470,name="The Head of the Snake",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=7334,mapID=630,description="Those naga have the Tidestone shards, . They will soon be dragging them into their watery holes, away from our reach. It would be wise to take out their leaders before that happens.",objectivesText="Defeat Athissa . Progress: I... I can't believe it...",rewardGold=808800,rewardXP=2830,rewardItems={133019,133020,133022,133023,133024,133025,133026,133028,133052,133053,133055,133056,133057,133058,133059,133061},rewardChoices={133019,133020,133022,133023,133024,133025,133026,133028,133052,133053,133055,133056,133057,133058,133059,133061},starts={{npcID=89009}},ends={{npcID=91403}},coords={x=0.578,y=0.434,source="quest_giver",zoneID=7334},questType="standard"},
[37474] = {id=37474,name="Basics First",level=1,requiredLevel=1,faction="none",expansion=5,objectivesText="Speak with Audrey Burnhep in Stormwind City.",questType="standard"},
