[37481] = {id=37481,name="Bonus Objective: Kill Horde Leaders",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=8485,mapID=588,rewardGold=1698000,rewardXP=5465,questType="pvp"},
[37482] = {id=37482,name="Bonus Objective: Kill Horde Leaders",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=8485,mapID=588,rewardGold=3396000,rewardXP=5465,questType="pvp"},
[37483] = {id=37483,name="Captian's Whistle",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=8485,mapID=588,objectivesText="Bring Anne Dunworthy 100 Artifact Fragments for a Captian's Whistle. Progress: We've brought our best here to help the fight for Ashran . Bring me some of those Artifact Fragments and I'll give you a whistle to call a Captian to battle within the Road of Glory when you need them the most.",rewardGold=339600,rewardItems={118736},starts={{npcID=84173}},ends={{npcID=84173}},coords={x=0.446,y=0.74,source="quest_giver",zoneID=6941},questType="standard"},
[37484] = {id=37484,name="Captain's Whistle",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=8485,mapID=588,objectivesText="Bring Anne Dunworthy 100 Artifact Fragments for a Captian's Whistle. Progress: We've brought our best here to help the fight for Ashran . Bring me some of those Artifact Fragments and I'll give you a whistle to call a Captian to battle within the Road of Glory when you need them the most.",rewardGold=339600,rewardItems={118736},starts={{npcID=84473}},ends={{npcID=84473}},coords={x=0.45,y=0.278,source="quest_giver",zoneID=6941},questType="standard"},
[37486] = {id=37486,name="Nar'thalas Still Suffers",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=7334,mapID=630,description="They have not forgiven me. I cannot blame them. Past crimes aside, I am still their prince. Even in death, I will do what I can to protect my people. . Act as my champion. Find and defeat the creature that leads this naga attack against the people of Nar'thalas. After all these years, you - |5 , of all things - may be the instrument of my redemption.",objectivesText="Defeat Athissa . Progress: I will make it up to them. WE will make it up to them.",rewardGold=202200,rewardXP=1415,rewardItems={121487,132911},rewardChoices={121487,132911},starts={{npcID=88867}},ends={{npcID=88867}},coords={x=0.518,y=0.442,source="quest_giver",zoneID=7334},questType="standard"},
[37492] = {id=37492,name="A Rather Long Walk",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=7334,mapID=630,description="I'm concerned for Elder Aldryth. He went out for a walk about ten thousand years ago, and he has not returned. With these naga attacking, I fear he may be in danger! If you dare venture out into the fray, do look out for our court elder.",objectivesText="Find Elder Aldryth. Progress: Have you seen him?",rewardGold=202200,rewardXP=1415,starts={{npcID=88798}},ends={{npcID=88798}},coords={x=0.47,y=0.414,source="quest_giver",zoneID=7334},questType="standard"},
[37494] = {id=37494,name="Under Cover of Darkness",level=45,requiredLevel=45,faction="both",expansion=5,zoneID=1519,mapID=84,description="We are off to Stormwind. Tethys will sneak us by water beneath the old barracks under cover of darkness tonight. The rest will be up to you, Mathias, and myself. We will have to stealth through Stormwind and confront Detheroc at SI:7. Are you ready to do this, ?",objectivesText="Speak with Taoshi when you're ready for Fleet Admiral Tethys to arrange your transport to Stormwind City.",rewardGold=101100,rewardXP=3070,starts={{npcID=98100}},ends={{npcID=111049}},questType="standard"},
[37496] = {id=37496,name="Infiltrating Shipwreck Arena",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=7334,mapID=630,description="The giants at Shipwreck Arena are very fond of smashing ships that sail too close to shore. They take the sailors prisoner and use them for their own amusement. I suppose it will be easy for you to infiltrate the place. It's breaking out that will be the difficult part.",objectivesText="Infiltrate Shipwreck Arena and find Okuna Longtusk .",rewardGold=7150,rewardXP=1415,starts={{npcID=88798}},ends={{npcID=88873}},coords={x=0.47,y=0.414,source="quest_giver",zoneID=7334},questType="standard"},
[37497] = {id=37497,name="Trailing the Tidestone",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=7334,mapID=630,description="Your quest for the Tidestone... it intrigues me. More than that, it suits my needs quite well. I have been in need of a champion for a very, very long time. It is decided, then. I shall join you. We will have to head east, through Nar'thalas. Shall we depart?",objectivesText="Escort Prince Farondis to the Ruins of Nar'thalas.",rewardGold=202200,rewardXP=1415,starts={{npcID=88115}},ends={{npcID=88867}},coords={x=0.47,y=0.412,source="quest_giver",zoneID=7334},questType="standard"},
[37501] = {id=37501,name="Draenor Challenge Mode - Bronze Addition (1st)",level=40,requiredLevel=40,faction="none",expansion=5,rewardGold=169800,rewardXP=1365,questType="standard"},
[37502] = {id=37502,name="Draenor Challenge Mode - Consolation (1st)",level=40,requiredLevel=40,faction="none",expansion=5,rewardGold=169800,rewardXP=1365,questType="standard"},
[37503] = {id=37503,name="Draenor Challenge Mode - Gold Addition (1st)",level=40,requiredLevel=40,faction="none",expansion=5,rewardGold=169800,rewardXP=1365,questType="standard"},
[37504] = {id=37504,name="Draenor Challenge Mode - Silver Addition (1st)",level=40,requiredLevel=40,faction="none",expansion=5,rewardGold=169800,rewardXP=1365,questType="standard"},
[37505] = {id=37505,name="LFGDungeons - Draenor - Raid Finder - 1st",level=40,requiredLevel=40,faction="none",expansion=5,rewardGold=1698000,questType="standard"},
[37507] = {id=37507,name="Boss Whalebelly's in Charge",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=7334,mapID=630,description="Great, let's get started! If we're going to break everyone out of here, you need to pose as a pit fighter like the rest of us. They won't just let you run around anywhere you want in here. First thing you need to do is present yourself to Boss Whalebelly . The giants may run this place, but as far as posing as one of us, Whalebelly's in charge. He's speaking with his goons just to the south.",objectivesText="Speak with Boss Whalebelly . Progress: Go on. Go talk to him.",rewardXP=175,starts={{npcID=88873}},ends={{npcID=88873}},coords={x=0.5,y=0.486,source="quest_giver",zoneID=7334},questType="standard"},
[37510] = {id=37510,name="Sternfathom's Champion",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=7334,mapID=630,description="Since you defeated Ooker Dooker, there's a pit fighter spot open on Sternfathom 's team. You should go establish yourself as his champion. That way, the giants won't think twice about why a stranger is suddenly coming and going as pleases. Meanwhile, I'll start to sow some chaos so that we can strike at Prince Oceanus.",objectivesText="Report to Sternfathom as his new pitfighter.",rewardXP=175,starts={{npcID=88873}},ends={{npcID=88923}},coords={x=0.5,y=0.486,source="quest_giver",zoneID=7334},questType="standard"},
[37511] = {id=37511,name="Dizzy Sparkshift",level=40,requiredLevel=40,faction="both",expansion=5,zoneID=6755,mapID=550,description="I'm in a pretty good spot as far as artifacts go. We have a couple other society members out in the field. I'd go look for them, but it seems like a bad idea from a health perspective. You don't seem to have a problem with pain, think you could find Dizzy?",objectivesText="Find Dizzy Sparkshift .",rewardGold=339600,rewardXP=1365,starts={{npcID=83734}},ends={{npcID=76508}},coords={x=0.396,y=0.244,source="quest_giver",zoneID=6755},questType="standard"},
[37516] = {id=37516,name="News for Nixxie",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=7078,mapID=550,description="Nixxie is probably worried sick about the potential loss of profits from this surveying operation. If you see her can you let her know we will be back soonish?",objectivesText="Speak with Nixxie .",rewardGold=339600,rewardXP=1365,starts={{npcID=76508}},ends={{npcID=88892}},coords={x=0.406,y=0.13,source="quest_giver",zoneID=6755},questType="standard"},
[37517] = {id=37517,name="News for Nixxie",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=7078,mapID=550,description="Nixxie is probably worried sick about the potential loss of profits from this surveying operation. If you see her can you let her know we will be back soonish?",objectivesText="Speak with Nixxie .",rewardGold=339600,rewardXP=1365,starts={{npcID=76508}},ends={{npcID=88892}},coords={x=0.406,y=0.13,source="quest_giver",zoneID=6755},questType="standard"},
[37520] = {id=37520,name="Vileclaw's Claw",level=35,requiredLevel=35,faction="both",expansion=5,zoneID=6755,mapID=550,objectivesText="Progress: Vileclaw is feared throughout Nagrand as a vicious predator. While it is true that Vileclaw is one of the most dangerous raptors you'll ever encounter, she is also a savagely beautiful creature. Vileclaw must be preserved for future generations to behold! If you can bring me back one of her vicious claws, I'll make sure you get a cut of the profit!",rewardGold=339600,starts={{npcID=87706}},ends={{npcID=87706}},coords={x=0.502,y=0.412,source="quest_giver",zoneID=6755},questType="standard"},
[37523] = {id=37523,name="Assault on the Gorian Proving Grounds",level=40,requiredLevel=40,faction="none",expansion=5,description="The ogres at the Gorian Proving Grounds are rousing champions to turn against our forces in Nagrand. A decisive assault on their training grounds should prevent them from mustering the forces they need to stand against us, and will help remind them that we are not an enemy they want to make.",objectivesText="Assault the ogre forces at the Gorian Proving Grounds in Nagrand.",rewardGold=509400,rewardXP=1365,rewardCurrencies={{id=823,amount=800}},questType="standard"},
[37524] = {id=37524,name="Assault on the Gorian Proving Grounds",level=40,requiredLevel=40,faction="none",expansion=5,description="The ogres at the Gorian Proving Grounds be rousin' champions to turn against our forces in Nagrand. A decisive assault on their training grounds should prevent dem from musterin' the forces dey be needin' to stand against us, and will help remind them that we are not an enemy they want to be makin'.",objectivesText="Assault the ogre forces at the Gorian Proving Grounds in Nagrand.",rewardGold=929400,rewardXP=1365,rewardCurrencies={{id=823,amount=800}},questType="standard"},
[37526] = {id=37526,name="Farondis Murder Flag",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=7334,mapID=630,questType="standard"},
[37528] = {id=37528,name="Let Sleeping Giants Lie",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=7334,mapID=630,description="We're going to need a diversion to get close to Prince Oceanus. Are you thinking what I'm thinking? See Sleepy Dhow over there? He's guarding all of the weapons the giants take from our shipwrecks. We can use those weapons to arm the rest of the pit fighters that are held in the caves. All you have to do is get past that giant without waking him.",objectivesText="Collect the Giants' Stash of Weapons . Progress: As soon as I can, I'll arm the gladiators in Oceanus Cove.",rewardGold=202200,rewardXP=1415,rewardItems={120181},starts={{npcID=88873}},ends={{npcID=88873}},coords={x=0.5,y=0.486,source="quest_giver",zoneID=7334},questType="standard"},
[37531] = {id=37531,name="Tracking - See Closed Chest",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6719,mapID=539,questType="standard"},
[37536] = {id=37536,name="Morale Booster",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=7334,mapID=630,description="Things may look good from where you're standing, but, we're losing. However, do not fret, my little friend. You can help. Listen closely. Ooka Dooker , Ooker's sister, is back over yonder in the champions' cave making her world famous Fighter Chow. It'll do the trick and boost our team's morale. All you have to do is to convince her to hand it over.",objectivesText="Get the Fighter Chow from Ooka Dooker",rewardXP=175,rewardItems={133828},rewardChoices={133828},starts={{npcID=88923}},ends={{npcID=89048}},coords={x=0.48,y=0.486,source="quest_giver",zoneID=7334},questType="standard"},
[37538] = {id=37538,name="Round 1, Fight!",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=7334,mapID=630,description="All of my gladiators are out of commission! It's down to you, . Bilgerudder's going to pit his three champions against you.",objectivesText="Have Sternfathom throw you into the arena, defeat Boss Whalebelly , and then find Okuna Longtusk inside Oceanus Cove.",rewardGold=606600,rewardXP=1770,rewardItems={121436,121437,121438,121439,132899,132900,132901,132902},rewardChoices={121436,121437,121438,121439,132899,132900,132901,132902},starts={{npcID=89048}},ends={{npcID=89048}},questType="standard"},
[37540] = {id=37540,name="Essence of the Iron Conqueror",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=6662,mapID=535,description="Redeem your Essence of the Iron Conqueror with Lady Liadrin to select an armament of your choice.",objectivesText="Collect an Essence of the Iron Conqueror . Progress: Well met, <class>. I see you have a claimed a trophy in your recent battles.",rewardItems={120212,120213,120214,120215,120216},rewardChoices={120212,120222,120221,120213,120223,120217,120215,120225,120218,120214,120224,120219,120216,120226,120220},ends={{npcID=76804}},coords={mapID=535,source="quest_giver",x=0.5,y=0.485},questType="raid"},
[37541] = {id=37541,name="Essence of the Iron Vanquisher",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=6662,mapID=535,description="Redeem your Essence of the Iron Vanquisher with Lady Liadrin to select an armament of your choice.",objectivesText="Obtain an Essence of the Iron Vanquisher . Progress: Well met, <class>. I see you have a claimed a trophy in your recent battles.",rewardItems={120217,120218,120219,120220,120221},rewardChoices={120212,120222,120221,120213,120223,120217,120215,120225,120218,120214,120224,120219,120216,120226,120220},ends={{npcID=76804}},coords={mapID=535,source="quest_giver",x=0.5,y=0.485},questType="raid"},
[37542] = {id=37542,name="No Time for Tryouts",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=7334,mapID=630,description="We don't have time for you to go through a lengthy set of tryouts. But, fighting in the arena is our best chance at getting you in good with the giants. That kind-hearted giant over there that's losing against Bilgerudder is Sternfathom. If you were to defeat his hozen champion, you'd make yourself a spot on his team. Looks like Ooker Dooker 's taking a rest between bouts. Now's the time to deliver a good ol' monkey beatdown.",objectivesText="Deliver a beatdown to Ooker Dooker . Progress: By giving that hozen a good beating, you'll be making a spot for yourself in the arena. You don't have to kill him, though.",rewardGold=404400,rewardXP=1770,rewardItems={121490,121492,121494,132954},rewardChoices={121490,121492,121494,132954},starts={{npcID=88873}},ends={{npcID=88873}},coords={x=0.5,y=0.486,source="quest_giver",zoneID=7334},questType="standard"},
