[37563] = {id=37563,name="The Frostwolves Stand Ready",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=6720,mapID=525,description="Though we have lost much this day, the Frostwolves stand ready to uphold our pact with your people. To honor this agreement, some of my clan have asked to join your ranks and fight alongside your forces. Our numbers are strained so I ask that you chose only one. Speak with me when you have made your decision.",objectivesText="Choose a follower (either Greatmother Geyah, Kal'gor the Honorable, or Lokra) and then speak with Makar Stonebinder . Progress: Have you decided which orc to take with you?",rewardGold=16980,rewardXP=175,starts={{npcID=76730},{npcID=88147}},ends={{npcID=76730},{npcID=88147}},coords={x=0.762,y=0.55,source="quest_giver",zoneID=6720},questType="standard"},
[37565] = {id=37565,name="The Right Weapon for the Job",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=7334,mapID=630,description="<You and Okuna were going to arm the captives in here. The idea was to free them and cause as much chaos as possible. It's the only sure way to be able to get close to the prince. You still have the weapons. You're just going to have to be careful sneaking around the giants.>",objectivesText="Arm 25 Shipwrecked Captives .",rewardGold=202200,rewardXP=1415,rewardItems={118330},ends={{npcID=89051}},coords={mapID=630,source="quest_giver",x=0.534667,y=0.634667},questType="standard"},
[37566] = {id=37566,name="The Prince is Going Down",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=7334,mapID=630,description="! I knew you'd come. Quick, let me out of here and we'll take this giant down.",objectivesText="Free Okuna Longtusk and kill Prince Oceanus .",rewardGold=606600,rewardXP=2125,rewardItems={121440,121441,121442,121443,132936,141386},rewardChoices={121440,121441,121442,121443,132936},starts={{npcID=89051}},ends={{npcID=109334}},coords={x=0.534,y=0.63,source="quest_giver",zoneID=7334},questType="standard"},
[37568] = {id=37568,name="Your First Alchemy Work Order",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=7004,description="Now that the alchemy lab is complete, we can start producing alchemical catalysts for you. When you have the ingredients, please speak with my assistant to start the first work order.",objectivesText="Start and collect your first Alchemy work order at the Alchemy Lab. Progress: Yes?",rewardGold=16980,rewardXP=175,rewardItems={108996},starts={{npcID=79813}},ends={{npcID=79814}},coords={x=0.536,y=0.366,source="quest_giver",zoneID=7004},questType="standard"},
[37569] = {id=37569,name="Your First Blacksmithing Work Order",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=7004,description="Now that the forge is complete, we can start producing truesteel ingots for you. When you have the ingredients, please speak with my assistant to start the first work order.",objectivesText="Start and collect your first Blacksmithing work order at the Forge. Progress: Yes?",rewardGold=16980,rewardXP=175,rewardItems={108257},starts={{npcID=79867}},ends={{npcID=79817}},coords={x=0.48,y=0.322,source="quest_giver",zoneID=7004},questType="standard"},
[37570] = {id=37570,name="Your First Enchanting Work Order",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=7004,description="Now that the enchanter's study is complete, we can start producing draenic dust for you. When you have the ingredients, please speak with my assistant to start the first work order.",objectivesText="Start and collect your first Enchanting work order at the Enchanter's Study. Progress: Yes?",rewardGold=16980,rewardXP=175,rewardItems={115504},starts={{npcID=79821}},ends={{npcID=79820}},coords={x=0.48,y=0.326,source="quest_giver",zoneID=7004},questType="standard"},
[37571] = {id=37571,name="Your First Engineering Work Order",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=7004,description="Now that the engineering works is complete, we can start producing gearspring parts for you. When you have the ingredients, please speak with my assistant to start the first work order.",objectivesText="Start and collect your first Engineering work order at the Engineering Works. Progress: Yes?",rewardGold=16980,rewardXP=175,rewardItems={111366},starts={{npcID=79826}},ends={{npcID=86696}},coords={x=0.536,y=0.366,source="quest_giver",zoneID=7004},questType="standard"},
[37572] = {id=37572,name="Your First Inscription Work Order",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=7004,description="Now that the scribe's quarters are complete, we can start producing war paints for you. When you have the ingredients, please speak with my assistant to start the first work order.",objectivesText="Start and collect your first Inscription work order at the Scribe's Quarters. Progress: Yes?",rewardGold=16980,rewardXP=175,rewardItems={112377},starts={{npcID=79829}},ends={{npcID=79831}},coords={x=0.53,y=0.364,source="quest_giver",zoneID=7004},questType="standard"},
[37573] = {id=37573,name="Your First Jewelcrafting Work Order",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=7004,description="Now that the gem boutique is complete, we can start producing taladite crystals for you. When you have the ingredients, please speak with my assistant to start the first work order.",objectivesText="Start and collect your first Jewelcrafting work order at the Gem Boutique. Progress: Yes?",rewardGold=16980,rewardXP=175,rewardItems={115524},starts={{npcID=79832}},ends={{npcID=79830}},coords={x=0.478,y=0.32,source="quest_giver",zoneID=7004},questType="standard"},
[37574] = {id=37574,name="Your First Leatherworking Work Order",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=7004,description="Now that the tannery is complete, we can start producing burnished leather for you. When you have the ingredients, please speak with my assistant to start the first work order.",objectivesText="Start and collect your first Leatherworking work order at the Tannery. Progress: Yes?",rewardGold=16980,rewardXP=175,rewardItems={110611},starts={{npcID=79834}},ends={{npcID=79833}},coords={x=0.53,y=0.366,source="quest_giver",zoneID=7004},questType="standard"},
