[37625] = {id=37625,name="Assault on Magnarok",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=6720,mapID=525,objectivesText="Magnarok Assaulted Minus Mobs Killed Normal Mobs Killed High HP Normal Mobs Killed Collect (Minor) Elite Killed Miniboss/Event Killed 5man Boss Killed Collect Cragstomper",rewardGold=702000,rewardXP=685,rewardCurrencies={{id=823,amount=800}},questType="standard",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Magnarok Assaulted"},{orderIndex=1,type=0,amount=500,objectID=87507,text="Minus Mobs Killed"},{orderIndex=2,type=0,amount=100,objectID=87513,text="Normal Mobs Killed"},{orderIndex=3,type=0,amount=50,objectID=87514,text="High HP Normal Mobs Killed"},{orderIndex=4,type=3,amount=1000,objectID=87383,text="Collect (Minor)"},{orderIndex=5,type=0,amount=25,objectID=87512,text="Elite Killed"},{orderIndex=6,type=0,amount=7,objectID=87511,text="Miniboss/Event Killed"},{orderIndex=7,type=0,amount=5,objectID=87742,text="5man Boss Killed"},{orderIndex=8,type=0,amount=34,objectID=87510,text="Collect"},{orderIndex=9,type=0,amount=34,objectID=87333,text="Cragstomper"}},worldTaskTitle="Assault on Magnarok"},
[37644] = {id=37644,name="Mastering the Menagerie",level=1,requiredLevel=1,faction="alliance",expansion=5,zoneID=7078,description="You know the drill. Defeat the pets in the garrison, and I might have something for you.",objectivesText="Defeat the pets in the battle area. Progress: Any luck?",rewardItems={113558,113623,116378,118578,118598,118697,119434,119467,119468},starts={{npcID=85418}},ends={{npcID=85418}},coords={x=0.288,y=0.392,source="quest_giver",zoneID=7078},questType="standard"},
