[37678] = {id=37678,name="Hit the Books",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=7334,mapID=630,description="One problem with maintaining such a large arcane library is that the books often pick up an errant enchantment and start darting about on their own. These overmagicked books need to be destroyed before they cause any further damage. If you encounter any of these exasperating essays, please put them down. Quietly.",objectivesText="Destroy 3 Ancient Tomes . Progress: <The librarian sighs quietly.>",rewardGold=202200,rewardXP=1415,rewardItems={138840,138841,138842,138843,138844,138845,138846,138847},rewardChoices={138840,138841,138842,138843,138844,138845},starts={{npcID=89849}},ends={{npcID=89849}},questType="standard"},
