[38035] = {id=38035,name="A Royal Summons",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=7502,mapID=84,description="Well met, $p. I have come on behalf of King Anduin Wrynn. My crew is preparing for a special mission, and the king would like you to join us. Please review this official summons and, if you are satisfied, return with me to Stormwind Harbor.",objectivesText="Use the Royal Summons and follow Sky Admiral Rogers through the portal to Stormwind Harbor. Progress: Can we count on you?",rewardGold=20220,rewardXP=175,rewardItems={128687},starts={{npcID=96644}},ends={{npcID=96644}},coords={x=0.188,y=0.426,source="quest_giver",zoneID=1519},questType="standard"},
[38036] = {id=38036,name="Supplies From the Skies",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=7541,mapID=634,description="Are you feeling alright? Say 'ah.' Mishka attempts to depress your tongue with a damp twig.> Sorry... we are in desperate need of medical supplies here. The infirmary on the Skyfire was well-stocked, but it's all scattered to the winds now. Anything you can salvage from the wreck will save lives!",objectivesText="Gather 5 Skyfire First Aid Kits . Progress: Did you find anything?",rewardGold=202200,rewardXP=1415,rewardItems={123876},starts={{npcID=90783}},ends={{npcID=90783}},coords={x=0.336,y=0.508,source="quest_giver",zoneID=7541},questType="standard"},
