[38043] = {id=38043,name="Bleeding the Bleeding Hollow",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=6723,objectivesText="Bleeding Hollow Forces Thwarted",coords={mapID=534,x=0.22,y=0.5},questType="standard",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Bleeding Hollow Forces Thwarted"}},worldTaskTitle="Bleeding the Bleeding Hollow"},
[38044] = {id=38044,name="Bleeding the Bleeding Hollow",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=6723,mapID=525,description="The Bleeding Hollow provide significant reinforcement to the Iron Horde in Tanaan. From their home in Zeth'Gol they relentlessly pursue our scouts, disrupt our operations, and gather more power for Gul'dan's magic. We should consider a direct raid on Zeth'Gol to make them pull back their forces across the valley. This should give us some breathing room... for a time.",objectivesText="Assault the Bleeding Hollow at Zeth'Gol in Tanaan Jungle . Progress: Have you completed the raid, general?",rewardGold=509400,rewardXP=1365,rewardCurrencies={{id=1101,amount=600},{id=823,amount=2000}},ends={{npcID=90481}},coords={mapID=525,source="quest_giver",x=0.408,y=0.732},questType="standard"},
[38045] = {id=38045,name="Bleeding the Bleeding Hollow",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=6723,mapID=534,description="The Bleeding Hollow provide significant reinforcement to the Iron Horde in Tanaan. From their home in Zeth'Gol they relentlessly pursue our scouts, disrupt our operations, and gather more power for Gul'dan's magic. We should consider a direct raid on Zeth'Gol to make them pull back their forces across the valley. This should give us some breathing room... for a time.",objectivesText="Assault the Bleeding Hollow at Zeth'Gol in Tanaan Jungle . Progress: Have you completed the raid yet, general?",rewardGold=509400,rewardXP=1365,rewardCurrencies={{id=1101,amount=600},{id=823,amount=2000}},ends={{npcID=90309}},coords={mapID=534,source="quest_giver",x=0.585,y=0.602},questType="standard"},
[38046] = {id=38046,name="Battle At The Iron Front",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=6723,mapID=534,description="General, our troops are currently engaged in a conjoined assault at the Iron Front. The fight has been raging for some time now, and casualties are high. Report to the Iron Front and lend your strength to the war effort. I have no doubt that your presence on the battlefield will inspire the soldiers to victory!",objectivesText="Aid the Alliance and Horde assault at The Iron Front in Tanaan Jungle .",rewardGold=129600,rewardXP=1365,rewardCurrencies={{id=1101,amount=600},{id=823,amount=2000}},ends={{npcID=90309}},coords={mapID=534,source="quest_giver",x=0.585,y=0.602},questType="standard"},
[38047] = {id=38047,name="Battle At The Iron Front",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=6723,mapID=525,description="The war against the Iron horde rages on. Not far from here at The Iron Front, our warriors are engaged in mortal combat with the enemy. They fight tenaciously and with great fury, but the losses have been severe. Go to The Iron Front and show the enemy that we will not falter in this war. Show them that we fight as wolves!",objectivesText="Aid the Alliance and Horde assault at The Iron Front in Tanaan Jungle .",rewardGold=509400,rewardXP=1365,rewardCurrencies={{id=1101,amount=600},{id=823,amount=2000}},ends={{npcID=90481}},coords={mapID=525,source="quest_giver",x=0.408,y=0.732},questType="standard"},
[38051] = {id=38051,name="Battle At The Iron Front",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=6723,objectivesText="Battle Aided At The Iron Front Enemy Slain Large Enemy Slain Iron Horde Banner Destroyed Wounded Soldier Revived Schematics Burned Elite Enemy Slain Point Captured",coords={mapID=534,x=0.14,y=0.57},questType="standard",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Battle Aided At The Iron Front"},{orderIndex=3,type=0,amount=34,objectID=90371,text="Iron Horde Banner Destroyed"},{orderIndex=4,type=0,amount=25,objectID=90337,text="Wounded Soldier Revived"},{orderIndex=1,type=0,amount=100,objectID=90867,text="Enemy Slain"},{orderIndex=6,type=0,amount=13,objectID=90868,text="Elite Enemy Slain"},{orderIndex=2,type=0,amount=50,objectID=93035,text="Large Enemy Slain"},{orderIndex=5,type=0,amount=25,objectID=93014,text="Schematics Burned"},{orderIndex=7,type=0,amount=10,objectID=93036,text="Point Captured"}},worldTaskTitle="Battle At The Iron Front"},
[38052] = {id=38052,name="Boarded!",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=7541,mapID=634,description="Glad to see you survived the crash. Unfortunately, so did most of the enemy's boarding party. Just the thought of those monsters setting foot on my ship makes me sick. Wipe them out, $p. For my crew... For King Wrynn... For the Alliance!",objectivesText="Slay 8 Forsaken Bat-Riders or Forsaken Deathstalkers . Progress: There will be no peace with those monsters running free.",rewardGold=43200,rewardXP=1415,starts={{npcID=90749}},ends={{npcID=90749}},coords={x=0.336,y=0.51,source="quest_giver",zoneID=7541},questType="standard"},
[38053] = {id=38053,name="Assault and Battery",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=7541,mapID=634,description="We need to report our position to the Alliance navy ASAP! I am building a new transponder to send a distress signal, but I need a battery from the Skyfire's communications console. You'll find the console at the top of the ship - I just hope those undead haven't put their creepy, bony fingers on it yet!",objectivesText="Recover the Transponder Battery from Dread-Rider Malwick. Progress: I cannot build a new transponder without that battery!",rewardGold=202200,rewardXP=1415,rewardItems={122295,134554,134555,134556,134557,134558,134559,134560,134561},rewardChoices={134554,134555,134556,134557,134558,134559,134560,134561},starts={{npcID=90866}},ends={{npcID=90866}},coords={x=0.336,y=0.508,source="quest_giver",zoneID=7541},questType="standard"},
[38054] = {id=38054,name="Battle At The Iron Front",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=6723,objectivesText="Battle Aided At The Iron Front Enemy Slain Big Enemy Slain Iron Horde Banner Destroyed Wounded Grunt Revived Schematics Burned Points Captured Elite Enemy Slain",coords={mapID=534,x=0.14,y=0.57},questType="standard",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Battle Aided At The Iron Front"},{orderIndex=3,type=0,amount=34,objectID=90371,text="Iron Horde Banner Destroyed"},{orderIndex=4,type=0,amount=25,objectID=90337,text="Wounded Grunt Revived"},{orderIndex=1,type=0,amount=100,objectID=90867,text="Enemy Slain"},{orderIndex=7,type=0,amount=10,objectID=90868,text="Elite Enemy Slain"},{orderIndex=2,type=0,amount=50,objectID=93035,text="Big Enemy Slain"},{orderIndex=5,type=0,amount=25,objectID=93014,text="Schematics Burned"},{orderIndex=6,type=0,amount=13,objectID=93036,text="Points Captured"}},worldTaskTitle="Battle At The Iron Front"},
[38057] = {id=38057,name="The Lost Legion",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=7541,mapID=634,description="The heroic men and women of the 7th Legion stayed at the front of the ship to fight off storm drakes while the crew evacuated. None of them have returned. Please find them, $p!",objectivesText="Locate the missing 7th Legion Dragoons.",rewardGold=202200,rewardXP=1415,starts={{npcID=90783}},ends={{npcID=90783}},questType="standard"},
[38058] = {id=38058,name="Lightning Rod",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=7541,mapID=634,description="Put this on. Just up the hill you'll find the front half of the Skyfire - and the big nest of storm drakes it crashed into! We can use the energy from those drakes to charge the transponder. You'll have to incite them, of course, but the device should draw most of the power. The probability of you being electrocuted is well within acceptable parameters!",objectivesText="Charge the Transponder by absorbing Storm Drake lightning attacks.",rewardGold=202200,rewardXP=1415,starts={{npcID=90866}},ends={{npcID=90866}},coords={x=0.336,y=0.508,source="quest_giver",zoneID=7541},questType="standard"},
[38059] = {id=38059,name="Pins and Needles",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=7541,mapID=634,description="Hngghh! Nope, can't stand yet. It's all pins and needles. Small fries like this are usually no problem for the 7th, but we weren't prepared for their electrical attacks. Before I knew it, I was trapped in some kind of static field. Couldn't move a muscle until you came along. My comrades were carried deeper into the cave. Get 'em out before they become whelp chow!",objectivesText="Release 6 7th Legion Dragoons from static fields.",rewardGold=202200,rewardXP=1415,starts={{npcID=92414}},ends={{npcID=92414}},questType="standard"},
[38060] = {id=38060,name="Signal Boost",level=10,requiredLevel=10,faction="alliance",expansion=5,zoneID=7541,mapID=634,description="The Skyfire's starboard propeller came to rest on the cliffs overlooking our camp - we're gonna use it like a big antenna and push our distress signal so far that even Mekkatorque's alarm clock could pick it up! Unfortunately, it might attract some unwanted attention. We're braced for enemy contact down here at the camp - fire up that signal and be ready to defend the antenna!",objectivesText="Use the Skyfire Propeller to broadcast a distress signal, then hold out until help arrives.",rewardGold=276200,rewardXP=1415,rewardItems={129233,129234,129235,129236,129310,129311,129312,129313},rewardChoices={129233,129234,129235,129236,129310,129311,129312,129313},starts={{npcID=90866},{npcID=92556}},ends={{npcID=90749},{npcID=92557}},coords={x=0.336,y=0.508,source="quest_giver",zoneID=7541},questType="standard"},
