[38872] = {id=38872,name="The Dark Lady's Bidding",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=7541,mapID=634,description="Uh, are these guys friendlies? I guess it's a good sign they haven't tried to eat Duchess... yet. Anyway, I have orders. Nathanos caught up with the dark rangers, who were sent forward aboard the Oblivion on a secret mission from Lady Sylvanas herself! Unfortunately the Alliance caught wind of our plan, and now Greymane is attacking the outpost! We could really use you over there, . Duchess can take you there, just give me the word.",objectivesText="Meet with Nathanos Blightcaller in Dreadwake's Landing.",rewardGold=715,rewardXP=175,starts={{npcID=93624}},ends={{npcID=93603}},coords={x=0.6,y=0.512,source="quest_giver",zoneID=7541},questType="standard"},
[38873] = {id=38873,name="Clear the Deck!",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=7541,mapID=634,description="Our mission in Skold-Ashil will have to wait, - for now, we have more pressing matters to attend to. I had just recently arrived with reinforcements for our assault when Greymane's ship sailed in and began barraging our walls. We deployed our siege weapons, but their ground forces quickly overwhelmed us. If you can get to those catapults and take out the dogs manning the cannons, it may give us the window we need to push the attack!",objectivesText="Fire 4 Forsaken Catapults in Greymane's Offensive.",rewardGold=202200,rewardXP=1415,starts={{npcID=93603}},ends={{npcID=93603}},coords={x=0.55,y=0.724,source="quest_giver",zoneID=7541},questType="standard"},
[38876] = {id=38876,name="Assault on the Fel Forge",level=40,requiredLevel=40,faction="horde",expansion=5,zoneID=6723,description="The Iron Horde continue to bring in reinforcements from all over Draenor to reinforce their position at Hellfire Citadel. If we don't cut off the flow of supplies then we risk losing control of our plans in Tanaan. A strategic attack to the supply lines at Ironhold Harbor is just the thing to keep the Iron Horde on the defensive and maintain our momentum.",objectivesText="Assault the Iron Horde reinforcements at Ironhold Harbor in Tanaan Jungle.",coords={mapID=534,x=0.5,y=0.44},questType="standard",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Iron Horde Forces Thwarted"}},worldTaskTitle="Assault on the Fel Forge"},
[38877] = {id=38877,name="Assault on the Fel Forge",level=40,requiredLevel=40,faction="alliance",expansion=5,zoneID=6723,description="The Iron Horde continue to bring in reinforcements from all over Draenor to reinforce their position at Hellfire Citadel. If we don't cut off the flow of supplies then we risk losing control of our plans in Tanaan. A strategic attack to the supply lines at Ironhold Harbor is just the thing to keep the Iron Horde on the defensive and maintain our momentum.",objectivesText="Assault the Iron Horde reinforcements at Ironhold Harbor in Tanaan Jungle.",coords={mapID=534,x=0.5,y=0.44},questType="standard",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Iron Horde Forces Thwarted"}},worldTaskTitle="Assault on the Fel Forge"},
[38878] = {id=38878,name="Shielded Secrets",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=7541,mapID=634,description="Our goal lies within that vault, . I don't have time to explain in detail - just know that it is vital to the Forsaken that we succeed. The shieldmaidens have proven tenacious in their defense, but I believe there may be another way in. A chosen few of their order are allowed entrance, and I need you to find out how. In the town I have seen intricately engraved shields which I believe are passed down from these champions. The scenes they depict may be the key to passing into the vault.",objectivesText="Examine 6 Engraved Vrykul Shields in Skold-Ashil.",rewardGold=202200,rewardXP=1415,starts={{npcID=94227}},ends={{npcID=95611}},coords={x=0.568,y=0.662,source="quest_giver",zoneID=7541},questType="standard"},
[38882] = {id=38882,name="A New Life for Undeath",level=10,requiredLevel=10,faction="horde",expansion=5,zoneID=7541,mapID=634,description="It seems that you are full of surprises, . With the blessing of the Valkyra queen, you have opened a path that will shape the destiny of Azeroth. I invite you to bear witness, for today a new day dawns on the Forsaken!",objectivesText="Follow Sylvanas into the Vault of Eyir .",rewardGold=202200,rewardXP=1415,rewardItems={121568,121570,121572,129342,129343,129344,129345,141392,245411},rewardChoices={121568,121570,121572,129342,129343,129344,129345},starts={{npcID=94228}},ends={{npcID=95755}},questType="standard"},
[38886] = {id=38886,name="7.0 Val'sharah - Treasure 021 - Sleeper's Barrow - twh",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=7558,mapID=641,questType="standard"},
[38887] = {id=38887,name="7.0 Val'sharah - Bluffs - Vignette: Swiftflight - TRACKING - twh",level=0,requiredLevel=0,faction="both",expansion=5,zoneID=7558,mapID=641,questType="standard"},
[38888] = {id=38888,name="The Highmountain Tauren",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=7503,mapID=650,description="Ye've brought me a bit of interesting rocks to look at, . I've got a special assignment for ye, if ye're up for it. I hear stories about these tauren, up in Highmountain, who claim mastery over minin'. I don't know if they're as talented as you or me, but they've been minin' leystone longer. Pay 'em a visit. See what they have to say.",objectivesText="Report to Ronos Ironhorn in Highmountain.",rewardXP=175,starts={{npcID=93189}},ends={{npcID=93691}},questType="standard"},
[38889] = {id=38889,name="Adopting the Adorable",level=10,requiredLevel=10,faction="both",expansion=5,zoneID=7558,mapID=641,rewardGold=101100,rewardXP=355,rewardItems={128690},starts={{npcID=93677}},ends={{npcID=93677}},coords={x=0.528,y=0.874,source="quest_giver",mapID=641},questType="standard"},
