[44571] = {id=44571,name="Honor the Flame",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6662,mapID=535,description="The Midsummer Fire Festival is a time to honor the elements. The element of fire stirs passion within us all. Many times, that passion pours out into aggressive actions. But here, in this land, we focus our passion on reverence. We will honor the flame as tradition dictates. Will you honor the flame with us, ?",rewardGold=170800,rewardXP=100,rewardItems={23247},starts={{npcID=114489,x=0.434,y=0.718,zoneID=6662}},ends={{npcID=259862,x=0.435,y=0.718,zoneID=6662}},coords={x=0.434,y=0.718,source="quest_giver",zoneID=6662},questType="world",worldTaskTitle="Honor the Flame"},
[44572] = {id=44572,name="Honor the Flame",level=1,requiredLevel=1,faction="both",expansion=5,zoneID=6755,mapID=550,description="The Midsummer Fire Festival is a time to honor the elements. The element of fire stirs passion within us all. Many times, that passion pours out into aggressive actions. But here, in this land, we focus our passion on reverence. We will honor the flame as tradition dictates. Will you honor the flame with us, ?",rewardGold=170800,rewardXP=100,rewardItems={23247},starts={{npcID=114490,x=0.804,y=0.476,zoneID=6755}},ends={{npcID=259863,x=0.805,y=0.477,zoneID=6755}},coords={x=0.804,y=0.476,source="quest_giver",zoneID=6755},questType="world",worldTaskTitle="Honor the Flame"},
